const HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow, noarchive\">\n<title>つむぎ 変更管理台帳</title>\n<style>:root{color-scheme:light dark}html,body{margin:0;padding:0}</style>\n<style>\n  :root{\n    --bg:#f7f8fb; --panel:#ffffff; --ink:#171a21; --ink-2:#5a6072; --ink-3:#8a90a2;\n    --line:#e7e9f0; --line-2:#eef0f6; --accent:#4b53c4; --accent-soft:#eceef9;\n    --bug:#d6455f; --bug-soft:#fbe9ec; --feat:#0f8f7e; --feat-soft:#e2f3ef;\n    --imp:#c07a15; --imp-soft:#f8efdd; --ops:#7b8194; --ops-soft:#eef0f4;\n    --crit:#c0392b; --focus:#4b53c4;\n    --mono:ui-monospace,\"SFMono-Regular\",Menlo,Consolas,monospace;\n    --jp:\"Hiragino Sans\",\"Hiragino Kaku Gothic ProN\",\"Yu Gothic\",\"Noto Sans JP\",\"Meiryo\",system-ui,sans-serif;\n  }\n  @media (prefers-color-scheme:dark){\n    :root{\n      --bg:#0f1116; --panel:#171a22; --ink:#e9ebf2; --ink-2:#a2a8bb; --ink-3:#71778a;\n      --line:#262a36; --line-2:#20242e; --accent:#8b93ee; --accent-soft:#20233a;\n      --bug:#f0879a; --bug-soft:#2c1a20; --feat:#5fcdb6; --feat-soft:#152621;\n      --imp:#e0ad5e; --imp-soft:#2a2213; --ops:#9aa0b3; --ops-soft:#21242d;\n      --crit:#f0879a; --focus:#8b93ee;\n    }\n  }\n  :root[data-theme=\"light\"]{\n    --bg:#f7f8fb; --panel:#ffffff; --ink:#171a21; --ink-2:#5a6072; --ink-3:#8a90a2;\n    --line:#e7e9f0; --line-2:#eef0f6; --accent:#4b53c4; --accent-soft:#eceef9;\n    --bug:#d6455f; --bug-soft:#fbe9ec; --feat:#0f8f7e; --feat-soft:#e2f3ef;\n    --imp:#c07a15; --imp-soft:#f8efdd; --ops:#7b8194; --ops-soft:#eef0f4; --crit:#c0392b; --focus:#4b53c4;\n  }\n  :root[data-theme=\"dark\"]{\n    --bg:#0f1116; --panel:#171a22; --ink:#e9ebf2; --ink-2:#a2a8bb; --ink-3:#71778a;\n    --line:#262a36; --line-2:#20242e; --accent:#8b93ee; --accent-soft:#20233a;\n    --bug:#f0879a; --bug-soft:#2c1a20; --feat:#5fcdb6; --feat-soft:#152621;\n    --imp:#e0ad5e; --imp-soft:#2a2213; --ops:#9aa0b3; --ops-soft:#21242d; --crit:#f0879a; --focus:#8b93ee;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--jp);line-height:1.65;\n    -webkit-font-smoothing:antialiased;font-feature-settings:\"palt\" 1}\n  .wrap{max-width:1120px;margin:0 auto;padding:40px 22px 80px}\n  .tnum{font-variant-numeric:tabular-nums}\n\n  header.masthead{border-bottom:2px solid var(--ink);padding-bottom:18px;margin-bottom:26px}\n  .eyebrow{font-size:12px;letter-spacing:.22em;color:var(--accent);font-weight:700;margin:0 0 8px}\n  h1{font-size:clamp(26px,4vw,38px);margin:0 0 6px;letter-spacing:.01em;font-weight:800;text-wrap:balance}\n  .sub{color:var(--ink-2);font-size:15px;margin:0}\n  .meta{display:flex;flex-wrap:wrap;gap:8px 22px;margin-top:16px;font-size:12.5px;color:var(--ink-2)}\n  .meta b{color:var(--ink);font-weight:700}\n\n  .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:24px 0 28px}\n  .stat{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 16px;position:relative;overflow:hidden}\n  .stat .k{font-size:12px;color:var(--ink-2);font-weight:600;letter-spacing:.02em}\n  .stat .v{font-size:30px;font-weight:800;margin-top:2px;line-height:1}\n  .stat .u{font-size:12px;color:var(--ink-3);margin-left:3px;font-weight:600}\n  .stat::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--sc,var(--accent))}\n\n  .toolbar{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin-bottom:16px}\n  .chips{display:flex;flex-wrap:wrap;gap:7px}\n  .chip{font:inherit;font-size:12.5px;font-weight:600;padding:6px 13px;border-radius:999px;border:1px solid var(--line);\n    background:var(--panel);color:var(--ink-2);cursor:pointer;transition:.14s;display:inline-flex;align-items:center;gap:6px}\n  .chip:hover{border-color:var(--accent);color:var(--ink)}\n  .chip[aria-pressed=\"true\"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n  .chip .dot{width:8px;height:8px;border-radius:50%}\n  .chip.k-bug .dot{background:var(--bug)} .chip.k-feat .dot{background:var(--feat)}\n  .chip.k-imp .dot{background:var(--imp)} .chip.k-ops .dot{background:var(--ops)}\n  .search{margin-left:auto;flex:1;min-width:190px;max-width:320px}\n  .search input{width:100%;font:inherit;font-size:13.5px;padding:8px 13px;border-radius:9px;border:1px solid var(--line);\n    background:var(--panel);color:var(--ink)}\n  .search input::placeholder{color:var(--ink-3)}\n  :focus-visible{outline:2px solid var(--focus);outline-offset:2px}\n\n  .count-line{font-size:12.5px;color:var(--ink-2);margin:0 2px 10px}\n\n  .ledger{display:flex;flex-direction:column;gap:9px}\n  .row{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 16px 14px 18px;\n    position:relative;overflow:hidden}\n  .row::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--rc)}\n  .row.k-bug{--rc:var(--bug)} .row.k-feat{--rc:var(--feat)} .row.k-imp{--rc:var(--imp)} .row.k-ops{--rc:var(--ops)}\n  .row-top{display:flex;flex-wrap:wrap;align-items:center;gap:8px 10px;margin-bottom:7px}\n  .tag{font-size:11px;font-weight:700;padding:3px 9px;border-radius:6px;letter-spacing:.02em;white-space:nowrap}\n  .tag.k-bug{background:var(--bug-soft);color:var(--bug)} .tag.k-feat{background:var(--feat-soft);color:var(--feat)}\n  .tag.k-imp{background:var(--imp-soft);color:var(--imp)} .tag.k-ops{background:var(--ops-soft);color:var(--ops)}\n  .area{font-size:12px;color:var(--ink-2);font-weight:600;background:var(--line-2);padding:3px 9px;border-radius:6px}\n  .crit{font-size:11px;font-weight:800;color:#fff;background:var(--crit);padding:3px 8px;border-radius:6px;letter-spacing:.03em}\n  .date{margin-left:auto;font-size:12px;color:var(--ink-3);font-family:var(--mono)}\n  .cid{font-size:11.5px;color:var(--ink-3);font-family:var(--mono);background:var(--line-2);padding:2px 7px;border-radius:5px}\n  .title{font-size:15px;font-weight:700;margin:0 0 6px;letter-spacing:.01em}\n  .cf{display:grid;grid-template-columns:auto 1fr;gap:3px 12px;font-size:13px;color:var(--ink-2)}\n  .cf .lb{font-weight:700;color:var(--ink-3);font-size:11.5px;letter-spacing:.04em;padding-top:1px}\n  .cf .tx{color:var(--ink-2)}\n  .cf .tx b{color:var(--ink);font-weight:700}\n  .empty{text-align:center;color:var(--ink-3);padding:44px;font-size:14px}\n\n  section.block{margin-top:44px}\n  .block h2{font-size:18px;font-weight:800;margin:0 0 4px;display:flex;align-items:center;gap:9px}\n  .block h2::before{content:\"\";width:10px;height:20px;border-radius:3px;background:var(--accent)}\n  .block .lead{color:var(--ink-2);font-size:13.5px;margin:0 0 16px}\n  .todo{display:flex;flex-direction:column;gap:8px}\n  .titem{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:13px 15px;display:flex;gap:13px;align-items:flex-start}\n  .titem .st{font-size:11px;font-weight:800;padding:4px 9px;border-radius:6px;white-space:nowrap;margin-top:1px}\n  .st.plan{background:var(--accent-soft);color:var(--accent)}\n  .st.hold{background:var(--imp-soft);color:var(--imp)}\n  .st.done{background:var(--feat-soft);color:var(--feat)}\n  .titem .body b{display:block;font-size:14px;color:var(--ink);margin-bottom:2px;font-weight:700}\n  .titem .body span{font-size:12.5px;color:var(--ink-2)}\n  .titem .prio{margin-left:auto;font-size:11px;font-weight:700;color:var(--ink-3);white-space:nowrap}\n\n  .docs{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}\n  .doc{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:15px 16px}\n  .doc .h{font-weight:700;font-size:14px;margin:0 0 8px;display:flex;align-items:center;gap:8px}\n  .doc .h .n{font-family:var(--mono);font-size:12px;color:#fff;background:var(--accent);border-radius:5px;padding:1px 7px}\n  .doc ul{margin:0;padding-left:18px;font-size:12.8px;color:var(--ink-2)}\n  .doc ul li{margin:4px 0}\n  .doc .note{font-size:11.5px;color:var(--ink-3);margin-top:9px;padding-top:9px;border-top:1px dashed var(--line)}\n\n  footer{margin-top:48px;padding-top:18px;border-top:1px solid var(--line);font-size:12px;color:var(--ink-3)}\n  @media (max-width:560px){\n    .cf{grid-template-columns:1fr;gap:2px} .cf .lb{margin-top:6px}\n    .date{width:100%;margin-left:0;order:5}\n  }\n</style>\n</head>\n<body>\n\n<style>\n  .stats .stat{cursor:pointer;font:inherit;text-align:left;width:100%;transition:.12s}\n  .stats button.stat{border:1px solid var(--line);background:var(--panel)}\n  .stats .stat:hover{border-color:var(--accent);transform:translateY(-1px)}\n  .stats .stat[aria-pressed=\"true\"]{outline:2px solid var(--sc);outline-offset:1px;box-shadow:0 2px 10px rgba(0,0,0,.08)}\n  .chip.k-crit .dot{background:var(--crit)}\n  .chip.k-crit[aria-pressed=\"true\"]{background:var(--crit);border-color:var(--crit);color:#fff}\n  .stat-note{font-size:11.5px;color:var(--ink-3);margin:-14px 2px 22px;line-height:1.5}\n</style>\n<div class=\"wrap\">\n  <header class=\"masthead\"><p class=\"eyebrow\">変更管理台帳 ／ CHANGE LOG</p><h1>つむぎ 修正・機能追加の記録</h1>\n    <p class=\"sub\">いつ・どこを・なぜ直したかを記録し、不具合対応の証跡として残す一覧です。</p>\n    <div class=\"meta\"><span>対象システム <b>つむぎ（通所介護 管理アプリ）</b></span><span>記録期間 <b class=\"tnum\">2026-07-16 〜 09-07</b></span><span>総件数 <b class=\"tnum\" id=\"m-total\">340</b> 件</span><span>版 <b>rev. 5a9763c</b></span></div>\n  </header>\n  <div class=\"stats\">\n    <button class=\"stat\" data-mode=\"bug\" aria-pressed=\"false\" style=\"--sc:var(--bug)\"><div class=\"k\">バグ修正</div><div class=\"v tnum\">132</div></button>\n    <button class=\"stat\" data-mode=\"feat\" aria-pressed=\"false\" style=\"--sc:var(--feat)\"><div class=\"k\">機能追加</div><div class=\"v tnum\">79</div></button>\n    <button class=\"stat\" data-mode=\"imp\" aria-pressed=\"false\" style=\"--sc:var(--imp)\"><div class=\"k\">改善・調整</div><div class=\"v tnum\">129</div></button>\n    <button class=\"stat\" data-mode=\"crit\" aria-pressed=\"false\" style=\"--sc:var(--crit)\"><div class=\"k\">重大な不具合</div><div class=\"v tnum\">53</div><span class=\"u\">再掲・データ保全</span></button>\n  </div>\n  <p class=\"stat-note\">※ <b>バグ修正 42 ＋ 機能追加 42 ＋ 改善・調整 39 ＝ 123 件（総件数）</b>です。「重大な不具合 16」は<b>この中で特に重要なものの再掲</b>なので、足しても総件数にはなりません。各カード／下のボタンを押すと、その種類だけに絞り込めます（もう一度押すと解除）。</p>\n<div class=\"toolbar\"><div class=\"chips\" id=\"kind-chips\"><button class=\"chip\" data-mode=\"all\" aria-pressed=\"true\">すべて</button><button class=\"chip k-bug\" data-mode=\"bug\" aria-pressed=\"false\"><span class=\"dot\"></span>バグ修正</button><button class=\"chip k-feat\" data-mode=\"feat\" aria-pressed=\"false\"><span class=\"dot\"></span>機能追加</button><button class=\"chip k-imp\" data-mode=\"imp\" aria-pressed=\"false\"><span class=\"dot\"></span>改善</button><button class=\"chip k-crit\" data-mode=\"crit\" aria-pressed=\"false\"><span class=\"dot\"></span>重大のみ</button></div>\n    <div class=\"search\"><input id=\"q\" type=\"search\" placeholder=\"キーワードで絞り込み（例: 連絡帳 / 同期 / 計画書）\" aria-label=\"キーワード検索\"></div></div>\n  <div class=\"chips\" id=\"area-chips\" style=\"margin-bottom:16px\"><button class=\"chip\" data-area=\"all\" aria-pressed=\"true\">全領域</button><button class=\"chip\" data-area=\"利用者マスタ\" aria-pressed=\"false\">利用者マスタ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">26</span></button><button class=\"chip\" data-area=\"日誌\" aria-pressed=\"false\">日誌 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">3</span></button><button class=\"chip\" data-area=\"変更ログ\" aria-pressed=\"false\">変更ログ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"連絡帳\" aria-pressed=\"false\">連絡帳 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">21</span></button><button class=\"chip\" data-area=\"同期\" aria-pressed=\"false\">同期 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">20</span></button><button class=\"chip\" data-area=\"連絡\" aria-pressed=\"false\">連絡 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">5</span></button><button class=\"chip\" data-area=\"各種設定\" aria-pressed=\"false\">各種設定 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">8</span></button><button class=\"chip\" data-area=\"提供記録\" aria-pressed=\"false\">提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">15</span></button><button class=\"chip\" data-area=\"分析/提供記録\" aria-pressed=\"false\">分析/提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"LIFE加算\" aria-pressed=\"false\">LIFE加算 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">8</span></button><button class=\"chip\" data-area=\"分析\" aria-pressed=\"false\">分析 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">9</span></button><button class=\"chip\" data-area=\"分析個人/LIFE加算\" aria-pressed=\"false\">分析個人/LIFE加算 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"スケジュール/提供記録\" aria-pressed=\"false\">スケジュール/提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"ケアマネ連携\" aria-pressed=\"false\">ケアマネ連携 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">9</span></button><button class=\"chip\" data-area=\"ホーム\" aria-pressed=\"false\">ホーム <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"家族アプリ\" aria-pressed=\"false\">家族アプリ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">9</span></button><button class=\"chip\" data-area=\"計画書\" aria-pressed=\"false\">計画書 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">10</span></button><button class=\"chip\" data-area=\"体力測定\" aria-pressed=\"false\">体力測定 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"管理局\" aria-pressed=\"false\">管理局 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button></div>\n  <p class=\"count-line\" id=\"count-line\">表示 172 件 ／ 全 172 件</p>\n  <div class=\"ledger\" id=\"ledger\">\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"各種連絡の定型文が保存直後に消える(同期保護リストの漏れ)。網羅監査で定型文/ADL評価/お知らせ3種/休み連絡状態/下書き/勤務表を保護に追加+削除復活防止の墓石\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">各種連絡の定型文が保存直後に消える — 同期保護リストの漏れを網羅監査で一括是正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">定型文(generalFaxTemplates)がpull保持・push側idマージ・_savedAt刻印の全てから漏れており、保存直後のpull(クラウド丸ごと採用)で端末から消え、その状態の次のpushでクラウドからも消えていた(日誌データ消失と同構造)。</span><span class=\"lb\">対処</span><span class=\"tx\">網羅監査を実施し、刻印+push側マージ+pull保持に generalFaxTemplates/adlRecords/trashedAnnouncements を、pull保持に お知らせ3種(全体/個別/写真)を、pullオブジェクト保持に faxDataStore(キー単位_updatedAt)/generalFaxDraft(_updatedAt)/workSchedule(月×スタッフ_wsTs) を追加。idマージは和集合のため、定型文削除とADL評価削除に復活防止の墓石を追加。storeMembersは削除経路に墓石が無く対象外のまま(従来挙動)。upd-2026-0907b。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5a9763c</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"【恒久対策】全保存を即時クラウド送信に統一。options無しonSave 77箇所(削除・設定変更等)が端末内のみ保存だった穴を根絶(日誌真因の水平展開)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">【恒久対策】「端末内にだけ保存されクラウドに送信されない保存」をアプリ全体で根絶</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">handleSaveToCloudはoptions.manual/silent指定時のみクラウド送信し、無指定のonSave呼び出しが全画面に77箇所(削除・設定変更・記録操作等)。これらは端末内のみ保存で、次のmanual/silent保存に相乗りするまでクラウドに届かず、再読み込みやpullのタイミング次第で消える=前日の日誌データ消失(5a52c5e)と同型の穴。</span><span class=\"lb\">対処</span><span class=\"tx\">push条件を撤廃し全保存を即時クラウド送信に統一。成功トーストはmanualのみ(silent/無指定は静かに送信)・失敗通知は全保存で表示・_lastSyncも全保存で刻印。CASは直列化済みのため保存頻度増の自己衝突なし。upd-2026-0907a。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">be408d5</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由を大分類+詳細の2段入力に(体調不良/通院・受診/入院/本人・家族の都合/冠婚葬祭/天候/その他)。特記=「大分類（詳細）」形式・ランキングは大分類集計+詳細内訳表示\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-07</span></div>\n      <p class=\"title\">欠席理由を「大分類を選択→詳細を記入」の2段入力に — 欠席理由ランキングの分類精度向上(店舗要望)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">従来は自由文のため「発熱、咳がひどいから」等が1つずつ別枠で集計され、体調不良として括れなかった。欠席時の理由入力を大分類(体調不良/通院・受診/入院/本人・家族の都合/冠婚葬祭/天候/その他)の選択+詳細の自由記入に変更し、特記には「体調不良（咳がひどい）」形式で記録。提供記録の状態変更モーダルと月間スケジュールの欠席理由モーダルの両方に適用。分析の欠席理由ランキングは大分類で集計し、詳細は件数付き内訳(上位3件・ホバーで全件)を表示。過去の自由文もキーワード表で大分類に寄せて集計(複数分類にまたがる文は原文維持)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">be408d5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"【重大・真因】日誌の自動保存5経路がoptions無しでonSaveを呼び、クラウドへ一度も送信されていなかった(manual/silent指定時のみpushする仕様)。全てにsilent付与で即時送信に\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">【重大・真因】日誌の自動保存がクラウドに一度も送信されていなかった — 「まだ消える」の最終回答</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">handleSaveToCloudは options.manual(手動保存)/options.silent(自動保存) 指定時のみ即時クラウド送信し、無指定の保存は端末内のみ(旧debounce送信経路は撤去済みで存在しない)。日誌の自動保存5経路(編集1.5秒後・AM/PM切替時・日付移動時・自己修復再送・1日モードの送迎車適用)が全てoptions無しで呼んでおり、クラウドへ一度も送信されていなかった。遠隔診断ログ(diag_店舗行)で裏付け: 日誌編集中にsaveログが皆無・silent保存はsave→push-okが正常記録・手動保存ボタンの3件だけが16:08に着弾。</span><span class=\"lb\">対処</span><span class=\"tx\">5経路全てに{silent:true}を付与し即時クラウド送信に変更(silent=成功トースト無し・失敗時のみ通知)。upd-2026-0906d。なお同型のoptions無しonSaveは全画面で77箇所あり、既定でも送信する恒久対策を次で実施予定(未来の修正点に記録)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5a52c5e</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"運用\" data-text=\"遠隔調査基盤: 稼働版数の画面表示+同期診断ログ(syncLog)のクラウド自動送信(diag_店舗行)+push不許可理由の記録\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">運用</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">遠隔調査基盤を追加 — 稼働中アプリ版の常時表示+同期診断ログのクラウド送信</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「保存が届かない」端末を遠隔調査できるよう、①スタッフ画面左下にビルド焼き込みのアプリ版数を常時表示(今すぐ更新が効いたかスクショで確認可能) ②localStorageのみだった同期診断ログ(syncLog)の末尾60件を60秒ごとにapp_stateの別行(diag_店舗)へベストエフォート送信(端末タグ=端末名|版数・本体データと完全分離で失敗無害) ③保存時にpush不許可の理由(店舗切替中/読込未完/店舗不一致/実データ無し)を必ず記録。この基盤により本件の真因を配信から数分で特定できた。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6f060c3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"【重大・根本対策】日誌データ消失の根本原因=pullのdiaryLogs保持漏れ。15秒pullが日誌だけ古いクラウド値で丸ごと置換していた。保持マージ+再pushを追加\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">【重大・根本対策】日誌の入力が消える根本原因 — 15秒同期(pull)の日誌保持漏れ</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">15秒pullはクラウドを丸ごと採用する際、提供記録・他の記録配列・設定・利用者・月間シフトには「端末内が新しい分(push未達)を保持」する処理があるが、diaryLogs(日誌オブジェクト)だけ保持リストから漏れていた。保存のpush完了前にpullが重なると日誌がappDataごと古いクラウド値に巻き戻り、以後の自動保存が巻き戻った内容を保存し続ける。クラウド実データで裏付け: 8/28_AMは同セッションのdriver/carTimes/managerConfirmedのみ当日刻印で、直前に設定したpick/drop(送迎車)は8/28のまま=巻き戻り後の状態が保存された痕跡。8/21_PMの_savedAtは8/21 09:26のままで、当日の入力が同じ穴で消えていた(9/4報告の「AM/PM切替で入力が戻る」も同根)。自動保存の導入で保存頻度が上がり、露出が急増して顕在化した。</span><span class=\"lb\">対処</span><span class=\"tx\">pullにdiaryLogs保持を追加: push側(mergeStates)と同じ「キー単位_savedAt+項目単位_fieldTsで新しい方を採用」でマージし、保持が発生したら_mergedForPushで再pushしてクラウドへ追いつかせる。syncLogにpull-preserve(diaryLogs)を記録し発生を観測可能に。消えた過去の入力は復元不可(再入力を依頼)。upd-2026-0906b。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9de4b30</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"【重大】日誌の入力が消える(自動保存の古いスナップショット保存+dirtyガード消失による同期巻き戻り)。appDataRef土台化+_savedAt比較ガード+自己修復re-pushで修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">【重大】日誌で送迎時間を入力したら入力済みデータが消えた — 前日導入の自動保存と同期の競合</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前日(9/4)導入の自動保存に2つの穴があった。①setTimeout発火時のappDataは最大1.5秒古いクロージャで、その間に15秒同期(pull)が届いていると、届いたばかりのデータを古い状態で上書き保存し得た。②自動保存で「未保存(dirty)」状態がほぼ無くなり、「編集中は同期で画面を上書きしない」既存ガードが機能しなくなった。保存の直後に古いクラウドスナップショットのpullが届くと、入力済みの画面ごと古い内容に巻き戻り「消えた」ように見えた。</span><span class=\"lb\">対処</span><span class=\"tx\">①自動保存の土台をappDataRef(常に最新)に変更。②リモート適用ガードを追加: リモートの_savedAtがローカルの_savedAtより古い/保存済みログに対して空の場合は適用せず、画面を保持したまま最新内容を自動で再保存してクラウドに追いつかせる(自己修復)。約1日で修正(upd-2026-0906a)。ガードレールに「dirtyフラグの意味を変える変更は、dirtyを前提にした既存ガードを全て洗い出す」を追記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e3dfbbc</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎時間キーパッド3桁の時優先判定(132→13:2、859→08:59)。先頭2桁が23以下なら時と解釈\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-06</span></div>\n      <p class=\"title\">送迎時間キーパッド: 「132」が「01:32」になる — 時として成立する読み方を自動判定に</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">前日の「下2桁=分」固定の整形では、13:24を打つ途中の「132」が「01:32」と表示され誤解を招いた(扇橋指摘)。3桁入力は先頭2桁が時として成立(23以下)すれば時優先=「132」→「13:2」、成立しなければ時1桁+分2桁=「859」→「08:59」と判定。決定時の解釈も同じ判定に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e3dfbbc</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎車の割り当てが別の利用者に表示される(丸山様が徒歩・吉岡様に車)。行番号フォールバックが他人のIDキーを誤読。ID化以降は行番号フォールバック禁止(表示・モーダル・1週間前コピー)\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">送迎車の割り当てが別の利用者に表示される場合がある(徒歩の方に車が付く等) — 扇橋実地テスト指摘</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">送迎キーは2026-07-14に行番号→利用者IDへ変更済みだが、キーの無い利用者は行番号で読むフォールバックが残っていた。利用者IDは連番の小さい整数のため、行番号が別の利用者のIDと衝突し、他人の車/徒歩を誤読・誤表示していた(例: キー未保存の丸山様の行番号=徒歩設定のある別利用者のID)。1週間前コピーの解決処理にも同種の誤解釈があり、コピー先で別人に車が付き得た。</span><span class=\"lb\">対処</span><span class=\"tx\">ID化(7/15)以降の日付の日誌では行番号フォールバックを禁止(帳票表示 getSelectedCar・割り当てモーダル・1週間前コピー _resolvePrevPid の3箇所)。行番号解釈は7/14以前の旧データとマスタ未登録の手書き行のみに限定。過去日の表示ずれは割り当てを開いて設定し直せば解消(IDキーで上書き保存される)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"カレンダーの緑●/AM/PM印を「要確認が全て解消した日」基準に変更。空ログの印残り・8/27以前保存分のコピー未確認残骸で印が付かない問題を修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">カレンダーの印が「入力して消しただけの日」に残り、「入力済みの日」(8/3・8/6等)に付かない</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">印の判定が「ログに何かキーがあれば入力済み」だったため、入力して消した日誌(空値のキーだけ残る)にも印が付いた。逆に8/27以前に保存した日誌は、当時「手動保存してもコピー未確認フラグ(_sougeiPending)が消えない」仕様だったため残骸が保存されており、全部入力済みでも印が永久に付かなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">印の基準を「要確認バッジが全て解消した日」(迎え/送り・送迎時間・記録者・管理者確認まで完了)に変更し、要確認判定と完全に一致させた。8/27以前の日付では_sougeiPending残骸を無視する。凡例も「AM+PM完了」等に更新。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"休業日・半日休業のスロットは要確認バッジ/ホームお知らせ/サイドバーバッジの対象外。半日休業は営業側完了で緑●\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">休業に設定した日は日誌の「要確認」を出さない — 扇橋実地テスト指摘</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">休業日は担当職員も送迎も無いため、要確認バッジ・ホームの日誌お知らせ・サイドバーの日誌バッジを表示しない。半日休業(AM/PM指定)は休業側スロットだけを対象外にし、営業側が完了すればカレンダーに緑●が付く。判定はスロット別休業ヘルパー(diarySlotKyugyo)に共通化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の全自動保存(編集停止1.5秒)。AM/PM切替・日付移動で入力が戻る事故を防止。保存ボタン=コピー確認の意味は維持\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">日誌を全自動保存に — 保存ボタンを押さずにAM/PM切替すると入力前に戻る事故の防止</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">編集の手が1.5秒止まったら自動保存する。従来もAM/PM切替時・日付移動時に個別の自動保存はあったが、保存前の切替タイミングや同期の競合で入力が戻るケースが残っていたため、常時保存に変更。自動保存はコピー未確認フラグを消さない(=「内容を確認した」の意味は保存ボタン/該当欄の編集のみが持つ。カレンダー印・要確認バッジの意味を壊さない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-improve\" data-kind=\"improve\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎時間キーパッドの入力中表示を確定後と同じに(859→08:59)。旧表示は85:9で分かりにくかった\">\n      <div class=\"row-top\"><span class=\"tag k-improve\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">送迎時間キーパッド: 入力中も「08:59」のように確定後と同じ表示に — 扇橋実地テスト指摘</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「859」と押すと入力中は「85:9」と表示され、決定後に「08:59」になっていた。決定時の整形(下2桁=分・残り=時)と同じ解釈で入力中から表示するよう変更(2桁までは時を入力中なのでそのまま表示)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5f4407</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡\" data-text=\"各種連絡がReferenceErrorでクラッシュ(フックの宣言前pageCount参照・TDZ)。宣言後へ移動+連絡FAX2画面をE2E遷移テストに追加。緊急修正\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">【緊急】各種連絡が開けない(画面エラー) — 0904aの自動縮小フックの実装ミス</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同日朝の修正(f07b9d0)で入れた連絡事項の実測縮小フックを、依存する pageCount の宣言より前に配置したため、初期化前参照(TDZ)の ReferenceError で GeneralFaxView 全体がクラッシュしていた。休み連絡/各種連絡は画面遷移E2Eの対象外で、デプロイ前検査をすり抜けた。</span><span class=\"lb\">対処</span><span class=\"tx\">フックを宣言後へ移動して即日修正(約1時間で復旧)。再発防止として休み連絡・各種連絡をE2E画面遷移テストに追加(chromium+iPadの22件PASS)。「新しい画面ロジックを足すときは、その画面がE2E遷移テストに含まれているかを確認する」をガードレールに追記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">84f056f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡\" data-text=\"振替の休み連絡が振替先(出席日)にも表示・理由欄に振替表記。元日側のみ表示・理由は休み理由・振替日は連絡事項に時制つき自動記載。連絡事項の実測自動縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">振替の休み連絡の是正(元日側のみ表示・理由欄は休み理由)+連絡事項の実測自動縮小</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前日の「振替も休み連絡に表示」対応で、status=振替のレコード(=振替で出席する日)までカレンダーに載り、出席日にも休み連絡が表示され、開くと理由欄に「◯月◯日AM分振替」が出ていた。また連絡事項の自動縮小が文字数推定で、実際の枠寸法とズレてスクロールが残っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">表示は欠席(基本利用日で休んだ側)のみに戻し、振替の有無は欠席記録の「◯月◯日へ振替」表記から判定して「振替あり」バッジ表示。理由欄は休み理由のみ(未記入なら空欄)、振替日は連絡事項に「◯月◯日に振替予定です/振替いたしました」(現在基準で時制切替)を自動記載。連絡事項の縮小はscrollHeight実測で収まるまで自動調整に変更(休み連絡・各種連絡とも)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f07b9d0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"招待メール済みバッジをクラウド招待参照に。送信端末以外でも表示。supabaseListCmInvitesForStore。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-04</span></div>\n      <p class=\"title\">担当者カードに「招待メール済み・登録待ち(送信日)」を全端末で表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">招待メールの送信記録が送信した端末のローカルにしか残らず、他の端末では「閲覧登録なし」に見えていた。クラウドの招待テーブル(family_invites・メールアドレス一致・未使用・期限内)も参照して判定するようにし、どの端末でも「招待メール済み・登録待ち(◯月◯日 送信)」が表示される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f07b9d0</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"店舗ログイン/切替直後に前店舗の利用者名が一瞬見える(個人情報)。_sbStoreId不一致の間はオーバーレイでゲート。スタッフ選択画面の空表示も読み込み中表示に。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">ログイン直後に別店舗の利用者名が一瞬見える(扇橋で報告・個人情報) — 読込完了までのゲートを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">店舗ログイン/切替の直後、端末に残っていた前店舗のデータ(daycareAppData_v3)が新店舗の読込完了までの0.数秒だけ描画されていた。スタッフ選択画面も同様に、読込前は「メンバーなし」空画面→数秒後に突然スタッフが現れていた。</span><span class=\"lb\">対処</span><span class=\"tx\">手元データの店舗ID(_sbStoreId)がログイン中の店舗と一致しない間は「最新のデータを取得しています…」オーバーレイで全面ゲートし、前店舗の情報を画面に出さない。スタッフ選択画面には読み込み中スピナーを追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">377fd1c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"スタッフ削除×修正・編集から削除・1日ヘルプ・送迎車リセット・時刻検証・振替あり表示・連絡事項自動縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">スタッフ管理・日誌・休み連絡の改善7件(実地テストのフィードバック反映)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①スタッフ選択の×で日誌由来のスタッフが削除できなかった問題を修正(id直一致・同名同役職も連動削除)。②スタッフ切替の「編集」からも削除可能に(選択中スタッフは削除不可)。③日誌の「担当者を追加」は既定で「この日だけ(ヘルプ)」になり、その日の日誌にのみ表示・スタッフ切替や各種設定には出ない(35日で自動掃除)。恒常スタッフはチェックを外して追加。④送迎車割り当てに「全員を未設定にする(リセット)」(1週間前コピー後の作り直し用・適用まで未保存)。⑤到着/出発時間は00:00〜23:59のみ保存可。⑥「振替」も休み連絡カレンダーに表示(振替ありバッジ)+連絡文面に振替日を自動記載。⑦休み連絡/各種連絡の連絡事項は文量に応じて自動縮小し印刷と同じ見た目で入力できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">377fd1c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"データ取得中の自動リカバリ(3秒ごと再取得)・同一店舗の利用者切替は即表示・空データ上書き禁止ガード。手動再読み込み不要化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">「データを取得中」で手動の再読み込みが必要 — 自動リカバリ化と切替の即時表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「データを取得中」画面の間は3秒ごとにクラウドから自動で取り直す(従来は15秒の定期取得待ちで、手動の「再読み込み」を押させていた)。②利用者切替は同一店舗内ならデータをクリアせず即表示(従来は切替のたびに空にして最大15秒待たせていた)。③localStorage取り込みに「利用者が入っている状態を空データで潰さない」ガードを追加(別タブのログイン初期化を拾って表示中の画面が取得中に落ちる穴)。④取得中画面の文言を「自動で取得しています(操作は不要)」に変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3ba3298</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"PCでデータ取得中ループ・一瞬表示・チカつき・重い。スタッフ画面と同一localStorageキーの取り込み合いが原因。ポータル専用キーに分離。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">PCでケアマネページが「データを取得中」のまま進まない — スタッフ画面との端末保存の衝突が原因</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族/ケアマネポータルはスタッフ画面と同じ端末保存キー(daycareAppData_v3)を1.5秒ごとに読み直す設計で、同じブラウザにスタッフ画面のタブが開いていると、スタッフ側の保存(別店舗のデータ・別形状)を取り込み続けて閲覧中の利用者が見つからなくなり「データを取得中」ループ・一瞬だけ表示されて戻る・チカつき・巨大JSONの毎秒解析でブラウザが重い、が発生(Windows/Macで実害。ポータル単独のスマホでは起きない)。</span><span class=\"lb\">対処</span><span class=\"tx\">ポータルの端末保存を専用キー(tsumugiFamilyAppData_v1)へ完全分離(24箇所)。1.5秒ポーリングは中身が変わった時だけJSON解析する方式に軽量化。「データを取得中」画面のログアウトが利用者選択画面に化ける問題(セッション消去漏れ)も修正。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">09a3865</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"担当変更で旧担当の閲覧が残り新担当に付与されない。ログイン時完全整合(失効+基点repoint+残骸グループ掃除+重複排除)。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">担当を変更しても「前の担当者に見え続け・新しい担当者に付与されない」 — ログイン時の完全整合を実装</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①自己付与は「追加」のみで、担当から外れた分の失効は行っていなかった。②担当から外れた基点行(ログインIDの行)を停止するとログイン自体が死ぬ設計欠陥があった。③削除済みの旧テストアカウント(同一メール)のグループから複製が誤生成される穴が実際に発生(asaasa由来で境様担当3名分が旧パスワードのまま生成)。④同一利用者を指す行が併存すると切替に2回表示されうる。</span><span class=\"lb\">対処</span><span class=\"tx\">api/cm-provisionを完全整合化: 不足分の付与+担当外れ複製の停止+基点行は現担当利用者へ付け替え(担当0なら停止)+生きた基点の無い同メール別パスワードグループの複製を自動停止。スタッフ側エンジンにも同ルールを実装し、linkedAccountsは利用者id単位で重複排除。閲覧中の利用者が担当外れになった場合はログイン行の利用者へ自動移動。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">58de26b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"複製アカウントのinsertがrole値の制約で全滅していた真因。role=member統一・多段再試行・サーバー側付与API cm-provision 新設・アプリ版表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">利用者切替が出ない真の原因が判明 — 複製アカウントの作成が一度も成功していなかった(roleの値制約)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウドの実データ精査で「登録フォーム経由のアカウント作成(role=member)は全て成功、自動同期エンジン/自己付与の複製作成(role=caremanager)は導入以来一度も成功していない」ことを確認。DB側のrole列の許容値制約に弾かれ、担当変更でエンジンに明確なトリガーがあった時刻(11:50)ですら複製が作られていなかった。前日までに直した「古いタブ」「5分tick」「担当欄の巻き戻り」は実在した別問題だが、これが最後の関門だった。</span><span class=\"lb\">対処</span><span class=\"tx\">①複製もrole='member'に統一(種別判定はkind/relation)。②insertをDB制約差異吸収の多段再試行に(role許容値→記号なしID→role列default)。③サービスキーで確実に付与するサーバーAPI(/api/cm-provision)を新設し、ログイン時/起動時はAPI優先・不達時のみクライアント処理。④起動時付与用の認証情報をsessionStorage保持(15秒pullで平文パスワードが失われる穴)。⑤ポータルに「アプリ版」表示を追加し、今後のスクショで実行中の版を即断できるように。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">22e970f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"担当を変更で設定した担当ケアマネが他端末の保存で巻き戻り消失(項目保護なし)。cm系を_fieldTs保護に追加。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-03</span><span class=\"tag k-crit\">重大</span></div>\n      <p class=\"title\">「担当を変更」で設定した担当ケアマネが消える — 項目単位保護の対象外だった(試作店で実例)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者の担当ケアマネ欄(cmOffice/cmName等)は項目単位時刻(_fieldTs)の保護対象外で、別端末(家族/ケアマネポータル含む)が古いスナップショットでその利用者を保存すると担当情報だけ巻き戻って消えた。試作店では大和田様の担当欄がクラウド上から完全に消失しており、担当一致で決まるケアマネの閲覧付与も1名分作られなかった。</span><span class=\"lb\">対処</span><span class=\"tx\">cmOffice/cmName/cmPhone/cmFax/cmHistoryを保存時刻印(_PT_FL)とマージ保護(PATIENT_FIELDLEVEL)の両方に追加。家族側マージ(supabaseMergePatientFromFamily)のcm系更新にも刻印。既に消えた分はスタッフ端末の次回保存の空欄補完で復元される見込み(表示されない場合は「担当を変更」で再設定)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fb622f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"ポータルの開きっぱなしタブが旧JSのまま動き修正が反映されない→ログイン画面で自動再読み込み。起動時自己付与。切替ボタンが一度で消えるバグ。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-03</span></div>\n      <p class=\"title\">修正を配信してもケアマネの利用者切替が出ない — ポータルの「古いタブ」問題と切替ボタンの消失を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①家族/ケアマネポータルにはスタッフ画面の「今すぐ更新」バナーが無く、開きっぱなしのタブはログアウト/ログインを繰り返しても配信前の古いJSのまま動く。前日配信の「ログイン時自己付与」が本人の端末で一度も実行されていなかった(クラウド実データの精査で、担当2名分のうち1名分のアカウントが未作成のままと確認)。②さらに利用者切替で一度選択するとリンク一覧を消す実装で、2回目以降の切替ボタンが消える既存バグもあった。</span><span class=\"lb\">対処</span><span class=\"tx\">①ログイン画面表示中にupdate-notes.jsonのversionをバンドル焼き込み値と比較し、違えば一度だけ自動再読み込み(ループ防止ガード付き・入力中データの無い画面のみ)。②ログイン済みケアマネの起動時にも自己付与を実行し、増えた担当をその場で利用者切替に反映。③切替の選択後もリンク一覧を保持(ログアウト時に消去)。④自己付与のinsert失敗をconsole.warnで可視化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fb622f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"パスワード変更後も旧パスワードでログインできた(mac/ipad)。認証エラー時のローカルフォールバック禁止。セキュリティ\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">パスワード変更後も以前のパスワードでログインできてしまう(Mac/iPadで確認) — 認証の抜け道を閉鎖</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族/ケアマネのログインはSupabase照合が本線だが、照合に失敗すると端末内に残る古い控え(平文パスワード時代のアカウント情報)で通すフォールバックがあった。パスワード変更は他端末の控えまで書き換えないため、変更前に一度でもログインした端末では旧パスワードが通り続けた(Macでの「ログイン後もデータ取得中のまま・切替なし」も、この控えログインが原因で正規の閲覧付与が走らなかったもの)。</span><span class=\"lb\">対処</span><span class=\"tx\">Supabaseが「IDまたはパスワードが違います」と明確に判定した場合はローカルの控えでのログインを禁止し、そのままエラー表示(本部管理者のプレビューはSupabaseスタッフ認証を先に確認する形で維持)。控えでのログインは通信障害でSupabaseに到達できない場合のみに限定。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3716101</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"複数利用者の切替が出ない: ログイン時自己付与supabaseSelfProvisionCm。新規登録のサービス提供内容タブ遷移漏れ。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">ケアマネの複数利用者切替が登録後も出ない — ログイン時の閲覧自己付与を新設(+新規登録のタブ遷移漏れ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">閲覧付与を作る自動同期エンジンは店舗スタッフの端末が開いているときしか動かず、5分定期tickを足しても「店舗端末が閉じている夜間などに登録したケアマネ」には付与されない穴が残っていた。</span><span class=\"lb\">対処</span><span class=\"tx\">ケアマネ本人のログイン成功時に、店舗データから担当利用者を特定して不足分の閲覧アカウントをその場で自動付与する supabaseSelfProvisionCm を新設(メール一致または事業所+氏名一致1名のみ・退所済み除外・担当外れ分は復活させない)。付与後は自動で再ログインし、初回ログインから利用者切替に全員が表示される。あわせて利用者マスタの新規登録で「登録してサービス提供内容へ」を押しても画面が移動しない問題(タブ切替の指定漏れ)を修正。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3716101</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"自己リセット3回化・ID+メール不一致表示・新パスワード表示切替・招待経由の事業所固定。パスワード\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">パスワード自己リセットと登録フォームの改善4点(実地テストのフィードバック反映)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①確認コードの試行上限を5回→3回に変更(メール文面・画面表記も統一)。②ログインIDとメールアドレスの組み合わせが登録と一致しない場合、次の画面へ進めず「どちらかが間違っています」をその場に表示(送信の成否フラグを応答に追加。第三者への情報漏えいには当たらない範囲で利便性を優先)。③パスワード変更画面の新しいパスワードに「表示/非表示」切替を追加。④招待メール経由のケアマネ登録は事業所をデイサービス側の登録内容で固定表示に変更(誤りは店舗で修正のうえ再招待する運用)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3716101</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"アカウント管理10秒更新の不一致ループで全画面チカチカ(家族/ケアマネポータル含む)。射影比較+保持マージで修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">画面が10秒ごとにチカチカする(ケアマネからクレーム) — アカウント管理の更新ループが原因</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アカウント管理モーダルの10秒ポーリングが「現在値とSupabase取得値のJSON丸ごと比較」で、(1)取得順が毎回変わる (2)ローカル側だけが持つ項目(cm招待のcmOffice/cmName・実パスワード等)がある、の2点により毎回不一致→10秒ごとにonSave(全体保存)→全画面再描画+クラウド書込→他端末・家族/ケアマネポータルのpull→再描画、というループ。副作用としてcm招待の追跡情報と実パスワードがサーバー形(****)で上書きされる問題も併発。</span><span class=\"lb\">対処</span><span class=\"tx\">共有項目のみをid昇順に射影して比較し、同一ならスキップ。保存時はローカル項目を保持したままサーバー値を重ねるマージに変更(実パスワードは****で潰さない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8bd889e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"担当者招待の登録フォーム自動入力(氏名/かな/事業所)・閲覧自動同期の5分定期起動。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">担当者招待の登録フォームに氏名・ふりがな・事業所を自動入力/閲覧自動同期に5分定期起動を追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①招待トークンに担当者マスタの姓名/ふりがな/事業所を同梱(cl/cf/kl/kf/co)し、登録フォームのご登録者情報と事業所選択を自動入力(ローカル招待レコードのcmName/cmOfficeからも復元)。②閲覧自動同期エンジンは担当データの署名変化でしか起動せず、ケアマネ登録直後(Supabase側のみ変化)に動かない穴があった→5分間隔の定期tickで強制再評価。複数担当の付与は登録後最大5分+再ログインで反映。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8bd889e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"メモリクラッシュ(コード5)再発対策: pull由来の端末保存を10秒間引き。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">長時間使用でブラウザがクラッシュ(エラーコード5)する再発への対策 — 端末保存の間引き</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pullでappDataが更新されるたびに写真込みの巨大JSONを全量JSON.stringifyしてlocalStorageへ保存しており、数秒おきの直列化によるGC負荷が長時間で蓄積しレンダラークラッシュを誘発(8/30のメタ先読み対策後も、保存側の負荷が残っていた)。</span><span class=\"lb\">対処</span><span class=\"tx\">ローカル編集は従来どおり即保存のまま、pull由来の端末保存だけ10秒に1回へ間引き(クラウドが正のため控えの鮮度低下は無害)。ビルド+E2E9件PASS確認の上デプロイ。経過観察: 発生端末で?syncdebug=1を外した通常URLでも再発するかを確認。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ff88214</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"サイドバーのホームに未読なしでも1が常時表示(江古田)。お知らせ母集合のズレを一覧と統一。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">未読が無いのにサイドバー「ホーム」に1が表示され続ける(江古田店で報告)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サイドバーの未読数(_homeUnreadCount)の運営お知らせ分が、ホームの一覧(本部+ライブ更新+組み込みを重複排除→日付降順→上位50件)と別の母集合(ライブ抜き・50件制限なし)で計算されていた。お知らせ総数が50件を超えると、一覧から溢れた古い組み込み告知が「画面から読む手段が無いのに未読として数え続けられる」状態になり、既読にしていなかった店舗で1が固定表示された。</span><span class=\"lb\">対処</span><span class=\"tx\">バッジの母集合を一覧と完全に同一へ統一(同じ重複排除・降順・50件制限・isNoticeRead基準)。devUpdateNotes(ライブ更新)定義後に計算を移動。ホームのお知らせで「新着なし」ならバッジも0になる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a6e5dab</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"個別運動×でも割当ありだと○表示。CI初回の単体テストが検出した実バグ。E2E基盤の初回赤も修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-09-02</span></div>\n      <p class=\"title\">連絡帳向け表示: 個別運動が「×(実施しなかった)」でも○と表示される — CI初回実行の単体テストが検出</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">resolveIndividualExerciseValueのcircleモードが、項目割当(itemId)がある枠は×でも○を返していた。既存の単体テスト(logic.test.js)は正しい仕様(×→非表示)を主張していたが、ローカルにnode環境が無くこれまで一度も実行されていなかった。E2E基盤構築で初めてCIが回り検出。</span><span class=\"lb\">対処</span><span class=\"tx\">×/✕/xは割当の有無に関わらず非表示(null)へ修正(空欄/ーは従来どおり割当あり=規定値実施の○を維持)。単体テスト15件PASS。あわせてCI初回赤の他要因も修正: vitestの対象をsrcに限定(e2e/の誤検出防止)・Supabase未設定時の起動ブロックにVITE_E2E_DEMO=1(CI専用)例外を追加しローカルモードで画面テスト可能に・CIにwebkit(iPad)取得を追加。手元検証でchromium/iPadとも9件全PASS。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a6e5dab</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"システム\" data-text=\"自動E2Eテスト基盤(Playwright+GitHub Actions・ローカルモード・毎push実行)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">自動E2Eテスト基盤 — pushのたびにCIでブラウザ操作テストを無人実行(Playwright+GitHub Actions)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">.github/workflows/e2e.yml: push(stable-rebuild)ごとに vitest単体テスト→Supabase環境変数なしでビルド(=ローカルモード・ログイン不要・実データゼロ)→vite preview起動→Playwrightスモーク実行。テスト内容(第1弾): 起動白画面/未捕捉エラー検知・主要6画面(提供記録/連絡帳/日誌/利用者マスタ/ケアマネ/各種設定)の遷移クラッシュ検知・日誌AM/PM切替・ケアマネ追加ポップアップ開閉。Chrome+iPad横持ちの2プロファイル。失敗時はHTMLレポート保存+GitHub通知メール。今後テスト項目一覧の画面操作系を段階的に自動化しスモークの大半を毎デプロイ自動に。手動で残るのは同期異常系(2端末/通信断)と実機系(印刷/FAX/実メール)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6263a31</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"起動2段階取得: 直近75日を先行表示・全量は裏で統合。データ増加への恒久耐性。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">起動(再読み込み)を2段階取得に — 直近75日分を先に表示し、過去分は裏で統合</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">fetchTicketRecordsRecent(rec_date>=今日-75日・最大5000件)を新設し、boot冒頭で直近分を取得→applyRows(項目時刻つき冪等マージ)で即反映→操作可(オーバーレイ解除)。その後従来の全量取得(1970〜)で過去分を統合(直近分はマージで保持)。「再読み込み直後の空欄時間」への恒久対策で、記録が何年分に増えても初期表示の待ちは直近分の件数(店舗あたり数百行)で一定。直近先行取得の失敗は全量取得でリカバリーされ致命的でない。将来の課題(V3候補): 全量の裏取得も月別オンデマンド化すれば通信量も一定化できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8331fbf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"再読み込み直後に提供記録が空欄→数秒後復活(容量超過店舗の軽量保存が記録を丸ごと除外)。直近45日保持+オーバーレイ20秒。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">再読み込み直後に提供記録が全欄空→数秒後に復活(扇橋店・容量超過時の軽量保存が原因)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">localStorage容量超過の店舗は軽量保存(persist-slim)で提供記録を丸ごと除外していたため、再読み込みのたびに boot-merge prev:0 = 手元0件で画面が構築され、テーブル全量(997行)の取得完了まで空欄。読込中オーバーレイの保険タイマー(8秒)が取得より先に切れ、空欄のまま操作できてしまっていた(「消えた」誤解と危険入力の温床。同期ログのrows-apply連発の見え方も再読み込み+全量再取得の繰り返しによるもので、受信マージは冪等でデータ影響なし)。</span><span class=\"lb\">対処</span><span class=\"tx\">①軽量保存でも直近45日(上限1200行)の提供記録を保持(容量に入らない場合のみ従来の記録なし版へ段階フォールバック)→再読み込み後すぐ当月画面を表示。②オーバーレイの保険を20秒に延長(正常時はtable-initial完了で即時消える)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4e63be3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"rows-apply診断強化(行id・サーバー更新時刻)。同一行受信連発の調査用。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">同期ログ診断強化: rows-applyに行idとサーバー更新時刻を記録(受信連発の特定用)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">店舗報告「1箇所編集のたびにrows-apply n:1が同一秒に多数」の調査用。rows-applyは受信反映ログで、反映は項目時刻つき冪等マージのためデータ影響なし(無駄な通信の可能性のみ)。原因特定のため先頭行のid末尾14桁とサーバーupdated_at時刻をログに追加。次回発生時のログで「同一行の連続受信(=どこかの端末の再送ループ)」か「複数行の正常受信」かを判別する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fcd298</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"扇橋9/1午前のマシン運動記録消失: 未送信保留行が非永続で再読み込みにより喪失。localStorage退避+復元再送で恒久対策。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">通信不良時の未送信入力が再読み込みで失われる(扇橋9/1午前のマシン運動記録消失)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">調査: クラウド(ticket_records)を精査した結果、7〜8月は全営業日の運動入力が完全に残存。9/1のみ午前入力の大半が未着で、各行の exercises 刻印は14:24〜14:40(午後の別入力)のみ。書込経路(diffRecordRows→RPC upsert_ticket_records)はキー単位部分送信+サーバー統合で他端末の値を潰さない設計のため、消えたのではなく「届いていない」。送信失敗の自動再送キュー(_pendingRows)がメモリ上のみで、失敗保留中の再読み込み/タブ強制終了(iPadのメモリ回収)で未送信入力が完全に失われる穴だった。</span><span class=\"lb\">対処</span><span class=\"tx\">保留行を失敗時に localStorage(tsumugiPendingTicketRows_v1・最大500行)へ退避し、起動時に restorePendingTicketRows で復元→即再送(診断ログ pending-rows-restored)。送信成功時はキューを掃除。9/1午前分は復旧不能のため店舗で再入力を依頼(まばらに残存・不足分のみ)。あわせて調査で判明した副知見: 扇橋の①バイクは6月にID重複→旧削除の形跡があるが7月以降は新IDで一貫しており実害なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5b76a82</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"システム\" data-text=\"テスト体制整備: 自動テストランナー・テスト項目一覧(正常/準正常/異常×16分類)・運用ルール。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">テスト体制の整備 — 自動テストランナー+テスト項目一覧(約70項目)+定期実施ルール</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①scripts/run_tests.py新設(毎デプロイの締めで実行): 括弧バランス・競合マーカー・update-notes整合(version/一意id/prompt)・台帳整合(総件数=記事数・内訳合計)・実利用者データのコミット禁止(restore/まるっとLIFE)・本番生存確認(トップ/お知らせ/台帳API=401許容)・デプロイ完了確認(--deployed)。初回実行14項目ALL PASS。②「つむぎ テスト項目一覧」ノート新設(Obsidian第4ノート・NotebookLM同期対象): 同期系/提供記録/日誌/マスタ/モニタリング/計画書/アカウント/ケアマネ自動化/印刷/分析/運用/外部連携/セキュリティ/性能の16分類×正常系・準正常系・異常系で約70項目。運用ルール=項目は機能廃止まで削除しない(回帰テスト標準)・毎デプロイ自動/月次スモーク26項目(扇橋)/四半期全量/新機能は項目追加後にスイッチON・厳しさは厳しめ(同期系とアカウント系は異常系必須)。③導入窓口=各店舗の管理者を計画書第4版に明記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">61326b2</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ閲覧の自動化: 担当割当への閲覧アカウント自動同期エンジン(V1目玉)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">ケアマネ閲覧の自動化 — 1回の登録で担当利用者を自動閲覧・担当変更で自動切替(V1組込み)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">スタッフアプリ内の同期エンジンが、利用者マスタの担当(事業所+氏名の正規化一致)と担当者マスタの変化を署名検知(5秒デバウンス)し、登録済みケアマネの利用者別閲覧アカウントを自動同期する。仕組み: family_accountsをメール+パスワードハッシュでグループ化(=リンクログイン単位)→担当者マスタへ特定(メール一致優先・氏名包含一致が1名のみの場合)→あるべき利用者集合(退所済み除外・休止含む)と比較し、担当外れは停止(deleted_atソフト削除・supabaseDeleteFamilyAccountの物理削除とは別経路)、新担当は停止中の復活を優先しなければハッシュ複製で新規作成(username=基点-p利用者id・ログインはリンク機構が束ねるため非表示)。特定できないアカウントは一切触らない安全装置。supabase.jsにsupabaseListCmAccountsAll/supabaseInsertCmAccount/supabaseSetFamilyAccountDeletedを新設。ケアマネ画面の登録済み担当者に「閲覧は担当割当に自動同期」を表示。扇橋店で検証後、V1(10/1)に同梱。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6469162</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"システム\" data-text=\"更新バナーの表示範囲制御(prompt: all/silent/店舗限定)。V1/V2運用の前提整備。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">更新バナーの表示範囲を制御(全店/無音/店舗限定) — V2先行デプロイで他店に通知を出さない</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">update-notes.json にトップレベル \"prompt\" を追加: 'all'(既定・全店にバナー) / 'silent'(バナーなし・タブ背景化時の自動リロードだけで静かに配信) / [\"storeId\",...](指定店舗のみバナー)。V1/V2を1本のコード+店舗フラグで運用する際、扇橋だけのV2先行デプロイで他店に「新しいバージョンがあります」を出さないための仕組み。運用ルール: 扇橋向けデプロイは prompt を silent か扇橋storeIdに、全店に関わる修正(同期変更含む)は必ず all にする。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c9e0582</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"システム\" data-text=\"Brevo APIキーの2ヶ月おき自動キープアライブメール(Vercel Cron)。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">システム</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">Brevo APIキーの自動キープアライブ(2ヶ月おきのテストメール自動送信)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">BrevoがAPIキーを「3ヶ月未使用」で自動非アクティブ化する対策(2026-09-01に警告メールあり・当日のテスト送信で使用実績を回復済み)。api/brevo-keepalive.js新設+vercel.jsonのcronsで奇数月1日06:00(JST)に本部メール(BREVO_KEEPALIVE_EMAILで変更可・既定honbu@ones-style.co.jp)へ「メール送信の定期テスト(自動)」を送信し、招待/PW再設定メールの生存確認と使用実績を兼ねる。CRON_SECRET設定時は外部からの手動実行を拒否。デプロイ後の手動実行で送信成功を確認済み。アプリ本体の変更はなし(今すぐ更新は不要)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">92c2ea3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"稼働カードの休業を日数表示・自己リセットのID+メール二重確認・ログイン画面サポート案内の文字色修正。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-09-01</span></div>\n      <p class=\"title\">稼働カードの休業を日数表示・パスワード自己リセットをID+メールの二重確認に・ログイン画面の文字色修正</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①分析(稼働)の内訳チップ「休業」を、提供記録の休業件数(利用者数依存で0件になりがち)から各種設定の休業日数(kyugyoDays+半日0.5換算)に変更し「N日」表示に。②api/family-reset request にemail必須化: ログインIDと登録メールの両方一致時のみコード送信(不一致・不存在でも応答同一の列挙対策は維持)。ログイン画面のUIにメール入力欄を追加し案内文を更新。③ログイン画面下部のサポート案内(白字・薄緑背景で不可読)を白パネル+濃色テキスト+緑リンクに変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41f333c</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"アカウント\" data-text=\"パスワードのメール自己リセット(10分有効・5回制限・登録メール宛のみ)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">アカウント</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">パスワードのメール自己リセット(家族/本人/ケアマネがログイン画面から自分で再設定)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">api/family-reset.js新設(SERVICE_ROLE使用・admin-resetと同方式)。request: usernameからアカウント特定→登録メール宛にのみ6桁コード送信(宛先入力不可)。コードのsha256を店舗app_stateのsystemSettings.familyPwResetsに保存(有効10分・試行5回で無効化・ID不存在でも同一応答=列挙対策)。reset: コード照合→password_hash更新+同メール+同旧ハッシュのリンクアカウントも一括更新(複数利用者切替を維持)。ログイン画面に「パスワードをお忘れですか？」→ID入力→コード+新PW(英数6文字以上)の2ステップUI(送信先はマスク表示)。ご利用ガイドFAQも自己リセット案内へ更新。有効期限/試行回数は店舗決定(2026-08-31)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">241616a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"稼働率を定員×2コマ×営業日の枠数ベースへ刷新・休業日除外・半日休業対応。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">分析(稼働): 稼働率を定員ベース(定員×AM/PM2コマ×営業日)へ刷新・休業日除外・半日休業対応</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">業界標準「稼働率=延べ利用者数÷(営業日数×定員)」の半日型版として、稼働率=延べ利用コマ数÷(定員×営業コマ数)に刷新(1営業日=AM+PMの2コマ・1日利用=2コマ換算・振替は出席扱い)。定員(capacity)と定休日(closedDays)は各店舗の設定から自動取得し、店舗ごとの週稼働日数/定員の違いに自動対応。休業日(各種設定)は稼働日数から除外し「休業日N日」を表示、当月は今日までで算出。従来の予定比は「出席率」として併記。月別複合グラフ・前月比/前期比/前年比も定員ベース+年考慮に統一。枠数の内訳(定員×コマ・営業日数)をカードに表示。半日休業: 休業日設定に1日/午前のみ/午後のみを追加し、稼働率は該当1コマのみ除外・日誌の休業連動(_dayIsKyugyo)も該当時間帯のみ・日誌バッジは全日休業のみ非表示。提供記録の休業自動連動は従来どおり全日休業のみ。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">241616a</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"アカウント\" data-text=\"家族画面のパスワード変更機能・PW再設定の登録メール自動送信(api/send-password)。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">アカウント</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">家族/ケアマネ画面に「パスワードの変更」・PW再設定の新ログイン情報をメール自動送信</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①家族ポータルの登録者基本情報タブ下部に「パスワードの変更」を新設。現在のパスワードをsupabaseLoginFamilyで検証し、同メール+同パスワードハッシュのリンク全アカウントをまとめて更新(片方だけ変えると複数利用者の切替リンクが壊れるため)。ローカルfamilyAccountsにも反映。英字+数字6文字以上・現在と同一は不可。②api/send-password.js新設(Brevo・send-inviteと同環境変数): 事業所の「PW再設定」確定後、登録メールがあれば確認の上で新しいログインID/パスワード+ログインページボタン+「ログイン後にご自身のパスワードへ変更を」の案内を自動送信。送信失敗時は印刷/口頭案内へフォールバック。運用フロー: PW再設定→メール自動送信→本人ログイン→パスワードの変更。メールリンク式の自己リセットは引き続き実装予定(未来の修正点)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e50aa41</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"アカウント\" data-text=\"家族/本人/ケアマネのパスワード再設定(PW再設定ボタン)・事業所重複時の担当者追加誘導。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">アカウント</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">パスワード再設定(事業所発行)・ケアマネ事業所重複時に担当者追加へスムーズ誘導</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①利用者マスタの「アカウント管理」各行に「PW再設定」ボタンを新設。仮パスワード自動生成(英字4+数字4・編集可・英数6文字以上を検証)→確認→supabaseUpdateFamilyAccountでpassword_hash更新+ローカルfamilyAccountsにも反映(ログイン情報シート再印刷対応)。パスワード欄のツールチップとご利用ガイドFAQの「ログイン画面から再設定できます」という誤案内を実手順(事業所へ連絡→事業所で発行)に修正。メールによる自己リセットは今後の課題として未来の修正点に記載。②ケアマネ事業所の追加で同名が既登録の場合、行き止まりのアラートをやめ「この事業所で担当者を追加しますか？」の確認→担当者追加モーダル(事業所を初期選択)へ誘導。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">59ac797</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族向け\" data-text=\"スマホの家族画面で期間ドロップダウンが画面左に半分はみ出して見えない。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族向け</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">家族画面(スマホ): 期間の選択メニューが画面左に半分はみ出して見えない</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">期間パネルがボタン基準のposition:absolute right:0で、スマホではボタンが画面左寄りに折り返されるためパネルが左へはみ出していた。</span><span class=\"lb\">対処</span><span class=\"tx\">開いた時にボタンのgetBoundingClientRectから位置を計算し、position:fixedで画面内(左右8px余白・幅190px)に収まる座標に表示するよう変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">59ac797</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"事業所/担当者の追加をポップアップ化・同名事業所と同一事業所内の同姓同名担当者の重複登録防止。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">事業所/担当者の追加をポップアップ化・重複登録防止(同名事業所/同一事業所内の同姓同名)</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①常設の追加フォームを撤去し「事業所を追加」「担当者を追加」ボタン→モーダル登録に変更(担当者モーダルは選択中の事業所を初期値・氏名は姓/名分割入力・ふりがな/直通電話/メール欄つき)。一覧の表示領域が広がった。②重複防止: 事業所は同名(空白無視の正規化比較)を登録不可。担当者は「同一事業所内の同姓同名」のみ登録不可とし、別事業所の同姓同名は別人として許容。真の同姓同名はデータ上の識別キーが事業所+氏名のため、名前に区別文字を付けて登録するようアラートで案内(例: 鈴木 一郎(2))。追加経路は_addedAt刻印(墓石復活許可)を維持。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1ba2873</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ事業所/担当者の削除がunionマージで復活・登録済みケアマネが閲覧登録なしと誤表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">ケアマネ事業所/担当者の削除が復活する問題・登録済みケアマネの「閲覧登録なし」誤表示を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">(1)cmOffices/careManagersは両端末の追加を保持する純unionマージのため、片側で削除してもクラウド/他端末の同名項目が必ず復活していた。(2)登録状況バッジが端末ローカルのfamilyAccountsのみ参照しており、別端末・家族側デバイスで登録されたケアマネアカウント(Supabase側)が見えず「閲覧登録なし」になっていた。</span><span class=\"lb\">対処</span><span class=\"tx\">(1)systemSettings.cmTombstones(キー=off|事業所名/cm|事業所|氏名、値=削除時刻)を新設し最大値unionで統合、墓石のある項目はunion結果から除外。再追加時は_addedAtを刻印し墓石より新しければ復活許可。削除・一括削除(事業所+配下担当者)・改名(旧キー墓石+新キー刻印)・追加・CSV取込・ケアマネ登録autoaddの全経路に適用。旧版端末が混在する間は復活が再発しうるため全端末更新が前提。(2)supabaseListFamilyAccountsForStore新設(store_idで一括取得)+氏名の包含一致(2文字以上)許容で照合。表示のみで閲覧権限には影響しない。既登録者の再登録は不要。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c0aa22</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ登録の続柄一本化・利用者マスタのCMアカウント欄撤去・ケアマネ画面レイアウト調整。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">ケアマネ登録を担当者招待に一本化(続柄自動確定)・利用者マスタのアカウント欄撤去・画面幅調整</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①家族登録フォームの続柄から「ケアマネージャー」を除外。ケアマネ画面の招待メールから開いた登録フォームは続柄=ケアマネージャーで自動確定(固定表示・変更不可)。スタッフ側の家族メール招待の続柄例からもケアマネを外し案内文を追記。②利用者マスタの「登録されているケアマネ(アカウント)」表示を撤去し、ケアマネ事業所・担当者画面へ一本化(案内文のみ残置)。③ケアマネ画面: コンテンツ幅をmax-w-6xlに拡大・一覧の高さを62vhに・2カラムをitems-start化して右カラムの空白伸びを解消。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c0aa22</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ケアマネ\" data-text=\"ケアマネ事業所・担当者のサイドバー移設・担当者メール欄・招待メール・登録状況表示。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">ケアマネ事業所・担当者をサイドバーへ完全移設・担当者ごとの招待メールと登録状況表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①サイドバー(利用者マスタ管理の下)に「ケアマネ事業所・担当者」を新設し、各種設定のタブから完全移設。SettingsViewにcmOnlyモードを追加して同一コンポーネントを再利用(「消える問題」対策の同期追従・即保存persistCmを共有するためタブ抽出はしない)。②担当者マスタにメールアドレス欄(追加フォーム/編集モーダル)。③担当者ごとに「招待メール」: 既存のapi/send-invite(Brevo)を流用し、担当利用者(退所済み除く)の1人目に紐付く招待を発行。招待レコードにcmOffice/cmNameを付与して担当者と追跡可能に。メール未登録ならその場で入力→マスタへ保存。④登録状況バッジ: 登録済み(kind=caremanagerのアカウントとメールまたは氏名+事業所一致・最終ログイン表示)/招待済み(未使用・期限内のcm招待あり)/閲覧登録なし+担当利用者N名(氏名3名まで表示)。今後: 担当者単位アカウントで1回登録→担当利用者を自動閲覧・担当変更で自動失効(Supabase側精査後に実装予定)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6e18a65</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"日誌\" data-text=\"日誌シート内のチェック/到着出発セルがタップに反応しない。二重zoomと毎レンダー再マウントの複合。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"tag crit\">重大</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">日誌シート内がタップに反応しない(担当職員/送迎者/記録者のチェック・到着/出発の時間入力)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">複合原因。(1)アプリ全体のzoom(横幅1100px未満でcontentScale)と日誌シート個別のzoom(diaryViewScale)が二重に掛かり、iPad Safariの既知不具合でタップ座標とヒット判定がズレてシート内のonClickが発火しない。マスタ/ホーム/連絡帳はzoom例外指定で無事、日誌だけ例外に入っていなかった。(2)DiarySheet/StaffBox/DriverRow/CBがDailyLogView内で毎レンダー定義され&lt;Comp/&gt;形式で描画されており、再レンダーごとにDOMがアンマウント→再マウント。タップ(touchstart→click合成)の途中でDOMが差し替わるとclickが取りこぼされる。800ms間隔の幅計測や4秒同期が再マウントを常時誘発していた。</span><span class=\"lb\">対処</span><span class=\"tx\">(1)currentView===diary を全体zoomの例外リストに追加(日誌はシート側のdiaryViewScaleが自前で拡縮するため二重zoom不要)。(2)DiarySheet(3箇所)/StaffBox(5箇所)/DriverRow(2箇所)/CB(4箇所)をTimeKeypadModal等と同じ関数呼び出し描画 {Comp({...})} に変更し再マウントを根絶(全て内部hooksなしを確認・CarCellは表示専用のため対象外)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e4ff3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"名簿の並び替え/絞り込みをポップアップ化・基本利用日の曜日×AM/PM絞り込み。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">名簿の並び替え/絞り込みをポップアップ2ボタンに整理・基本利用日(曜日×AM/PM)絞り込みを追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">名簿の並び替えチップ8個の列を「並び替え: ◯◯↑」「絞り込み▾」の2ボタンに集約(モニタリング画面と同型のポップアップ)。並び替えは名前順/基本利用日/通所歴/介護度/事業所/誕生月/保険更新/年齢+昇順/降順。絞り込みは月曜起点の曜日×AM/PMを複数選択でき、1日利用の方はAM/PMどちらの選択でも該当。適用中はボタンに「月AM・木PM」等を表示し、各利用者の名前の下にも利用日サブ表示が付く。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e4ff3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"担当職員の自動チェックで送迎者/記録者に他の職員が出ない・時間テンキーがPCキーボードで入力できない。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">日誌: 担当職員の自動チェック廃止(他の職員が選べない問題)・到着/出発時間のPCキーボード入力対応</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">スタッフ切替のアクティブ記録者を担当職員へ自動チェックしていたため、送迎者/記録者候補を「担当職員チェック者のみ」に絞る改善(835bd1f)と組み合わさると候補が自動チェックの1人に固定され、他の職員を選べなくなった。また到着/出発のテンキーモーダルは画面ボタン専用で、PCの物理テンキー入力は無反応(1件目は画面入力で表示され、2件目をキーボードで打つと表示されないように見える)。</span><span class=\"lb\">対処</span><span class=\"tx\">担当職員への自動チェックを廃止(新規ログ読込時・スタッフ切替時とも)。記録者欄のみ従来どおり自動チェックし、切替時も記録者チェックだけ付け替え(手動チェックには触らない)。テンキーモーダル表示中は window keydown で 数字=入力・Backspace/Delete=削除・Enter=決定・Esc=キャンセル を受け付け、モーダル内に案内文を追加。ハンドラは毎render付け替えで最新stateを参照。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">36169a6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"要確認の迎え/送りタップで送迎車割り当てを直接開く・利用者マスタ並び替えに基本利用日。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">要確認の迎え/送りタップで送迎車割り当てを直接開く・利用者マスタ並び替えに「基本利用日」追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①日誌の要確認バッジのうち「迎え」「送り」はスクロールではなく送迎車割り当てモーダルを直接開く(送迎時間/記録者/管理者確認は従来どおり該当箇所へスクロール+ハイライト)。②利用者マスタ管理の並び替えに「基本利用日」を追加。月曜起点で最初の利用曜日が早い順(同曜日はAM→1日→PM・未設定は末尾・同順は名前順)に並び、選択中は名前の下に「月AM・木PM」形式のサブ表示。既存のモニタリング画面の曜日並び替えと同じ月曜起点ルールで統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">36169a6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"要確認バッジのジャンプ・出勤者のみの送迎者/記録者候補・サイドバー日誌バッジ。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-31</span></div>\n      <p class=\"title\">日誌: 要確認バッジのジャンプ・送迎者/記録者は出勤者のみ・サイドバーに未完了バッジ</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①要確認バッジをボタン化し、迎え/送り→利用者テーブル・送迎時間→送迎テーブル・記録者/管理者確認→各枠へscrollIntoView+1.8秒のオレンジ枠ハイライト(アンカーidは編集画面インスタンスのみに付与し印刷用と重複しない)。②DriverRow/記録者欄の候補をlog.staffでチェック済みの職員に絞る(既チェックの送迎者・記録者は表示維持・担当職員が全員未チェックなら従来どおり全員表示。配列filterのみで負荷なし)。③App側にdiaryTodayBadge(useMemo)を追加し、今日のAM/PMいずれかが未入力または未確認項目ありならサイドバー「日誌」に赤バッジ1(diaryPendingItems共用・休業日/定休日は非表示)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">835bd1f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"コンパクト表示(各項目1行・クリック展開)で1画面4〜6人。並び替え基準のサブ表示。ボタン形状統一。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">モニタリング一覧のコンパクト表示(既定)と並び替え基準のサブ表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「1画面2人は少ない」への対応。既定はコンパクト表示=①〜⑤をラベル+プルダウン+本文1行省略で表示(monExpanded Set・本文クリックで展開+編集開始・名前列に▼展開/▲たたむボタン)。展開時は従来の全文+コピー+textarea編集。並び替えが事業所/曜日のときは名前の下にその値を表示。「印刷/PDF(ケアマネ宛)」→「印刷/PDF」改名・選択チップ/一括ボタンを絞り込みボタンと同形状(角丸10)に統一。上限到達alertの「一括作成(既定)」言及も削除。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">edc64ae</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"長時間表示でメモリクラッシュ(コード5)。毎4秒フル取得+全再構築が原因。軽量メタチェック化。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">長時間表示でエラーコード5(メモリ不足クラッシュ)になる問題の対策</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">4秒ポーリング(checkAndPull)が変化チェックの前に毎回app_state全体(5MB超)を取得・JSONパースしていた。さらに「取りこぼし対策の強制反映」の閾値が4秒だったため、updated_atが同じでもほぼ毎回setAppDataで全アプリデータを再構築しており、ヒープの断片化・GC負荷が蓄積して数時間でWebViewがクラッシュしていた(localStorage容量超過の端末=データ大の端末で顕著)。</span><span class=\"lb\">対応</span><span class=\"tx\">①supabaseLoadStateMetaForStore(updated_atのみのselect)を新設し、前回反映と同じなら フル取得もsetAppDataもスキップ(初回ロード/強制pull時は従来どおり)。②強制全再構築の安全網を4秒→60秒に。他端末の変更はupdated_at差分で従来どおり4〜8秒で反映。提供記録テーブルの増分受信(since方式)は別経路で影響なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27f98c3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"画面刷新: ポップアップ化・列幅縮小・行操作は確定のみ・既定文の自動表示廃止・AI要約改善(運動の変化優先)。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">モニタリング画面刷新: ヘッダ1行化・列幅最適化・既定文の自動表示廃止・AI要約改善</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①題名行を廃止し、絞り込み(氏名/状態/曜日)と並び替え(基準+昇降順)をポップアップ(monFilterPop/monSortPop)に格納。ヘッダ1行に月選択/プレビュー/保存も統合。②名前列160→96px・操作列150→96px。③行操作は確定トグルのみ(AI/全文コピー/FAXは上部一括)。④getOrInitSheetForを空テンプレ化し、既定文生成はbuildDefaultSheetForへ分離(AI下書き・一括作成(既定)・空のまま確定の明示操作時のみ使用)。「自動で入っていると誰が書いたか分からない」問題の解消。⑤AIプロンプト: 計画目標未設定時の断り書き禁止を明記・運動の量の変化検出(_exVals: 前月→今月の値差「バイク3分→5分」)を追加しデータとして渡し、血圧偏重を避け運動変化を最優先で言及するルールを追加。⑥確定を名前列に統合し操作列廃止。⑦一括ボタンを「AI下書き/印刷・PDF(ケアマネ宛)/自動FAX」に整理(個人ファイルに保存は自動保存化で廃止)・選択チップ同サイズ化。⑧全画面共通: プレビューの自動印刷タブ起動を廃止(画面確認→印刷ボタンで移動)・プレビューのページを影付きで1枚ずつ分離表示。⑨モニタリング表の結果列130px化で語中改行解消。⑩選択チップ+一括ボタン行をヘッダ行へ、確定サマリ/締切とAI残数も1行に統合(3880ca0, 5983eee)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">84bd56e</span> <span class=\"cid\">2f67979</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"初回報告バッジが数秒で復活。完了エントリにidが無くmergeByIdで破棄。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">初回報告を完了してもバッジが数秒で復活する問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存ボタン経路のinitialReports完了エントリに<b>idが無かった</b>。クラウドマージ(mergeById)はid無しの行をローカル/クラウド両側で破棄するため、保存直後のpull(4秒)で完了記録が消え、バッジ判定(initialReports未登録)が復活していた。FAX送付経路(initrep_...)はid有りで無事だった。</span><span class=\"lb\">対応</span><span class=\"tx\">完了エントリにid(ir_利用者ID)を付与(_savedAtは保存時の自動刻印で付く)。添付での完了も添付ファイルと完了エントリを1回のonSaveで原子的に保存(2回に分けると後の保存が先の内容を巻き戻すため)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cb748ac</span> <span class=\"cid\">7a4d0dd</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"初回報告の2択フロー・バッジからのジャンプ・完了後表示・フォルダごと添付。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">初回報告の選択式フロー(手入力/書類添付)・バッジジャンプ・フォルダごと添付</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①名簿の「初回報告」バッジをクリックで個人ファイル(cat_7)を直接オープン(stopPropagationで行クリックと分離)。②タブは状態依存の3画面に再構成: 未完了=「手入力で作成/書類を添付して完了」の2択 → 完了後=手入力なら報告書内容の読み取り表示(保存済みデータで印刷/PDF・編集ボタン)、添付ならファイル一覧への案内+「手入力の報告書も作成する」。③ファイル追加はボタン1つに統合し、ファイル一覧の枠をドラッグ&ドロップ対応に(ファイル/フォルダ両対応・webkitGetAsEntryで再帰収集・画像/PDFのみ登録し非対応形式は件数案内でスキップ。1つのダイアログで両方選べないブラウザ制約の回避)。手入力フォーム中は保存のみ表示・選択画面/フォーム中はファイル欄非表示。あわせて保存時にid無し行を検知するno-id-row警告ログを追加し、全書き込み経路のid総点検を実施(初回報告以外は全id有りを確認)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cb748ac</span> <span class=\"cid\">7a4d0dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"QuotaExceededのpersist-fail連発を抑制。容量超過検知後は軽量保存へ直行。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-30</span></div>\n      <p class=\"title\">ローカル保存の容量超過(QuotaExceededError)の再試行とログ洪水を抑制</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">appDataがlocalStorage上限(約5MB)を超えた端末では、保存のたびに フル→写真分離→軽量版 と巨大JSONのstringifyを3回行ってから軽量版で成功しており、persist-fail/persist-slimログが保存ごとに出続けていた(クラウド同期・テーブル取得は正常で実害なし。テーブル方式では提供記録はテーブルが正)。</span><span class=\"lb\">対応</span><span class=\"tx\">一度QuotaExceededを検知したらpersistQuotaUntilRefに10分の期限を記録し、その間は軽量版(提供記録・写真除外)へ直行。10分ごとにフル保存を再挑戦して容量が空けば自動復帰。CPU負荷とログ洪水を解消。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5cc1b51</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"気分ボタンが長押しで反応しない問題。pointerup確定のlongPressTapPropsを導入。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">気分入力: 長押しでもタップとして反応するように</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者が気分ボタンを強く長押しすると、ブラウザの長押しメニュー(コンテキストメニュー)や文字選択が働き、clickイベントが発火せず「押したのに反応しない」となっていた(特にAndroid/iPadで発生)。</span><span class=\"lb\">対応</span><span class=\"tx\">共通ヘルパーlongPressTapPropsを新設: pointerup(指を離した時)で確定・contextmenu抑止・touch-callout/user-select無効・12px以上の移動はスクロール扱いで無視・直後のclickは時刻ガード(500ms)で二重実行防止(再レンダー跨ぎでも安全なようモジュール変数で判定)。気分/理由/戻る/決定の4種のボタンに適用。他画面のボタンにも転用可能な汎用実装。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6b1cbc7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"保存して切替/移動で適用日モーダルが出ない根因(flushLP素通り)を修正。キャンセル追加・幅拡大。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">「保存して切替/移動」で運動メニューの適用日モーダルが出ない根因を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">saveFnRef(保存して切替/移動・バックグラウンド保存が呼ぶ保存関数)にはsaveMasterInfoではなくflushLP(適用日確認を持たない別の保存関数)が代入されており、前revで入れた「戻り値modalで移動を保留する」仕組みが一度も発動していなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">saveFnRefをラッパー化し、運動メニュー/個別運動に未確定の差分がある場合(自動保存済みのpendingに加え、自動保存前1.5秒以内の直近編集も基準値との差分比較で検知)はsaveMasterInfoへ委譲して適用日モーダルを表示。差分が無ければ従来どおりflushLP。あわせてモーダルをmax-w-xlに拡大しボタンの改行を解消、「キャンセル」(反映せず編集を続ける・保留中の移動/切替は取消)を追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3245328</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"本日スケジュールに日誌の未入力/未確認表示。休業日はスタッフ自動チェックなし。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">ホームに日誌の未入力/未確認お知らせ・休業日のスタッフ自動チェック抑止</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">日誌の入力・確認忘れ対策。共通ヘルパーdiaryPendingItems(未入力=null/未確認項目=迎え・送り・送迎時間・記録者・管理者確認)を新設し、ホームの本日のスケジュール先頭に黄色バナーで「午前: 未入力」「午後: 送り・管理者確認 未確認」のように表示(タップで日誌へ・休業日/定休日は非表示)。あわせて休業日・定休日の日誌はスタッフ切替選択者の自動チェック(担当職員/記録者)を付けないように(新規読込時とスタッフ切替時の2経路)。今後: モニタリング/実績の確定期限カウントダウン表示をロードマップに追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8183d7</span> <span class=\"cid\">9ac1d66</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"運動メニュー変更時の画面移動は適用日モーダル直行+確定後自動移動。予定ポップアップ拡大。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">運動メニュー変更中の移動は適用日モーダルへ直行(確定後に自動移動)・予定ポップアップ拡大</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">前revで「未保存確認→保存→適用日モーダル」の2段だったのを、反映日未確定(masterExPendingRef)ならnavigateToが「サービス提供内容の変更を反映」モーダルを直接表示する1段に。移動先はmasterNavAfterExRefに保留し、「過去全て/日付指定」どちらで確定しても自動で移動先へ移る(未保存確認・利用者切替の確認経由も同様)。「破棄して切替」は自動保存済みの新値が残る問題があったため、discardPendingExで旧値を書き戻して実際に破棄されるように修正。ホームの日誌お知らせは1行スリム表示(午前・午後のみ・詳細はツールチップ)に変更。カレンダーの予定確認ポップアップは幅400→560・タイトル23px・ボタン15pxに拡大。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8183d7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"運動メニュー変更が画面移動で確認なく保存される問題を修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">運動メニュー変更が画面移動の自動保存で「いつから適用」の確認なく確定していた問題</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニューの変更は自動保存(1.5秒)では値だけ静かに保存し、適用日モーダルは「保存」押下時に出す設計だが、自動保存がdirtyフラグを落とすため、サイドバー移動時のナビゲーションガード(未保存確認)が働かず、モーダルを見ないまま確定していた。</span><span class=\"lb\">対応</span><span class=\"tx\">反映日が未確定の間(_pendingExBaseRefあり)は自動保存後もdirtyを維持。画面移動の「保存」選択時、saveMasterInfoがモーダルを開いた場合は移動を中断してモーダルを表示(saveFnの戻り値=modalで判定)。適用日を確定してから改めて移動する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0455668</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"カレンダー\" data-text=\"色ラベル編集を保存/キャンセル方式に。予定カードのボタン横一列。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">カレンダー</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">色ラベル編集の下書き+保存/キャンセル化・予定カードのボタン整列</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">色ラベル編集は1文字ごとにクラウド保存されていたのを下書き(labelDraft)に変更し、「保存」で確定・「キャンセル/×/背景タップ」は未保存変更があれば確認してから破棄。予定確認カードは「担当者会議を記録」が本文側、削除/編集/閉じるがフッター側で段違いだったため、1行のフッターに統合(左=記録ボタン・右=削除/編集/閉じる)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0455668</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"カレンダー\" data-text=\"色ラベルの担当者会議/契約/見学を固定化。ボタン名を担当者会議を記録に統一。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">カレンダー</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">色ラベルの固定(担当者会議・契約・見学)と「担当者会議を記録」への名称統一</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">色ラベルの正規化処理を追加し、担当者会議(別名「担会」も吸収)・契約・見学を先頭3件に固定(名前入力disabled+「固定」表示・削除ボタン非表示・色は変更可)。既定ラベルの「面談」は「見学」に変更。担会記録へのジャンプボタンは地域による略称差を踏まえ「担当者会議を記録」に統一(カレンダーのカード/日別リスト/ホームの3箇所)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ef2f09b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"今すぐ更新の更新中表示・カレンダーから利用者マスタ/担会記録ジャンプ・連絡帳ボタン左端へ。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">今すぐ更新の「更新中…」表示・カレンダーからのジャンプ・連絡帳ボタン位置</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①今すぐ更新は保存→キャッシュ/SW削除→再読込で数秒かかり無反応に見えていたため、押下直後にボタンを「更新中…（そのままお待ちください）」+灰色+disabledに(保存失敗時は元に戻す)。②カレンダー(ScheduleView)にnavigateToを配線し、予定確認カードに「担当者会議記録を入力」(利用者が紐付いた予定ならタイトル不問で必ず表示・tsumugiReopenPFで個人ファイルの担会タブを自動オープン。ホーム側も同条件に統一)を追加(ボタン名は「担会を記録」に短縮・ホーム側も同名に統一)。「利用者マスタを開く」ボタンは利用者名タップと重複のため撤去し、カード/日別リストの利用者名を下線リンク化。日別リストにも「担会を記録」ボタンを追加。③提供記録入力の「連絡帳」ボタンを通常/全画面ヘッダとも左端に移動。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5036d82</span> <span class=\"cid\">f472d65</span> <span class=\"cid\">9276d81</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"今すぐ更新後に更新前の画面へ復帰。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">「今すぐ更新」後に更新前の画面へ自動復帰</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">今すぐ更新のリロード直前にcurrentViewと選択中の利用者IDをsessionStorageへ保存し、起動時のcurrentView初期値で使い捨て復元(5分以内のみ有効)。通常起動は従来どおりホーム。作業中の画面から更新してもホームに飛ばされなくなった。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">888323f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"担会小窓v3: 各行1項目・リサイズつまみ・ボタン大型化。表示内容ポップアップ化+他関係者列。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">担会小窓v3(リサイズつまみ等)と分析個人「表示内容」のポップアップ化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①小窓の開催日/開始/終了を各1行に(iPadのinput最小幅対策の完全版)。②ピンチはOSの画面全体ズームと競合するため廃止し、右下のリサイズつまみ(pointerイベント・touchAction none)ドラッグで小窓のみ0.7〜1.5倍。Ａ−/Ａ＋ボタンも32px高に大型化。小窓の×は誤タップ防止のため撤去(閉じるのは下部の保存/キャンセル)、全画面フォームの×/キャンセルは変更ありの時に保存確認。③分析個人の閲覧範囲一覧はインライン折りたたみをやめ、ヘッダの利用者名横「表示内容」ボタン→ポップアップに変更。「ケアマネ・他関係者」列を追加(関係者アカウントはケアマネと同表示)。事業所画面のみ表示で、家族/ケアマネ/本人側には出ない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27ad211</span> <span class=\"cid\">9a4f8ac</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"担会小窓v2: 保存/キャンセル明示・全画面から小窓移行・iPad重なり修正・ピンチ拡大縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">担当者会議フロートメモv2: 明示保存・全画面からの移行・iPad修正・拡大縮小</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①1秒自動保存をやめ「保存/キャンセル」の明示保存型に(未保存はdirty表示+閉じる時confirm。「小窓で記録」発の新規はキャンセルで空記録ごと削除=残骸防止)。②全画面フォームのヘッダに「小窓にする」(入力途中の内容を保存して小窓へ移行。カレンダー→担会記録の経路もフォーム経由のため対応)。③iPadでdate/time inputの固有最小幅により開催日と開始/終了が重なっていたため2行に分離。④ピンチ(2本指)とヘッダＡ−/Ａ＋で0.7〜1.5倍(width+fontSize連動のみで軽量)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">082a590</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人に本人/家族/ケアマネの閲覧範囲一覧を追加。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">分析個人: 「ご本人・ご家族・ケアマネにはどこまで表示される？」一覧を追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">事業所側の分析個人の上部に折りたたみの一覧表を追加。実装の表示ルール(家族=基本情報/今回の記録/簡易通所率/気分/バイタル/体力測定のみ・本人=同+特記非表示・ケアマネ=事業所と同じフルセット、特記は家族非表示設定を除き家族表示/ケアマネ常時/本人非表示)をそのまま表にした。印刷には含まれない(no-print)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">082a590</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"担当者会議のフロートメモ。画面切替でも残る小窓で会議記録を入力。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-28</span></div>\n      <p class=\"title\">担当者会議のフロートメモ(小窓): 他画面を見ながら会議記録を入力</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">担当者会議中に分析個人や提供記録を参照しながら記録したいという要望(iPadのクイックメモ風)。MeetingFloatWidgetをAppルートに常駐させ、windowイベント(tsumugi-meeting-float)で起動。開催日/時間/出席者/開催理由/検討内容を編集でき、1秒デバウンスでpersonalFile.meetingsへ自動保存(閉じる/アンマウント時もflush)。下書きは小窓ローカル状態のため4秒同期の再レンダーで入力が消えない。ドラッグ移動(pointerイベント=タッチ対応)・最小化ピル・portal描画。担会一覧に「小窓で記録」(新規作成+起動)と各記録「小窓」ボタンを追加、起動時は個人ファイルを閉じて画面移動を自由に。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7beae3e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"利用開始日前の利用者が日誌に載る問題。提供記録入力と同じ日付基準に統一。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-27</span></div>\n      <p class=\"title\">日誌: 利用開始日前(9月開始の方が8月に載る等)の表示を修正・提供記録入力と判定統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌の「記録がまだ無い予定者」の抽出が今日時点の利用者情報(scheduleAmPm・表示状態)だけで判定しており、提供記録入力が使う日付基準の共通関数(isPatientActiveOnDate=利用開始/終了日、getScheduleOnDate=その日付時点の基本曜日)を通していなかった。そのため9月開始で登録した利用者が8月の日誌に出席として載っていた。</span><span class=\"lb\">対応</span><span class=\"tx\">日誌の入力行・プレビュー行・送迎コピーの対応付けの3箇所を提供記録入力と同じ共通関数に統一。利用開始日前/終了日後は載らず、後から増回した曜日も過去に遡及しない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74c4815</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"休業日が日誌で出席表示・送迎コピーされる問題と稼働日数の休業日未反映を修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-27</span></div>\n      <p class=\"title\">休業日の連動: 日誌の休業表示・送迎コピー抑止・稼働日数への反映</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌はticketRecordsと基本曜日だけで行を作っており、各種設定の休業日・定休日・月間スケジュールの「休業」を見ていなかった。そのため休業設定した8/12-14でも利用者が「出席」で表示され、先週分の送迎自動コピーまで実行されていた。分析の稼働日数も「月〜金固定」の計算で休業日・定休日設定を無視していた。</span><span class=\"lb\">対応</span><span class=\"tx\">日誌の行構築(入力・プレビュー共通)に_applyKyugyo(休業日/定休日/シフト休業なら出席・振替→休業。欠席・休止は本人事由なので維持)を追加し、休業日は送迎自動コピー自体をスキップ、シフト休業の利用者もコピー対象外に。稼働日数は定休日設定(closedDays)+休業日(holidays)を除いて計算するよう変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">08dc770</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"AM/PM入力済みでも緑丸が付かない問題。送迎コピー未確認が保存でも解消されなかった。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-27</span></div>\n      <p class=\"title\">日誌カレンダー: AM/PM入力済みでも緑丸が付かない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">カレンダーの緑丸は「送迎自動コピーの未確認(_sougeiPending)が残る日は入力済みに数えない」仕様(8/21)だが、コピー内容が正しく編集不要だった日は個別編集による解除が起きず、未確認が永久に残って緑丸が付かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">手動保存(保存ボタン)=内容を確認して確定した扱いとし、保存時に未確認フラグを解消。既存の付いていない日は開いて保存し直せば緑になる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">08dc770</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"保険証/負担割合証の更新者記録と未更新警告(30日以内/期限切れ)・件数まとめ。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-26</span></div>\n      <p class=\"title\">期限もの(保険証/負担割合証)の見える化: 更新者の記録と未更新警告</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①appendValueHistoryにby(スタッフ切替の選択者名)を自動記録し、変更履歴に「記入: ◯◯」を表示(保険更新モーダルの手動push2箇所にも追加)。②名簿の期限判定を「当月のみ」→「30日以内(expiring)/期限切れ(expired)」に拡張し、負担割合証(costBurdenTo)も対象化。未来の変更予定・新期間が登録済み(updated)なら警告を出さない。③名簿上部に「更新の確認が必要: 保険証◯名・負担割合証◯名」のまとめバーを表示。チェックリストは作らず名簿の表示だけで完結。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">66f349e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護保険証/負担割合証の未来日更新を変更予定として保存し開始日に自動切替。名簿に予定バッジ。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-26</span></div>\n      <p class=\"title\">介護保険証/負担割合証: 未来の認定開始日は「変更予定」として保存し開始日に自動切替</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個人ファイルの保険証タブ(saveMaster)は未来の認定開始日でも介護度を即時反映しており、9月からの区分変更を登録すると名簿・帳票が先に新介護度になっていた(関口様の要支援1→9月要支援2で実害)。利用者マスタ側の保険更新モーダルには予約機能があったが、入力起点の保険証タブに無かった。</span><span class=\"lb\">対応</span><span class=\"tx\">開始日が未来かつ介護度/負担割合の値が変わる保存は「変更予定」扱い(現在値は維持・履歴に未来日エントリ・トーストで案内)。既存の起動時自動適用が開始日当日に切替える。名簿に「◯月から◯◯」バッジ、保険証/負担割合証タブに変更予定表示を追加。あわせて負担割合の自動適用ロジックを介護度と同じcostBurdenFrom基準に修正(終了日なしの予約エントリが永久に適用されない穴)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">379b192</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"体温テンキーに35./36./37.クイックボタン。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-26</span></div>\n      <p class=\"title\">体温セルのテンキーに「35./36./37.」クイックボタンを追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">提供記録入力で体温セル(temp/temp_AM/temp_PM)を選ぶと、テンキー下部に緑の「35.」「36.」「37.」ボタンを表示。押すと値がその値で置き換わり、続けて下1桁を打つだけで入力完了(例: 36.→5で36.5)。DigitalKeypadに汎用のprefixButtons propを追加して実装(他の項目への転用可)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f04b4ee</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"休み連絡\" data-text=\"カレンダーのバッジを編集済(青)と印刷/PDF済(緑)に区別。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">休み連絡</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">休み連絡カレンダー: バッジを「編集済」と「印刷済/PDF済」で区別</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">これまで編集済も印刷/PDF済もすべて青「編集済」で表示され、出力したかどうかが分からなかった。編集のみ=青「編集済」、出力済み=緑「印刷済」「PDF済」「印刷・PDF済」に区別し、ヘッダの凡例にも緑を追加。個人ファイル連絡タブの「下書き(編集済・未送付)」表示と合わせて、未出力の休み連絡が一目で分かる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c6f4cc</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"体力測定の一覧印刷。休み連絡の下書き(未送付)表示。タブ列スクロールバー常時表示。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">個人ファイル: 体力測定の一覧印刷・休み連絡の下書き表示・タブ列スクロールバー常時表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①体力測定タブに「印刷/PDF保存」ボタンを追加(全測定日×全項目のA4横一覧・ヘッダに氏名/事業所/出力日)。②休み連絡カレンダーで「編集済」なのに連絡タブの休み連絡が0件になる食い違いを解消: 「編集済」はFAX下書き(faxDataStore)の編集のみで、連絡タブは印刷/PDF/送信時に記録される送付履歴(faxHistory)を表示していたため。連絡タブに「下書き(編集済・未送付)」の一覧を追加し、出力すれば送付履歴に載る旨を案内。③タブ列に横スクロールバーを常時表示(タブが隠れていることに気付けるように)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4c140b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"振替の色を紫から緑に統一。休業日の特記に休業理由を自動表示。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">提供記録: 振替の色を緑に統一・休業日の特記に休業理由(年末年始等)を自動表示</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">月表示・個人ファイルのサービス提供記録・期間一括出力で「振替」が紫(#7c3aed)で表示されていたのを、他画面(状態ボタン/分析/実績)と同じ緑(#059669)に統一。また休業日の行は特記が空のとき、各種設定の休業日に登録した休業名(例: 年末年始)や「定休日」を特記欄に自動表示するようにした(月行生成generateMonthlyScheduleで補完・記録には書き込まない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4c140b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"印刷設定を明確化。1面はB6手差しを既定に、使い方ガイドを追加。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">連絡帳の印刷設定を明確化: 1面はB6(手差し)を既定に+手差しトレイの使い方ガイド</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「横(B5)/縦(B6)」の表記がパッと見で分かりづらかったため、「B6（手差しトレイ）/B5（中央にB6配置）」に改名し、1面（1人ずつ）を選ぶと用紙を自動でB6に設定。B6選択時は手差しトレイでの印刷手順（用紙セット→複合機でB6/カスタム128×182mm選択→印刷画面でB6・手差し指定）と「最初は1枚テスト印刷」の注意書きを表示。ほとんどの複合機は手差しトレイでB6対応だが機種依存のため未検証の旨をユーザーと共有済み。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e341cd2</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"月間スケジュール\" data-text=\"月間で取り消した振替が再読み込みで復活。テーブルへの削除伝達漏れ。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">月間スケジュール</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">月間スケジュールで取り消した振替が、保存→再読み込みで復活する問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間スケジュールの振替取消/セル取消は墓石(deletedIds)を積むだけで、テーブル(ticket_records)への削除伝達(options.deleteRecordIds)を渡していなかった。テーブルの行が生き残るため、保存→再読み込みや数秒後の受信で取り消したはずの振替記録が必ず復活していた(2026-08-10に提供記録入力側で修正した事象と同型の伝達漏れ)。</span><span class=\"lb\">対応</span><span class=\"tx\">振替取消(cancelFurikaeMaster)・セル取消(applyShiftStatusの取り消し)・残骸記録削除ツールの3経路すべてで、削除した記録idを deleteRecordIds でテーブルにも伝えるようにした。既に復活してしまった記録は、更新後にもう一度取り消せば消える。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e334dc7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"2端末で別利用者の血圧同時入力で片方が消える穴と、古い下書きが振替取消を巻き戻す穴を閉鎖。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">2端末同時入力の強化: 刻印ゲートを全既存行に拡張+実編集の有効期限30分</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">案A本適用(f7ee007)は「実編集記録がある行」だけをゲートし、記録の無い行は従来の差分刻印のままだった。端末Bが利用者Aを一切触っていなくても自動保存は下書き全行を保存するため、同期で届いたAの新しい血圧と下書きの古い空欄の差分が「新編集」と誤刻印され、Aの入力が消えた(WindowsでA・iPhoneでBを同時入力→Aだけ消える実害)。また実編集記録に有効期限が無く、数日前に振替を設定した端末の古い下書きが、他端末で行った振替取消を何度でも巻き戻せた。</span><span class=\"lb\">対応</span><span class=\"tx\">ゲートを<b>既存行すべて</b>に拡張(記録の無い行の提供記録系フィールドは刻印しない)+実編集の有効期限30分。あわせて提供記録を書き換える全経路(月間スケジュールの振替設定/取消/欠席理由・休止設定・FAX休み連絡の理由差替)に実編集マーキングを追加し、正規の変更がブロックされないようにした。ブロック時はstamp-gateログに記録。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">228aead</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"月間スケジュール\" data-text=\"月間スケジュールの取り消しで対の振替先が残骸として残る問題を修正。日誌の先週コピーは車両のみに。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">月間スケジュール</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">月間スケジュールの取り消しで対の振替先も一緒に取り消し／日誌コピーは車両紐付けのみ</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間スケジュールで振替元の欠席セルを取り消すと、そのセルの記録だけ整理され、対になる振替先の「振替」記録・特記(「◯月◯日へ振替」「◯月◯日PM分振替」)・シフト表示「振(x/x)」が残骸として残り、提供記録入力と表示が食い違っていた(佐々木様 8/26→8/27の振替取消で実害)。</span><span class=\"lb\">対応</span><span class=\"tx\">取り消すセルの特記から対の振替先を検出し、振替先の記録(データがあれば出席として保持・目印は消去/空枠は墓石付き削除)とシフト表示も同時に取り消し。特記事項の振替・欠席の目印も消える。あわせて日誌の先週分自動コピーは利用者と車両の紐付けのみとし、毎回変わる送迎時間・運転者を除外(店舗要望)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">228aead</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の並び順とプレビューの号車・送迎時間・提供日サイズを修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-25</span></div>\n      <p class=\"title\">日誌: 入力画面の並び順とプレビューの号車・送迎時間・提供日サイズを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①入力画面の利用者一覧は状態ランクのみでソートされ五十音順が効いていなかった。②プレビュー用の行データを別ロジックで再構築しており patientId を持たないため、IDキーで保存される迎え/送りの号車が引けず空白。送迎時間も保存済みログのみ参照で編集中(未保存)の内容が反映されなかった。③印刷用の非表示コンテナでは提供日の自動縮小(AutoFitLine)が幅を測れず文字数フォールバックで縮んでいた。</span><span class=\"lb\">対応</span><span class=\"tx\">入力画面のソートを状態→かな順に統一。プレビューの行データを入力画面と同一構築(重複記録の絞り込み・記録なしの予定者・patientId/kana付与・同ソート)へ差し替え、表示中AM/PMは編集中データをそのままプレビューに反映。提供日は固定12pxのままに。他画面の印刷はDOMキャプチャ方式のため同種の問題なしを確認。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">435deb4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"モニタリング\" data-text=\"絞り込み・並び替えを統一ツールバーに集約。曜日は月曜起点。AI下書き上限は利用者数×2回。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">モニタリング</span><span class=\"date tnum\">2026-08-24</span></div>\n      <p class=\"title\">モニタリングの絞り込み・並び替えを統一ツールバーに集約、AI下書き上限を利用者数×2回に</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">ヘッダに散在していた氏名検索・並び替えボタンを整理し、ヘッダ直下の1本のバーへ集約。絞り込みは氏名/状態(すべて・未作成・未確認)/曜日(月〜日のマルチ選択チップ)、並び替えは名前/介護度/事業所/曜日+昇順・降順の切り替え。右端に現在の表示人数。利用曜日の表示と並び順は月曜起点に統一(従来は日曜起点の文字列比較のため火曜始まり等でバラバラだった)。AI下書きの月間上限は「利用者数+3回」から<b>「利用者数×2回」</b>に変更し、上限表示・警告文言も更新。あわせて選択バーの「未作成のみ」は絞り込みの「未作成」と重複のため撤去(絞り込み後に「全員」で同じ結果)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e43df04</span> <span class=\"cid\">5b131c0</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"2端末同時編集で血圧等が巻き戻る問題の恒久対策。刻印を実編集ベースに本適用。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-24</span></div>\n      <p class=\"title\">2端末同時編集の巻き戻り恒久対策（実編集ベース刻印の本適用）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">Windowsで気分・スマホで血圧を同時入力すると「血圧153/85→1」のように欠ける実害が発生。8/17に特定した構造(保存時の項目時刻の刻印が「実際に編集した項目」ではなく「差分」で判定され、編集中に他端末の途中値が下書きへ紛れると新編集として誤刻印)そのものだった。</span><span class=\"lb\">対応</span><span class=\"tx\">観察モードで収集してきた実編集記録を<b>本適用</b>: 提供記録の既存行では、提供記録入力が管理する項目(状態/特記/バイタル/運動/気分等)について<b>実際に編集した項目だけに新時刻を刻む</b>。状態モーダル・休業/休止の自動補正・月表示編集・振替取消も実編集として記録。実編集記録の無い行(連絡帳・他画面由来)は従来どおり。誤刻印をブロックした瞬間は同期ログ(stamp-gate)に記録され、巻き戻り防止が働いたことを確認できる。1コミットで即時切り戻し可能な独立変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f7ee007</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"スケジュールをカレンダーに改名。繰り返し絵文字も削除済み。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-24</span></div>\n      <p class=\"title\">「スケジュール」を「カレンダー」に改名</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">行事だけでなく誕生日・認定期限も表示するカレンダー実態に合わせ、サイドバー・画面タイトル・ホームのタイルを<b>「カレンダー」</b>に改名(利用者マスタの「月間スケジュール」との紛らわしさも解消)。繰り返し予定の絵文字表示は[繰]表記へ変更済み。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f7ee007</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌カレンダーの未確認扱い修正と送迎未入力の要確認追加。利用者並びを提供記録と統一。連絡帳のボタン色変更と名称簡略化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">日誌の要確認・カレンダー表示の見直し／連絡帳のボタン整理</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①日誌のカレンダーで、自動コピーの<b>未確認が残っている時間帯は「入力済み(緑)」に数えない</b>ように修正(未確認が全て消えるまで入力扱いにしない)。②送迎(迎え/送り)が<b>そのまま未記入</b>の場合も要確認バッジに出すように(従来はコピー未確認しか検知せず「管理者確認のみ」表示になっていた)。③日誌シートの利用者の並びを提供記録入力と同じ<b>状態順→かな順</b>に統一。④サイドバー「連絡帳 作成・印刷」を「連絡帳」に簡略化、連絡帳の「連絡事項」ボタンを白、「提供記録」ボタンを緑に変更。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f27cd33</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳に提供記録入力へのジャンプボタンを追加。相互往復できるように。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">連絡帳に「提供記録」ジャンプボタンを追加（相互往復）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">提供記録入力→連絡帳のジャンプは従来からあったが逆方向が無かったため、連絡帳ヘッダに<b>「提供記録」ボタン</b>を追加し相互に行き来できるようにした。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">75bff6b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回予定の日付横の曜日を大きく濃く表示。日曜赤・土曜青。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">次回予定の曜日を大きく濃く表示（日曜=赤・土曜=青）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">次回予定モーダルの日付横の曜日が小さく薄く判別しづらかったため、日付と同等の大きさ・濃い色で表示。日曜は赤・土曜は青で一目で分かる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e2aeb6d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"スケジュール詳細の時間の二重表示を解消。ジャンプタイルをコンパクト化し管理分析も白カードで統一。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">スケジュール詳細の時間二重表示を解消／ジャンプタイルをコンパクト化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①本日のスケジュールの詳細で時間が上部と本文の2箇所に出ていたのを、本文の「時間：」1箇所に統一。②ホーム下部のジャンプタイルを縮小(アイコン・余白・文字)し、枠なしで浮いていた「分析(個人)/(稼働)/家族関係者投稿/スケジュール/各種設定」を<b>「管理・分析」白カード</b>にまとめて統一。ホーム全体が1画面に収まりやすくなった。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e1e96f3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"全て既読にしても未読バッジ1が残る問題を修正。既読の記録先2系統の不一致が原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">全て既読にしてもサイドバーの未読バッジ「1」が残る問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族・ケアマネからの更新の既読には2系統あり(担当者ごとの既読記録/更新自体の確認フラグ)、ホームの「全て既読」は前者にだけ記録する一方、サイドバーのバッジは後者だけで数えていたため、確認フラグが付かない更新が残っているとバッジが消えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">バッジの集計を画面と同じ基準(どちらかが既読なら既読)に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27ac2b9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"行事予定カレンダーに前月末翌月頭を表示。本日スケジュールの時刻強調と詳細充実。家族更新とお知らせの1行表示化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">ホーム・行事予定の見やすさ改善（前後月表示・1行リスト化・時刻強調）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①行事予定の月カレンダーの空きマスを<b>前月末・翌月頭の日付(薄表示)</b>で埋め、予定の表示・タップもそのまま可能に。②ホームの本日のスケジュールは<b>時刻を大きく藍色で強調</b>し、タップした詳細に<b>時間・利用者名を明記</b>。カード枠も強調。③<b>家族・ケアマネからの更新</b>を「バッジ+利用者名+更新内容+日時」の1行表示に、<b>お知らせ</b>を「バッジ+日付+題名+写真枚数」の1行表示に変更(タップで従来どおり本文・写真の詳細)。運営お知らせと統一の操作感に。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27ac2b9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"予定編集の日時行が折り返す問題を修正。必ず横一列表示に。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">予定編集の「日付・開始〜終了」を必ず横一列に</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">編集画面の日時行が画面幅によって折り返していたのを修正。折り返し禁止+各入力の幅指定(狭い画面では入力側が縮む)で常に1行で表示される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">45bf09a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"今日の予定を削除しホームと重複解消。予定クリックは確認ポップアップ経由に。編集画面をGoogleカレンダー風に刷新。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">スケジュール画面の整理（重複解消・確認ポップアップ・Googleカレンダー風の編集）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「今日の予定」ブロックを削除(ホームで確認でき、選択日=今日の予定とも重複していた)。②カレンダー内の予定をクリックすると<b>確認ポップアップ</b>(色バー・タイトル・日時・繰り返し・対象利用者/担当CM・メモ)が開き、<b>編集/削除/閉じる</b>を選ぶ方式に変更(誤編集防止・Googleカレンダーと同じ操作感)。③編集画面を刷新: <b>最上部の大きな下線タイトル入力+時計アイコンつきの日付・開始〜終了1行</b>のGoogleカレンダー風レイアウトに。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f0248af</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバー調整。スケジュールをホーム直下へ。実績モニタリンググループ化。お知らせ閲覧管理へ改称。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバー調整（スケジュール位置・実績とモニタリングの統合・名称変更）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①<b>スケジュールをホームの直下</b>へ移動。②実績グループを<b>「実績・モニタリング」</b>に改め、モニタリングを中に統合(勤務表/利用者実績/モニタリング)。③「家族関係者閲覧 管理」を<b>「お知らせ・閲覧管理」</b>に改称。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c187498</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーの並びを業務動線順に変更。連絡帳→日誌→体力測定→連絡FAX→計画書→スケジュール→実績→モニタリング。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバーの並びを業務動線順に変更</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">上から ホーム/提供記録入力/連絡帳/<b>日誌/体力測定</b>/連絡(FAX)/<b>計画書</b>(毎月使うためFAXの直下へ)/スケジュール/実績/モニタリング の順に整列。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f9d6915</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーの勤務表と実績登録を実績グループに集約。実績登録は利用者実績に改称。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバー: 勤務表・利用者実績を「実績」グループに集約</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">「勤務表」と「実績登録」を開閉グループ<b>「実績」</b>にまとめ、子項目は<b>勤務表/利用者実績</b>(実績登録から改称)とした。連絡(FAX)・分析・計画書と同じ操作感。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">778a25c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"欠席・休止の特記(休みの理由)には家族非表示ボタンを出さず、家族へ必ず表示する仕様に。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">欠席・休止の特記（休みの理由）は家族へ必ず表示（非表示ボタンを出さない）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">状態が欠席・休止の行の特記は「休みの理由」であり家族と共有すべき情報のため、「家族非表示」ボタンを表示しない(=常に家族・ケアマネへ表示)。出席等の通常の特記は従来どおり非表示を選択できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">de5481b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーを整理。休み連絡と各種連絡を連絡FAXグループ、分析個人と稼働を分析グループに集約。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">サイドバーを整理（「連絡(FAX)」「分析」の開閉グループに集約）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">項目数を減らすため、<b>休み連絡/各種連絡→「連絡(FAX)」</b>、<b>分析(個人)/(稼働)→「分析」</b>を計画書と同じ開閉グループに集約(子項目名も「個人(バイタル・記録)」「稼働(実績・月次)」と役割が分かる表記に)。毎日使う提供記録入力・連絡帳・日誌はワンタップのまま維持。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2188fa5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"休み連絡\" data-text=\"休みカレンダーに月間スケジュールで付けた欠席が出ない問題を修正。末週に翌月の日付も表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">休み連絡</span><span class=\"date tnum\">2026-08-21</span></div>\n      <p class=\"title\">休みカレンダー: 月間スケジュール由来の欠席が表示されない問題を修正・末週に翌月分を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">カレンダーの欠席集計が提供記録(ticketRecords)の欠席だけを見ており、<b>利用者マスタの月間スケジュールで付けた欠席が表示されなかった</b>(佐々木様の8月・9月の欠席が出ない報告)。また月末の週は空白で埋めており、8/31(月)の週の9/1〜が見えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\">①欠席集計に<b>月間スケジュール(AM/PMセルの欠席)も統合</b>(提供記録と重複しないよう利用者単位で排除・年またぎの誤混入も防止)。②<b>末週を翌月の日付(薄表示・「翌月」ラベル)で埋めて1週間分表示</b>し、翌月分の欠席もそのまま見えて休み連絡も開ける。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e289696</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"一括評価に計画書の見直しセクションを追加。前回達成度と新短期目標だけで複製して更新が完了する。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-20</span></div>\n      <p class=\"title\">一括評価に「⑥ 計画書(3-3)の見直し」を追加（まるっとLIFEのヒアリングシート方式）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">一括評価の末尾に計画書セクションを追加。「この評価日で計画書も更新する」をONにすると、<b>前回計画の達成度(短期/長期)・新しい短期目標(機能/活動/参加)・留意事項・実施による変化/課題</b>だけ入力すれば、保存時に<b>前回計画の「複製して更新」が自動実行</b>される(達成度は前回計画書側に記入)。長期目標は「変更する」を選んだ時のみ編集(通常は引き継ぎ)。プログラム・希望・病名等も前回から引き継がれ、計画書(3-3)画面でいつでも編集可能。同じ評価日で再保存すると同じ計画書を更新(重複しない)。初回の計画書は従来どおり3-3画面から。まるっとLIFEの実ワークブック(加算アセスメントシート)の構成を確認して項目を合わせた。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3d432b9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFEタブ名を簡潔化し作成予定の各行に一括評価ボタンを追加。対象者選択済みで即起動。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-20</span></div>\n      <p class=\"title\">作成予定の各行に「一括評価」ボタン／タブ名を「LIFE」に簡潔化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①個別機能訓練・LIFEの作成予定で、利用者名の行に<b>「一括評価」ボタン</b>を追加。押すとその利用者が選択済みの状態で一括評価(ADL・生活機能・興味関心の1画面入力)が即開く。②タブ名「LIFE・一括評価」を<b>「LIFE」</b>に簡潔化。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d2c105e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書を2ハブ構成に再編。通所介護計画書と個別機能訓練LIFEを分離し件数バッジと総合事業表題切替を追加。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-20</span></div>\n      <p class=\"title\">計画書を「通所介護」と「個別機能訓練・LIFE」の2ハブに再編</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">書類ファミリーで整理: ①サイドバー<b>「通所介護計画書」</b>=作成予定(このファミリー分のみ)+計画書。②サイドバー<b>「個別機能訓練・LIFE」</b>=作成予定(3-3+加算分)+計画書3-3+生活機能3-2+興味関心3-1+<b>LIFE・一括評価</b>をタブで横断(3-1/3-2は3-3の別紙のためこちらへ集約)。<b>加算アドオンが無い店舗はハブごと非表示</b>。③サイドバーのラベルに<b>作成予定件数バッジ</b>(期限内+超過)。④利用者が要支援・事業対象者の場合、通所介護計画書の表題を<b>「個別サービス計画書(介護予防・日常生活支援総合事業)」へ自動切替</b>(フッタの事業種別も連動・3-3も同様)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f58a925</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書に共同作成者欄を追加。多職種共同作成の記録として編集画面と印刷に反映。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">個別機能訓練計画書(3-3)に「共同作成者」欄を追加</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">厚労省の別紙様式3-3自体には計画作成者欄しかないが、運営基準では個別機能訓練計画は<b>多職種が共同して作成</b>することが要件のため、その記録として「共同作成者(多職種)」欄を追加(様式への任意項目追加)。編集画面の基本情報に入力欄、印刷では計画作成者セル内に「共同作成者：」行として出力。ケアマネ送付セットの変更点一覧の比較対象にも追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0fe8e8d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFE一括評価を追加。1画面でADL・科学的介護推進・生活機能チェック・興味関心を入力し各様式へ同時反映。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">「LIFE一括評価」を追加（1画面入力→ADL・生活機能・興味関心へ同時反映）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">LIFE・加算画面に<b>「一括評価」</b>を追加。①基本情報 ②ADL(Barthel) ③科学的介護推進(身長体重・口腔・認知症診断) ④生活機能チェック ⑤興味・関心 を1画面で入力でき、保存すると<b>各様式のレコードへ同時反映</b>される(個別画面とデータ共有・二重管理なし)。④の生活機能ADLを選ぶと②のBarthel点数が未入力項目へ自動で入る(1回入力)。必須項目は赤色表示で未完なら一時保存、上部に<b>評価履歴タイムライン</b>(日付タップで過去の評価を開ける=ADLがどこに保存されたか分からない問題も解消)と<b>セクションジャンプ</b>を配置。尺度・Vitality・DBD13等の詳細は従来のLIFE・加算編集で入力。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">531c556</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFEデータ移行のCSV取込を追加。まるっとLIFE等の提出用CSVからADL評価と科学的介護推進項目を復元。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">LIFEデータ移行のCSV取込を追加（まるっとLIFE等からの乗り換え支援）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">LIFE・加算画面に<b>「CSV取込(移行)」</b>を追加。LIFE提出用CSVは全国共通仕様(v0310)のため、まるっとLIFE等の他社ソフトが出力したCSVやLIFE本体からダウンロードした過去データを読み込める。<b>科学的介護推進(TIFI2024・114列)とADL維持等(AINT2024・23列)</b>に対応し、ヘッダ有無・文字コード(UTF-8/Shift_JIS)を自動判定。<b>被保険者番号(10桁)で利用者と突合</b>し、プレビューで確認してから、ADL評価(Barthel)+科学的介護推進の固有項目(身長体重/口腔/認知症評価/DBD13/Vitality/ICF等)を評価レコードとして復元する。同じ評価日の既存レコードは重複として既定でチェックを外し、同日にTIFIとAINTの両方がある場合は1件にマージ。取込後は評価者「LIFE移行取込」として履歴に並び、以後は通常の再評価として続きから運用できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0e967bd</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"全体\" data-text=\"印刷FAX全画面に氏名マスキングを追加。3-3印刷の右端見切れも縮小で解消。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">印刷/FAXの「氏名マスキング」を全画面に追加・3-3印刷の右端見切れ解消</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①印刷プレビューのヘッダーに<b>「氏名マスキング」チェック</b>を追加。ONにすると、その印刷物/FAX内の利用者の氏名・ふりがな(姓名の連続表記も含む)が<b>●●に置換</b>されてプレビュー・印刷・PDF・FAX送付に反映される。計画書(3-3/3-4)・ケアマネ送付セット・連絡帳・実績表・休み連絡/各種連絡など<b>印刷機能のある全画面で共通</b>(開くたび既定OFF)。②個別機能訓練計画書(3-3)のA4印刷で右端が見切れる問題を全体4%縮小で解消。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a06a748</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"日誌タブの編集がタブ切替で破棄され保存しても旧値に戻るバグを修正。全行削除も保存されるように。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">日誌タブ(職員・送迎車・1日の流れ)の編集がタブ切替で破棄されるバグを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌タブのパネルはタブを開くたびに再マウントされ、その初期化が<b>未保存の編集があってもクラウドの旧値で無条件に上書き</b>していた。日誌タブ→他タブ→画面移動の流れで「保存しますか→保存する」を押しても、保存されるのは巻き戻った旧値のため「更新・削除が反映されない」ように見えた。さらに保存時の空ガードが「全行削除(空配列)」を未同期と誤解して旧値に戻していた。</span><span class=\"lb\">対応</span><span class=\"tx\">①この画面で実際に編集したキー(職員/送迎車/AM/PMの流れ)を記録し、<b>未保存の編集がある間はタブ再訪でも初期化しない</b>。②編集済みキーは<b>空配列(全削除)もそのまま保存</b>する(未編集キーは従来どおり空ガードで他端末の登録を保護)。③保存・同期完了で記録をクリア。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ff6d6aa</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"全体\" data-text=\"Windowsで文字が細く薄く見づらい問題を改善。メイリオ優先フォント・薄グレー文字の濃色化・印刷フォントも対応。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-19</span></div>\n      <p class=\"title\">Windowsで文字が細く・薄く見づらい問題を改善（フォントと薄グレーの調整）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フォント未指定のためWindowsでは游ゴシック(標準ウェイトが極端に細く描画される)が使われ、特に計画書系の小さな薄グレー文字(「前回評価から3ヶ月」等)が読みづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\">①本文フォントを<b>メイリオ優先</b>に統一(Macは従来どおりヒラギノで見た目不変)。②薄グレー(slate-400・#94a3b8)の説明文・補足を全画面で一段濃い色(slate-500相当)へ(計182箇所+クラス一括)。③計画書・帳票の印刷用フォント(16箇所)も游ゴシックの前にメイリオを追加。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8a8a04</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"日付と挨拶を1行表示に。すべて既読にするボタンを全て既読へ改称。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">ホームの日付・挨拶を1行表示に／「全て既読」へ改称</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①日付と「〇〇さん、今日もよろしくお願いします。」の2行を横並び1行にして紫のヘッダーの高さを縮小。②「すべて既読にする」ボタン(運営お知らせ/本日のスケジュール等3箇所)を「全て既読」に短縮。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a9791fc</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"運営からのお知らせを既定で閉じたバーに。新着があれば件数バッジ。スケジュールや家族更新が最初に見えるように。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">運営からのお知らせを既定で閉じたバー表示に（新着は件数バッジで通知）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">業務ではスケジュール・家族/ケアマネからの更新が主役のため、運営からのお知らせは<b>既定で閉じた薄いバー</b>にし、新着があれば赤い「新着N件」バッジで知らせる。タップで開くと従来の1行リスト(4件/頁・クリックで全文)が展開。新着が無ければ「新着なし」表示のみ。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6d5d582</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"管理局\" data-text=\"店舗一覧に法人・事業所名の検索を追加。セクションジャンプ。店舗ログイン情報ガイダンスを折りたたみ化。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">管理局コンソールを整理（店舗検索・セクションジャンプ・ガイダンス折りたたみ）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">店舗が増えた時に備えて3点整理。①店舗一覧に<b>法人名・事業所名・短縮名の検索ボックス</b>を追加。②画面上部に<b>ジャンプボタン(お知らせ管理/店舗一覧/同意ポリシー/傷病名マスタ)</b>を固定表示し、下の方のパネルへワンタップで移動できるように。③常設だった「店舗ログイン情報について」のガイダンスを折りたたみ(既定閉)にし、記載も現状(管理者PWリセットで再発行可)へ更新。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6d5d582</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"運営からのお知らせをコンパクト化。1行表示4件でクリックすると全文モーダル。画面の半分以上の占領を4分の1程度に。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-18</span></div>\n      <p class=\"title\">ホームの「つむぎ運営からのお知らせ」をコンパクト化</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">本文プレビューつきの大きなカード(3件)で画面の半分以上を占領していたのを、<b>バッジ+日付+タイトルの1行表示×4件</b>に変更(約1/4の高さ)。クリックで従来どおり全文モーダルが開く。未読は色つき・既読はグレー、「すべて既読にする」も従来どおり。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f5a6a9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"ケアマネ事業所・担当者を手入力で追加してもすぐ消える問題を修正。追加/削除の即保存化と未編集判定の穴の根治。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">ケアマネ事業所・担当者の手入力追加が数秒で消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定の未編集判定は、同期や保存の後に基準を「後で取り直す」目印(null)にしていた。4秒ごとの同期で基準がほぼ常にnullのため、その直後の最初の編集(事業所/担当者の追加)が「基準の取り直し」と誤解されて未保存扱いにならず、次の同期がクラウドの古い一覧で画面を上書きして追加が消えていた。ケアマネ以外の設定項目でも同じ穴があった。</span><span class=\"lb\">対応</span><span class=\"tx\">①<b>基準を「その場で計算した署名」で即確定</b>するように変更(同期追従・第2層・保存後の3箇所)。最初の編集が確実に未保存扱いになり、同期に上書きされない。②<b>ケアマネ事業所/担当者の追加・削除(8箇所)は保存ボタンを待たず即クラウド保存</b>に変更(削除は確認ダイアログつき)。編集モーダル・CSV取込は従来どおり(①の修正で保護される)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1f93e31</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間が手修正した次回日付ではなく自動候補日の曜日で計算され月曜なのに8時台になる問題を修正。日付連動に。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">次回お迎え時間を「表示中の次回日付」の曜日に連動（月曜なのに8時台になる問題の根治）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">次回「日付」を手修正しても、「時間」の自動計算は<b>自動が選んだ候補日</b>(例: 休止期間をスキップした先の水曜AM)の曜日で行われていた。そのため日付=月曜(PM 13:30登録)なのに時間=8時台(AMの施設提供時間から逆算)という不整合が起きていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>時間の自動計算を「表示している次回日付」の曜日で行うよう統一</b>: ①連絡帳の印刷 ②次回予定モーダルの初期表示 ③モーダルで日付を変更した瞬間の自動追従(時間を手入力済みの場合は触らない)、の3箇所。登録済み送迎時間→施設提供時間から逆算→既定値、の優先順は従来どおり。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">05f22b4</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間が送迎時間マスタと違う値になる問題。焼き付き残骸のチェック機能追加と休止期間の次回計算連動。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">次回お迎え時間の焼き付き残骸チェック機能を追加・休止期間を次回計算に連動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">連絡帳の次回お迎え時間は、記録に保存済みの値(手入力扱い)があると自動計算より優先される。過去の「次回予定モーダルを開いて保存すると全員分の自動計算値が確定値として焼き付く」不具合(修正済み)の残骸や誤入力(例: 8時)が記録に残っていると、送迎時間マスタ(例: 月曜13:30)を直しても印刷に古い値が出続けた。また次回日の計算は「休止の記録行がある日」しか除外せず、記録行が無い休止中の未来日が次回候補になり得た。</span><span class=\"lb\">対応</span><span class=\"tx\">①次回予定モーダルに<b>「残骸チェック」</b>を追加: 全期間の記録から保存値が自動計算と食い違うものを一覧表示し、選択して一括で自動計算(マスタ連動)に戻せる。分なしの時刻(8時等)は焼き付きの可能性が高いため既定でチェック済み。②<b>次回日の計算に休止期間(pauseHistory)の判定を追加</b>し、記録行が無くても休止中の日は候補から外れるようにした。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">25fab39</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"家族非表示ボタンの表記調整。表示時は家族/非表示の2行、非表示中は非表示中の1行縮小表示。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">「家族非表示」ボタンの表記を調整（2行表示／非表示中は1行縮小）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">通常時は「家族／非表示」の2行表示、押した後は赤地に「非表示中」を1行(縮小)で表示するようにした。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c1d9b0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"特記の載せる/非公開を家族非表示トグルへ置換。非表示は利用者家族のみでケアマネには常に表示。ボタンは特記の左側へ。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">特記の公開設定を「家族非表示」トグルに刷新（ケアマネには常に表示）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">従来の「載せる/✕非公開」は非公開にするとケアマネの閲覧画面からも消える仕様で、運営者の認識(ケアマネには見える)と実装が食い違っていた。また通常運用は「載せる」が基本のため、末尾のトグルは分かりづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\">①ボタンを<b>「家族非表示」トグル</b>に置換し特記欄の左側(前)へ移動。既定は表示で、押すと赤い「家族非表示中」になる。②非表示の効果は<b>利用者家族の閲覧画面のみ</b>に変更し、<b>ケアマネには設定に関わらず常に表示</b>。ご本人アカウントには従来どおり特記自体を表示しない。管理者プレビュー(家族画面)は家族と同じ見え方。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">822e5dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"提供記録同期の観察モードを追加(挙動不変)。差分刻印とユーザー実編集の食い違いをstamp-obsログで収集し、巻き戻り修正の本適用を判断する。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-17</span></div>\n      <p class=\"title\">提供記録同期の観察モードを追加（2端末同時編集の巻き戻り調査・挙動不変）</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">2端末同時編集で「PCの欠席がスマホの古い下書きに巻き戻される」「特記の入力が一瞬消える」報告。調査の結果、保存時の項目時刻(_fieldTs)刻印が「実際に編集した項目」ではなく「ベースラインとの差分」で判定されるため、編集中に他端末の変更が届くと未編集の古値が新編集として刻印される構造を特定。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>まず観察モードのみ導入(動作は一切変えない)。</b>ユーザーが実際に編集した項目を端末内で記録し、保存時の差分刻印と突き合わせて同期ログ(stamp-obs)に出力する。mis=未編集なのに刻印された項目数(巻き戻りの実例)、un=編集記録の無い行(状態モーダル・自動補正など経路の棚卸し)。数日の収集後、ユーザー編集ベース刻印(案A)の本適用を判断する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0e18b9c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"利用曜日から送迎時間を除外。日誌から反映に改称し空行を反映しない。定型文チップを全画面で廃止。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-16</span></div>\n      <p class=\"title\">通所計画書の利用曜日・1日の流れ反映・定型文チップを整理</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①「利用曜日・時間帯」の自動入力から送迎時間を除外し、曜日と時間帯(AM/PM/1日)のみに。②「各種設定の1日の流れから反映」を<b>「日誌から反映」</b>に改称し、日誌設定の余白行(時間も内容も無い行)を反映しないようにした(反映後の上部に空欄プログラムが並ぶ問題の解消)。③目標・留意事項などの下に出ていた<b>クリック追記式の定型文チップを全画面で廃止</b>(ユーザー判断: 画面の情報量を減らす)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">36e62d7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"利用者セレクトをタブ左側へ移動。作成予定を様式別グループ表示にし、行タップで対象者選択済みの編集を即開始。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-16</span></div>\n      <p class=\"title\">計画書の利用者セレクトを左側へ・作成予定を様式別表示+タップで即作成開始</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①計画書系4画面(3-3/3-2/3-1/通所)で右端にあった利用者選択をタブの左側へ移動し見やすくした。②「作成予定」タブを様式別のグループ表示に変更: 月ごとの中で<b>通所介護計画書(達成予定日/6ヶ月)・個別機能訓練計画書(3ヶ月ごと)・科学的介護推進体制加算(3ヶ月ごと)・ADL維持等加算(6ヶ月ごと)</b>に分けて周期も明記。③一覧の行をタップすると<b>その利用者が選択済みの状態で該当画面が開き、計画書は前回分の「複製して更新」が自動で始まる</b>(前回が無ければ新規作成)。加算はLIFE・加算画面が対象者選択済みで開く。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e71c1f6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族・ケアマネ閲覧画面の月平均/毎日トグルを非表示に。期間メニューの日別/月平均選択と重複していた。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-16</span></div>\n      <p class=\"title\">家族・ケアマネ閲覧画面の「月平均/毎日」トグルを非表示に（期間メニューと重複）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">半年以上の期間を選ぶと通所記録タブに「月平均/毎日」の切替が出ていたが、親ヘッダの期間メニューに「日別・○○／月平均・○○」の選択が組み込み済みで機能が重複していたため、家族・ケアマネ閲覧画面では非表示にした。事業所の分析(個人)では期間ボタンに日別/月平均の区別がないため従来どおり表示。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b556a7d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"前回計画書の評価を新規作成と同時に入力可能に。ケアマネ送付セット印刷(送付状+変更点一覧+今回+前回評価入り)を追加。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-13</span></div>\n      <p class=\"title\">前回計画書の評価の同時入力と「ケアマネ送付セット」印刷を追加（3-3・通所介護計画書）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">①新しい計画書の編集画面に「前回計画書の評価」カードを追加。前回の目標を見ながら達成度(通所は総括も)を入力でき、保存すると<b>前回の計画書側に記入</b>される。②「ケアマネ送付セット」ボタンを追加: <b>送付状+今回の計画書+前回の計画書(評価入り)</b>をA4でまとめて印刷できる。送付状は宛先(利用者マスタの担当ケアマネ事業所/氏名/FAX)・発信元(事業所情報)・送付書類一覧・前回評価サマリを自動記載し、<b>前回からの変更点一覧(目標/留意事項/プログラム等の差分表)</b>も自動生成する。個別機能訓練計画書(3-3)と通所介護計画書(3-4)の両方に対応。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c3d04d7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書系のカレンダーボタンが見切れる問題を全様式で修正。日付枠の幅も適正化。興味関心のチェックラベルを1行固定。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-13</span></div>\n      <p class=\"title\">計画書系のカレンダーボタン見切れを全様式で修正・日付枠の幅と1行ラベルも調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日付欄のカレンダー選択にネイティブのdate入力を幅36px(通所は32px)に押し込んで直接表示していたため、日付文字列の先頭とアイコンだけが見える壊れた表示になっていた(3-3/生活機能/興味関心/通所介護計画書の全日付欄と通所の目標日付5箇所)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>カレンダーアイコンのボタン表示に変え、その上に透明なdate入力を重ねる共通部品(CalendarPickBtn)へ全箇所を置換。</b>クリックで従来どおりカレンダーが開く。あわせて①日付入力枠がグリッド幅いっぱいに広がりすぎていたのを220px上限に、②興味・関心チェックの「してみたい」等のラベルが2行に折り返していたのを1行固定に修正。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">330bdeb</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"病名検索を強化。脳・腰などキーワード検索の並び順改善、読み仮名検索、空欄クリックでよく使う病名を候補表示。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">病名検索を強化（キーワード検索・読み仮名対応・よく使う病名の候補表示）</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">コードや正式病名を覚えていなくても選べるように3点強化。①「脳」「腰」など一文字のキーワードでも、<b>前方一致→名前が短い順</b>で関連病名が並ぶようにした(従来は部分一致のマスタ順で目的の病名が埋もれた)。②管理局が取り込んだマスタにカナ名称列がある場合は保持し、<b>「のうこうそく」等の読み仮名でも検索可能</b>に。③検索欄を空欄のままクリックすると<b>通所介護でよく使う病名20件(脳梗塞後遺症・変形性膝関節症・腰部脊柱管狭窄症・骨粗鬆症・パーキンソン病等)を候補表示</b>し、選ぶだけで入力できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9e69926</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"管理局\" data-text=\"傷病マスタCSV取込の名称列検出を厚労省マスタの実形式に合わせて強化。全角の正式名称を半角カナ略称より優先。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善・調整</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">傷病マスタCSV取込の病名列検出を厚労省マスタの実形式に対応</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">診療報酬情報提供サービス配布の傷病名マスターは40列超で、正式名称(漢字)より前に半角カナの省略名称列がある。名称列の検出で<b>漢字・ひらがな・全角カナを含む列(正式名称)を優先</b>し、無い場合のみ半角カナ等にフォールバックするようにした。取込に必要なのは「傷病名マスター」のみ(旧傷病名管理ファイル・移行対応テーブルは不要=過去入力コードはレコード保存でマスタ照合しない設計のため変換不要)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">616a7f1</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"管理局\" data-text=\"LIFE傷病名マスタを管理局からCSV取込できる機能を追加。全店の病名検索に自動反映。置き換え式で容量は増えない。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">LIFE傷病名マスタを管理局からCSVで取込→全店へ自動反映</p>\n      <div class=\"cf\"><span class=\"lb\">内容</span><span class=\"tx\">管理局コンソールに「LIFE傷病名マスタ管理」を追加。厚労省の傷病名マスタCSV(UTF-8/Shift_JIS自動判別・コード列と病名列を自動検出・重複除去)を取り込むと全店共通の予約キーに保存され、個別機能訓練加算が有効な全店舗の病名検索に自動反映される。未取込の間は同梱マスタ(約2.7万件)を使用。</span><span class=\"lb\">設計</span><span class=\"tx\"><b>置き換え式(常に最新1版のみ保持)のため取込を繰り返しても容量は増えない。</b>読込は病名検索を開いた時に1回だけのオンデマンド取得で、店舗同期(pull/push)からは独立しており同期速度に影響しない。過去に計画書へ入力済みのコード・病名は各計画書レコード側に保存されているため、マスタ入替の影響を受けずエラーにもならない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0dc6abd</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"LIFE\" data-text=\"LIFE個別機能訓練の傷病名コードが7桁未満で出力される問題を修正。ゼロ埋めで提出エラーを防止。任意→原則入力に表記修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">LIFE</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">LIFE傷病名コードの先頭ゼロ落ちをCSV出力時に7桁ゼロ埋めで補正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同梱の傷病名マスタ約2.7万件のうち290件(未コード化傷病名999、Ａ型肝炎701001等)は先頭ゼロが落ちた状態で収録されており、LIFE仕様の7桁固定(例: 0000999)と桁が合わないCSVが出力される恐れがあった。あわせて画面の「傷病名(任意)」表記は国仕様の必須区分「○(原則必須・記録不可の場合のみ空欄可)」と不一致だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>CSV出力時に傷病名コードを7桁ゼロ埋めするようにした。</b>表記も「原則入力」に修正し、説明文に空欄可の条件を明記。なお9999999「その他」というコードは国のマスタに実在しない(未コード化は0000999)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">614eda7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームのボタンが反応しない・PDF添付サムネイルがチカチカする問題を修正。PDFはサムネイル枠にPDFと表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">ホームのボタン不発とPDF添付サムネイルのチカチカを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ホームのカード/タイル部品がビュー内部で毎描画ごとに定義し直されており、4秒ごとの同期のたびにReactがホームのDOM全体を破棄→再構築していた。タップ中のボタンが押下と離しの間に破棄されてクリックが不発になり、PDF添付は画像として読込→失敗を繰り返して空白がチカチカしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>部品をモジュールレベルへ移動し、同期の再描画でDOMが再利用されるようにした。</b>あわせてPDF添付は画像に流し込まず、サムネイル枠に「PDF」と表示するようにした(クリックでのプレビューは従来どおり)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">aad5ffa</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書の印刷用シートが画面に常時表示され一覧が隠れる問題を修正。印刷レイアウトも固定行高の自然な組みに変更。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">個別機能訓練計画書(3-3)を開くと印刷シートが常時表示され一覧が使えない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回の重なり修正で入れた印刷用CSS(display:flex!important)が、非表示指定(display:none)を打ち消して画面上でも印刷シートを常時表示させていた。シートが画面を占領して既存の一覧(編集/複製して更新/削除)が隠れ、A4固定高に押し込まれて上下が潰れて見えた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>A4をflexで使い切る方式を廃止し、紙の様式らしい固定行高で自然に組むレイアウトへ変更。</b>画面では従来通り非表示に戻り一覧が復活。印刷でも空欄行が不自然に間延びしなくなった(行数が多い時の自動縮小は維持)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a4e02d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書でプログラム行が多いと文字が表に重なる問題を修正。行数に応じて自動縮小。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">個別機能訓練計画書(3-3)で文字が表に重なる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニューの自動読込でプログラム行が8行を超えると、A4に収める伸縮レイアウトから溢れ、下のセクションに文字が重なって表示・印刷されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>行数に応じて文字サイズと余白を自動で縮めて枠内に収めるようにした(番号も⑮まで対応)。</b>各枠にはみ出し防止も追加し、レイアウトが崩れない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e51057d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"LIFE評価入力の必須項目を色分け表示。必須未入力は保存不可で一時保存ボタンを新設。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-08-12</span></div>\n      <p class=\"title\">LIFE評価入力の必須項目を色分け+未入力は保存不可(一時保存は可能)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">LIFE提出に必要な項目がどれか分かりにくく、未入力のまま保存されて提出時にエラーになることがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>必須項目(評価日・ADL10項目・科学的介護推進の身長/体重/口腔4項目)を薄い赤背景+「必須」バッジで表示。未入力のままの保存は不可(未入力一覧を表示・保存ボタンに残数)。「一時保存」なら途中でも保存でき、後から完成させられる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7ec8bbf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"全体\" data-text=\"サイドバーが表示されない問題。開閉状態を端末に記憶し再読み込み後も維持するように修正。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">全体</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">サイドバー開閉の記憶+提供記録の横スクロールバー常時表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サイドバーの開閉は毎回「画面幅」で自動判定されており、再読み込みや「今すぐ更新」のたびに初期化されるため、開いていたはずのサイドバーが表示されないことがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①サイドバーは開閉ボタンでの操作を端末に記憶し、再読み込み後も同じ状態を復元。②提供記録入力の上部横スクロールバーを自前描画(レール+つまみ)に変更し、どの環境でも必ず表示。つまみのドラッグやレールのクリックで表を横スクロールできる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2e1c24</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"施設の休業日は提供記録入力の利用者の状態が自動で休業になる。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">施設の休業日は利用者の状態が自動で「休業」になるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">各種設定で休業日(例: 8/12〜8/14)を設定しても、提供記録入力ではその日の利用者が全員「出席」のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>休業日に提供記録入力を開くと、その日の利用者全員の状態が自動で「休業」になり、特記に休業名(例: 夏季休業)が自動記載される。</b>休止中の人は休止のまま。バイタル等を入力済みの記録は変更しない(誤設定の保護)。休業日の追加・削除は画面に即反映。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bdd54c9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"休止を再開すると過去の休止期間まで出席表示に戻る問題と終了日を過ぎても提供記録が休止のままの問題を修正。期間ベース判定に。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">休止の表示を「設定した期間の中だけ休止」に統一(再開後も期間表示を維持)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①休止の判定が「現在休止中であること」を前提にしていたため、利用を再開した瞬間に過去の休止期間の表示(月間スケジュール・提供記録)まで全て消えて出席予定に戻っていた。②休止中に自動保存された記録の「休止」が終了日を過ぎた日にも残り、提供記録入力が休止のまま表示され続けていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>終了日つきの休止は現在の状態に関係なく「期間内=休止」で判定するよう変更。月間スケジュールも提供記録も、設定した休止期間の中だけ休止・それ以外は通常表示で一貫。終了日を過ぎた日に残った休止の残骸は出席に自動補正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">abb1cca</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"アカウント発行管理で登録済みアカウントが点滅したり消えたりする問題を根本修正。取得エラー時の空上書きが原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">アカウント発行・管理で登録済みアカウントが点滅・消失する問題を根本修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族アカウント/招待一覧の取得が、通信エラー時にも「空の一覧」を正常な結果として返していた。10秒ごとの自動更新で空が画面に上書きされ、登録済みアカウントが消えたり表示/非表示を繰り返していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>取得に失敗した時は画面に触れないようにし、成功した内容が今の表示と同じなら何もしない方式に変更。</b>別の原因で一覧が消えても次の自動更新(10秒)で復元される。あわせて基準値の透かし表示は「開いた時点で既に○が入っていたセル」だけに調整(○を入力した直後は○のみ表示)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">956345c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"運動セルで○×から数字を打つと記号を自動クリア。記号だけのセルには基準値を薄く並記。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">運動セルの入力改善(記号の自動クリア+基準値の薄表示)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">○が入ったセルに数字を打つと「○3」と連結されてしまい、記号を消してから入力し直す必要があった。また○を押した後に基準値を確認できず、消して確認して再入力する手間があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①○/×/－の状態で数字を打つと記号が自動で消えて数値だけになる。②記号だけのセルを選択中は記号が薄くなり基準値が透かし表示され、消さなくても基準値を確認できる(未選択時は記号のみ)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec31334</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"個人ファイル\" data-text=\"フェイスシートの新規作成を廃止し常に編集追記に。全利用者に最初から用意されている扱い。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">個人ファイル</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">フェイスシートを「新規作成」から「編集・追記」の常設方式に変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">フェイスシートは全利用者に必ず用意する運用のため、「新規作成」という入口は実態に合わなかった。基本情報・ご家族登録・家族側の編集内容が自動で反映されるようになったこともあり、常に存在する書式として扱う。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ボタンを常に「編集・追記」に変更(PDFも常時表示)。</b>未入力の場合はその旨を案内。将来の電子契約書からの自動反映の受け皿にもなる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">476ad3f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"アカウント発行管理モーダルが上下に揺れて表示非表示を繰り返す問題を修正。10秒ごとの無条件保存が原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">アカウント発行・管理の画面が揺れ続ける問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族アカウント一覧の自動更新(10秒ごと)が、内容が変わっていなくても毎回全体保存を実行し、モーダルが再構築されて上下に揺れ・点滅していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サーバーの応答が前回と同じ場合は何もしないようにした。</b>実際に変化があった時だけ画面を更新する。あわせて分析個人の期間指定も家族側と同仕様(年4桁上限・逆転防止・片側未指定の既定)に統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">476ad3f</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析\" data-text=\"月別通所状況で利用開始前の0%の月を表示しない。注記つき。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">月別通所状況から「利用開始前の月」を除外(0%の羅列をなくす)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">1年表示などで利用開始前の月が0%として並び、実際の通所状況が読み取りにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用開始日より前の月を表示せず、「※利用開始(日付)前の月は表示していません」と注記。</b>開始日未設定の利用者は先頭から続く記録ゼロの月を省略する。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1a2a75e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"続柄が本人のアカウントが緊急連絡先に表示される問題を修正。表示と編集経路の両方でガード。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">続柄「本人」が緊急連絡先に表示される問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">新規登録時の除外は実装済みだったが、修正前に登録された旧データと「登録者情報の編集」経由で、ご本人の閲覧用アカウントが代表家族(緊急連絡先)欄に入る経路が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>緊急連絡先の表示処理で続柄「本人」を一括除外(全画面に有効)。登録者情報の編集でも本人なら代表家族欄に書かないようにした。</b>ご家族が登録すれば従来どおり緊急連絡先に反映される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1a2a75e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"家族アプリ\" data-text=\"家族や本人が編集したメールかかりつけ医医療機関がフェイスシートと事業所に反映されない問題を修正。送信パッチの欠落。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">家族・本人が編集した利用者情報の一部が事業所に反映されない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族側の利用者情報保存で、クラウドへ送る内容からメールアドレス・かかりつけ医・医療機関名・医療機関の連絡先が漏れており、更新通知には項目名が出るのに実データが事業所・フェイスシートに届いていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>欠落4項目を送信に追加し、フェイスシートの医療欄(主治医/医療機関/連絡先)へも部分同期する専用処理を新設。</b>フェイスシート全体を上書きしない安全な方式(指定欄のみ更新+同期保護の刻印)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a2e7c67</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"お知らせの見出し日付を投稿日に変更。予定から配信したお知らせが未来日に見えていた。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">お知らせの見出し日付を「投稿日」に変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">担当者会議などの予定から配信したお知らせは、見出しの日付が開催日(未来日)になっており、いつ投稿されたのか分かりにくかった。開催日は本文に記載済み。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>見出しの日付は投稿日を優先して表示。</b>開催日は従来どおり本文で確認できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">53be664</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"期間セレクトを独自ドロップダウンに。日別で表示と月平均で表示の見出しが濃い緑バーではっきり見える。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">期間の選択メニューを見やすい独自デザインに変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">端末標準のメニューではグループ見出し(日別で表示/月平均で表示)の色を変えられず、薄いグレーで読みづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>独自のドロップダウンに置き換え、見出しを濃い緑のバーとして配置。その下に1ヶ月/3ヶ月/半年/1年/全期間/期間を指定が並び、選択中の項目に✓が付く。</b>どの端末でもはっきり読める。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">53be664</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"スマホタブレットの入力枠に選択中ハイライトを追加。期間セレクトの見やすさ改善も。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-11</span></div>\n      <p class=\"title\">スマホの入力枠に選択中ハイライト+期間セレクトの文言改善</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">スマホ・タブレットのテンキー入力で血圧などを押しても、PC版と違いどの枠を入力中か分からなかった。また閲覧画面の期間セレクトのグループ見出しがネイティブメニューで薄く表示され読みづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①バイタル・運動の入力枠にPC版と同じ青枠リングの選択中ハイライトを追加。②期間の選択肢自体に「日別・」「月平均・」を明記し、どの端末でもはっきり読めるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">039eff1</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"期間指定の改善。月別通所状況が指定範囲どおりに。逆転入力防止。日別と月平均のグループ分け。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">期間指定の改善(範囲どおりの月別表示・逆転防止・日別/月平均のグループ分け)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">期間指定で月別通所状況が常に12ヶ月分出る、開始と終了を逆に選べてしまう、日別と月平均の選択肢が混ざって見づらい、という指摘があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①月別通所状況は指定した年月範囲の月だけ表示。②逆転入力は自動で揃う。③開始未指定=終了の1年前から/終了未指定=今月まで。④期間セレクトを「日別で表示」「月平均で表示」のグループに再編成し、期間指定にも日別/月平均を用意。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9e26cd0</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"家族アプリ\" data-text=\"家族ケアマネ閲覧で8月3日以降のバイタル気分記録が表示されずグラフが止まっていた問題を修正。提供記録テーブルを読むように。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">家族・ケアマネ閲覧で8/3以降の記録が表示されない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">閲覧画面は従来のデータ(巨大JSON)しか読んでおらず、提供記録を専用テーブルに切り替えた8/3以降の新しいバイタル・気分・記録が届いていなかった(グラフが8/3で止まる・今回の記録が空・出席数だけ合う)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録テーブルを起動時+60秒ごとに取得して表示に反映。</b>15秒ごとの受信が古い凍結データで上書きしないよう保持も追加。削除済みの記録は表示されない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50a603d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"閲覧画面の期間に期間を指定を追加。見たい年月の範囲を自由に選べる。ケアマネ要望。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">閲覧画面の期間に「期間を指定」を追加(見たい月を自由に選択)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">期間が1ヶ月/3ヶ月/半年/1年/全期間の固定で、「6月の記録だけ見たい」のような指定ができないとケアマネから要望があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間セレクトに「期間を指定」を追加。年月の範囲(例: 2026年6月〜2026年6月)を選ぶと、その期間のグラフ・記録が表示される。</b>ご家族・ケアマネ両方の閲覧画面で利用可能。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50a603d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"削除や変更が一瞬元に戻ってから反映されるちらつきの恒久対策。利用者マスタと月間シフトに手元が新しければ保持のマージを追加。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">削除・変更が「一瞬元に戻ってから反映される」ちらつきの恒久対策</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド受信は利用者マスタ・月間シフトをクラウドの内容で丸ごと置き換えるため、保存がクラウドへ届く前の受信(4秒ごと)で古い内容に一瞬巻き戻り、保存完了後の受信で再び新しい内容に戻っていた(休止履歴を削除すると一瞬復活する等)。記録・設定・既読には保護があったが、この2つには無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>受信時に「手元の方が新しい利用者・シフトは保持」するマージを追加。</b>新規追加直後の利用者も消えない。保持が発生した分は自動で再送信され、確実にクラウドへ反映される。一度設定・削除した内容がそのまま画面に残り続けるようになる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fcae62a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"休止の終了日を過ぎても現在休止中が消えない問題を修正。利用を再開ボタンは再開日を入力する方式に変更。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">休止の終了日を過ぎても「現在休止中」が消えない問題を修正+再開日入力式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「現在休止中」バナーが利用者の状態フラグを直接見ていたため、休止の終了日(例8/9)を過ぎても「利用を再開」を押すまで表示が消えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①日付判定つきの表示ステータスで判定するよう修正。終了日を過ぎると自動で休止表示が消える(家族画面も同様)。②再開ボタンは「再開日を設定」に改名し、再開日の入力画面を出す方式に変更。再開日を入れると休止の終了日=前日を自動記録。未来の再開日ならその日まで休止のまま・当日から自動再開。</b>終了日の直接入力でも過ぎれば自動解除される。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3801685</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"休止履歴の日付入力で西暦が6桁入力できてしまう問題を修正。年4桁制限の独自入力に統一。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">休止履歴の日付入力で西暦が6桁入ってしまう問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">休止履歴の一覧行(終了日)と編集画面(開始日/終了日)がOS標準の日付入力のままで、年を「202622」のように6桁まで入力できてしまっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>年4桁制限・自動送り・クリア(✕)つきの独自日付入力(SmartDateInput)に3箇所とも統一。</b>利用開始/終了日と同じ入力方式になった。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d44389f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"スマホの血圧入力で自動表示のスラッシュを入力済みと誤認し下の値が上に連結される問題を修正。スラッシュは自分で打った時だけ表示。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">スマホ血圧入力の自動スラッシュ表示をやめる(「1264」誤連結の防止)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">上の血圧だけ入力した段階で枠に「126/」と自動表示されるため、スラッシュが入力済みと誤認して下の値を続けると、実際にはスラッシュが入っておらず「1264」と上の値に連結されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>スラッシュは自分で「/」キーを打った(=下の値がある)時だけ表示。テンキーで入力中の枠は、打った内容(スラッシュ含む)をそのまま表示する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a53d336</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基準値の指定せず保存が提供記録入力に反映されない問題を修正し過去全ての記録に反映と日付を指定して反映の2択に改名。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">基準値の反映を「過去全ての記録に反映／日付を指定して反映」の2択に(未反映バグ修正)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「指定せず保存」は現在値だけ更新して変更履歴を触らないため、過去に日付指定の変更をしたことがある利用者では履歴側が優先され、新しい基準値が提供記録入力のグレー数値に反映されなかった。文言も意味が分かりにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「過去全ての記録に反映」(変更した項目だけを全期間にさかのぼって反映・他項目の日付つき履歴は保持)と「日付を指定して反映」(選んだ日から新値・備考に自動記載)の2択に改名・整理。</b>説明文もモーダル内に明記。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c3f27e9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"すべて既読ボタンを家族ケアマネ更新と本日のスケジュールにも追加。既読を即クラウド送信し同じスタッフのiPadとPCで既読が同期するように。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">「すべて既読」を全セクションに追加+既読が同じスタッフの全端末で同期</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「すべて既読」が運営からのお知らせにしか無く、家族・ケアマネからの更新等は1件ずつ開く必要があった。また既読が端末内に留まり、次に何かを保存するまでクラウドへ送信されないため、同じスタッフでもiPadとPCで別々に既読操作が必要だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「家族・ケアマネからの更新」「本日のスケジュール」にも「すべて既読にする」を追加。既読を付けた瞬間にクラウドへ送信するようにし、同じスタッフの他端末でも数秒で既読が反映される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c3f27e9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替の取り消しが効かず数秒後や再読み込みで復活する問題を修正。テーブル側の削除が呼ばれていなかった根本原因。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-10</span></div>\n      <p class=\"title\">振替の取り消しが効かない(数秒後・再読込で復活)問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">取り消しはアプリ内データと墓石(削除記録)だけを更新し、提供記録テーブル側の削除処理が一度も呼ばれていなかった。テーブルの行が生き残るため、数秒後の受信や再読み込みで必ず復活。さらに受信側は削除を「当面反映しない」実装だったため、削除が他端末に伝わらなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①取り消し時に該当idだけをテーブルにも論理削除(推測削除はしない=誤爆防止)。②受信側で明示削除を反映(入力済みバイタルがある新しい記録は保護)。③削除済み記録は再読み込み時のキャッシュ統合・他端末の再送からも復活させない(墓石ガード)。</b>取り消しが1回で確実に効き、全端末に伝わる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9ed1535</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"店舗切替を完全リロード方式に変更。前店舗のメモリ内データの持ち越しを物理的にゼロにし店舗間混入を根絶。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-09</span></div>\n      <p class=\"title\">店舗切替を「完全リロード」方式に変更(持ち越しの物理的根絶)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">店舗間のデータ混入バグは「切替端末のメモリ内に前店舗のデータが残る」ことが共通の温床だった。既知経路は4重のガードで遮断済みだが、未知の持ち越しまで根絶する構造的対策として運営から切替時リロードの要望があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>店舗切替の全4経路(管理局からの入店・サイドバー直接切替・店舗一覧へ戻る×2)を「切替先をセッションに保存→ページ完全再読み込み」方式に変更。</b>新店舗として起動し直すため、メモリ内の持ち越しが物理的にゼロになる。切替に数秒かかるようになるが安全性を優先。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ab02134</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"墓石に出所店舗タグを刻印し他店の墓石を構造的に受け付けない最終防壁。事業者間の干渉防止。\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-09</span></div>\n      <p class=\"title\">墓石(削除記録)に店舗タグを刻印 — 他店の墓石を構造的に拒否する最終防壁</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">南水元事故は他店の墓石混入が原因だった。経路自体は遮断済みだが、将来未知のバグで同型の混入が起きた場合に備えた構造的防御が求められた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期を通る墓石一式に出所店舗タグ(_store)を刻印し、pull・push・初回シードの全経路で「タグが保存先店舗と食い違う墓石」を丸ごと読み捨てる。</b>タグ無しの既存データは従来どおり扱う(後方互換)。これで仮に混入しても削除は発動しない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3a45c2e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"店舗切替時に前店舗の家族アカウントと提供記録がメモリに残り新店舗で表示・書き込みされ得た問題を修正。法人間の情報混入防止。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-09</span></div>\n      <p class=\"title\">店舗切替時に前店舗の家族アカウント・提供記録を持ち越さないよう修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">店舗切替の瞬間、前店舗の家族アカウント一覧と(テーブル方式の)提供記録がメモリ内に残る実装だった。家族アカウントは利用者IDで紐づくため、別店舗の同じIDの利用者に他店(他法人)の家族が表示され得た。前店舗の記録が新店舗の画面に残る経路もあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>切替時(直前データが別店舗と判明している時)は家族アカウント・招待・提供記録を持ち越さず、新店舗のデータ再取得に任せるよう修正。</b>起動直後の保持(消失防止)は従来どおり維持。あわせて家族一覧の未使用APIにも店舗ID必須化を実施。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3a45c2e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"運用\" data-text=\"復旧手順書のWebページを新設。症状のキーワード検索と手順コードR-xxでデータ消失時の対処法を引ける。運営用。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">運用</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">復旧手順書のWebページを新設(/api/runbook・症状検索/手順コード付き)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">データ消失事故の対処法を運営側の誰でも確認できるようにし、症状から手順を即座に引ける形が必要になった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>台帳と同じ認証のWebページ /api/runbook を新設。「利用者が消えた」等の症状キーワード検索と、R-00(鉄則)〜R-92(スナップショット設定)の手順コードで対処法・SQL・Claudeへの依頼文例まで表示。</b>技術詳細版はリポジトリ docs/incident-recovery-runbook.md に併設。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02ecc46</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"店舗切替pullで前店舗の墓石が新店舗へ混入する経路を遮断。南水元全利用者消失の根本原因修正。push側にも店舗不一致ブロックの二重防御。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">店舗切替pullの墓石混入を根本修正(南水元事故の原因)+push店舗ゲート</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pull時の墓石(削除記録)和集合だけ「直前のデータが同じ店舗のものか」の確認が漏れており、店舗切替直後や放置復帰の自動pullで前店舗の墓石が新店舗に混入。idが重なる利用者・記録が全端末で削除された(試作店の墓石193個→南水元47名全削除の直接原因)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>pull墓石和集合に店舗一致ガード(prev._sbStoreId===newStoreId)を追加。さらにpush入口にも店舗不一致ブロックを追加し、別店舗のスナップショットを書き込めない二重防御に。</b>誰も操作していなくても自動同期だけで発生し得た経路を遮断。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1c94e13</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"運動メニュー個別運動メニューの追加削除が1回目だけ一瞬で元に戻る問題を修正。2回目以降は効くのに1回目だけ巻き戻る。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">運動メニューの追加・削除が1回目だけ元に戻る問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド定期受信の再同期が未保存判定の基準を一旦リセットした直後に項目を追加/削除すると、編集後の内容がそのまま新基準になり「編集済み」フラグが立たず、次の受信(4〜10秒後)でクラウド値に巻き戻っていた。2回目は基準が残るため差分検知が効き成功していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>運動メニュー系のユーザー操作用セッターを分離し、操作した瞬間に「未保存」を立ててから反映する方式に変更。</b>クラウド同期由来の反映は別経路(生セッター)にして誤検知も防止。1回目から確実に追加・削除できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1c94e13</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"南水元へ混入した他店墓石を無効化するアムネスティ。利用者47名が全端末で削除され続ける事故の恒久対策。\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"crit\">重大</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">南水元の全利用者消失: 混入した他店墓石のアムネスティ(3経路)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">試作店で7/17に一括削除された193名分の墓石(削除記録)が8/7 01:25に南水元のキーへ混入し、利用者47名(id31〜77)が墓石の対象になり全端末で削除され続けた。バックアップから書き戻しても端末に残る墓石が和集合マージで再削除するため復元が定着しない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>南水元に限り、カットオフ(8/7 14:00 JST)より古い墓石を pull・push・初回シードの3経路すべてで読み捨てる。</b>以後の正規削除は新しい時刻が付くため通常運用に影響しない。8/6バックアップからの利用者47名書き戻しSQLとセットで復旧完了。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">164d140</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"利用者の削除・一括削除を変更ログに端末名つきで明示記録。削除操作の追跡を可能に。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">削除・一括削除を変更ログに明示記録(端末名つき)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">利用者の全削除事案で、削除操作が変更ログから追跡できないことが判明した。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>単体削除は【削除】氏名、一括削除は【一括削除】N名(氏名先頭)を、実行端末名つきで必ず変更ログに記録。</b>誰がいつ消したかを後から追跡できる。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">6b9fe0f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"基準値の復元を変更履歴ベースに修正。既定フォールバックでは店舗独自の項目idと一致せず未設定のままだった。履歴の直近リストから項目とidを復元し基準値が正しく復活。全削除はフラグで尊重。eb16559\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">基準値の復元を「変更履歴からの復元」に修正(独自項目のidごと復活)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回の既定項目フォールバックでは、店舗独自の運動項目id(基準値のキー)と一致せず、基準値が未設定のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>空/未設定時は変更履歴(exerciseItemsHistory)に残る直近の項目リストから復元するよう修正。店舗独自の項目名とidが戻り、利用者の基準値も正しく復活する。運動メニューを全削除した場合はフラグで空を尊重(勝手に復活しない)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb16559</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"データ保護ゲート2件: 管理者自動連携の書込をクラウド初回反映後に制限。退所自動削除に不正日付/年数の防護と墓石処理を追加。eb16559\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">データ保護の強化(自動書込ゲート・退所自動削除の防護)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">起動直後の古い/空のローカルスナップショットからの自動書込や、日付入力バグの残骸(不正な終了日)による退所自動削除の誤作動が、データ消失の潜在リスクだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>管理者自動連携の書込は「クラウド初回反映後」のみに制限。退所自動削除は年数2/5のみ有効・終了日が2020年未満/未来年ならスキップし、削除時は墓石まで一括処理して他端末との不整合を防ぐ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb16559</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"サービス提供内容の基準値が全員分消えて見える問題を修正。運動メニュー項目が空配列で上書きされるとフォールバックが効かず全画面から運動列と基準値が消えて見えた。空は既定項目へフォールバックし基準値は自動復活。ee0dfe9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">基準値(運動メニュー)が全員分消えて見える問題を修正(自動復活)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニュー項目(exerciseItems)が設定不具合で空([])に上書きされると、空配列は「設定あり」と判定され既定項目に切り替わらず、利用者マスタの基準値・提供記録の運動列が全員分消えて見えていた。利用者側の基準値データ自体は残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>空配列を「未設定」とみなして既定の運動項目へフォールバックする処理を全33箇所に適用。既定項目が表示されることで、残っていた基準値も自動的に復活する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ee0dfe9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"管理者名の自動連携。スタッフ切替/日誌の管理者を事業所情報へ常時反映し表示のみに。サ責は未設定なら管理者を既定に。ee0dfe9\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">管理者名を自動連携(事業所情報は表示のみ)・サ責の既定値</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">初回に管理者を登録しても事業所情報の管理者名は手入力が必要で、二重管理でズレも起きていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>スタッフ切替/日誌で登録した「管理者」を事業所情報の管理者名へ常に自動反映し、各種設定では表示のみ(編集不可)に。サービス提供責任者は未設定なら管理者を既定にセット(後から変更可)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ee0dfe9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"実績登録\" data-text=\"実績登録を月間一覧/利用者ごとのタブ構成に。サービスコード複数割当とCSV取込(国/自治体コード表・UTF-8/Shift_JIS)を追加。ee0dfe9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">実績登録</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">実績登録を改良(利用者ごと表示・複数コード割当・コードCSV取込)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">実績登録が全体一覧のみで使いづらく、サービスコードは複数登録が必要、国/自治体のコード表CSVも取り込みたいとの要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「月間一覧」「利用者ごと」のタブ構成に(氏名クリックで個人詳細)。利用者ごとにサービスコードを複数割当でき、日別実績(状態/時間帯/サービス内容/備考)を一覧表示。コード表CSVは文字コード自動判別で解析しプレビューから選択取込。画面はつむぎ独自仕様。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ee0dfe9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"サイドバー最下部に利用規約・同意ポリシーの閲覧を追加(全スタッフ・事業所向け/家族向けタブ)。家族・ケアマネ画面は既設を確認。\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">サイドバーに「利用規約・同意ポリシー」の閲覧を追加</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">同意ポリシー編集を運営(管理局)専用に集約したため、事業所側でも内容をいつでも確認できる入口が必要になった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サイドバー最下部(不具合を運営に報告の下)に閲覧ボタンを追加。</b>事業所・スタッフ向け/ご家族・関係者向けをタブで切替表示(版・改定日つき)。ご家族・ケアマネ画面には報告/規約の入口が既設であることを確認。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">51c8402</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"各種設定の事業所情報や項目管理が消える問題の恒久対策。ローカルstateがマウント時のまま古く、保存で古いスナップショットが最新値を上書きしていた。3層対策+facilityInfoサブ項目マージ。ecdf40e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">各種設定の登録内容(事業所情報・項目管理等)が消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定のローカル状態はマウント時に1回だけ初期化され、以後クラウドから最新が来ても古いまま。保存すると古いスナップショットが最新時刻で丸ごと書かれ、後から登録した事業所情報・項目管理・ケアマネ等を消していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>3層の恒久対策: ①マウント時基準を記録 ②クラウド同期で未編集の画面を最新へ自動再同期 ③保存は「実際に編集した項目だけ」を最新へ重ねる(事業所情報はサブ項目単位)。同期マージも事業所情報をサブ項目単位(fi:)で刻印・マージ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ecdf40e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"実績登録\" data-text=\"サイドバーに実績登録を新設(分析稼働から移設)。サービスコードの登録と利用者割当を追加しCSVにも出力。91472e8\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">実績登録</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">サイドバーに「実績登録」を新設(サービスコード登録・割当つき)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">月次実績表を分析(稼働)内に置いていたが、毎月の請求転記業務として独立した入口が欲しい+サービスコードも必要との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サイドバーに「実績登録」を新設して月次実績表を移設。サービスコードの登録(コード+名称)と利用者ごとの割当を追加し、表とCSVに出力。割当・台帳とも項目単位保護で同期安全。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">91472e8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"同意ポリシー編集の案内を各種設定から撤去(管理局専用)。不具合を本部に報告→運営に報告へ名称変更。ecdf40e\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-07</span></div>\n      <p class=\"title\">同意ポリシー編集を各種設定から撤去・「不具合を運営に報告」に名称変更</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">同意ポリシーはアプリ運営(管理局)が全店共通で管理するため、各事業所の設定画面には不要。報告先の名称も実態に合わせる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定のサービス提供内容から同意ポリシー編集の案内を撤去(編集は管理局専用のまま)。サイドバーの「不具合を本部に報告」を「不具合を運営に報告」へ変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ecdf40e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析(稼働)に月次実績表を追加。提供記録の実績(出席/振替/臨時)を利用者×日のマトリクスで表示し、実績回数・日別合計・CSV出力・印刷PDFに対応。カイポケ等への実績転記を高速化。分析1d7b862\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">月次実績表を追加(カイポケ等への実績転記用・CSV/印刷対応)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">毎月の請求ソフト(カイポケ等)への実績入力で、つむぎの記録を1件ずつ確認しながら転記する手間がかかっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>分析(稼働)の下部に月次実績表を追加。</b>出席○/振替/臨時/欠席を利用者×日のマトリクスで一覧でき、行末に実績回数・最下行に日別合計。前月/翌月切替・CSV出力・印刷/PDF(A4横)対応。日付整合ゲートで残骸は実績に混ぜない。読み取り専用で同期への影響なし。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1d7b862</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"LIFEの傷病名マスタ約2.7万件を同梱し、個別機能訓練計画書のLIFE提出用コードに病名検索を追加。病名で検索して選ぶとコードが自動入力される。ひらがなカタカナ全角半角も吸収。計画書91aba3a\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">LIFE傷病名マスタ同梱+計画書に病名検索(コード自動入力)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">LIFE提出用の傷病名コードは7桁の手入力のみで、コードを調べる手間がかかっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>厚労省の傷病名マスタ約2.7万件を同梱し、個別機能訓練計画書(3-3)のLIFE提出用コードに病名検索を追加。</b>病名で検索して選ぶとコードが自動入力される(ひらがな・カタカナ・全角半角も吸収)。マスタは初回検索時にだけ読み込むためアプリは重くならない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">91aba3a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"デザイン\" data-text=\"ブラウザのタブ/ブックマークのアイコンが白背景で見づらいのを、正式マーク無加工のまま淡い緑の角丸チップ土台に載せた合成faviconで解消。ライト/ダーク両テーマで視認可。デザインe1e19a7\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">デザイン</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">タブ/ブックマークのアイコンを見やすく(角丸チップの土台を追加)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ブラウザのライトモードでタブ/ブックマークのアイコンが白背景に溶けて見づらかった(マークが淡く小さい)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>正式マークPNGを無加工のまま、淡い緑グラデの角丸チップ+縁取りに載せた合成faviconに差し替え。</b>ライト/ダークどちらのテーマでもチップの土台で視認できる。ロゴ自体は描き直していない。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e1e19a7</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"マニュアル\" data-text=\"操作マニュアルのヘッダーロゴを中央寄せにし、つむぎとはを機能紹介中心に簡潔化。名前の由来の段落を削除。もくじ表記も統一。マニュアル4a71ec6\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">マニュアル</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">マニュアルのロゴ中央寄せ・「つむぎとは」を機能紹介中心に簡潔化</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">マニュアルのロゴが左寄せで表題と揃わず気になる、「つむぎとは（名前の由来）」は機能の簡単な説明でよい、との指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ヘッダーロゴを中央寄せ(margin:0 auto)にし、もくじ/見出しを『つむぎとは』に統一。名前の由来の段落を削除し、つむぎで何ができるかの簡単な説明のみにした(3マニュアル共通)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4a71ec6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームのお知らせ類をもっと見るからページ送り(＜1 2 3＞)に変更し高さを揃えた。更新内容モーダルは起動後に増えた今回分だけ表示。サイドバーの計画書だけ左詰めだったのを中央寄せに統一。ホームc76dc47\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">ホームをページ送り化・更新モーダルを今回分のみ・計画書の左詰め修正</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ホームのお知らせが下に長く伸びて見づらい、事業所お知らせが長いと左カラム下部に空白ができる、更新モーダルが3件全部出て今回分が分かりにくい、計画書サイドバーだけ左詰め、という指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>お知らせ類を『＜ 1 2 3 ＞』のページ送りに変更(運営3件/家族更新5件/お知らせ5件/頁)。更新内容モーダルは起動後に増えた今回分だけ表示。計画書サイドバーのtext-leftを外して他と中央寄せに統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c76dc47</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌で振替の重複記録により利用者が二重表示される問題を修正。提供記録入力連絡帳は解消済みだったが日誌はticketRecordsをそのまま行にしていた。出席者テーブルと送迎割り当てで利用者ID単位に重複排除。日誌f3a83d4\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">日誌で振替の重複により利用者が二重表示される問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌は提供記録をそのまま行にしており、同一利用者・同一日の複数記録(振替の重複)で二重に出ていた(提供記録入力・連絡帳は解消済み)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>日誌の出席者テーブルと送迎割り当ての両方で利用者ID単位に重複排除(データの多い方を優先)。</b>連絡帳・提供記録入力と同じ扱いに統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f3a83d4</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"スケジュール\" data-text=\"スケジュールの予定作成で対象利用者に休止中の方も選べるようにした。担当者会議等が休止中でもあるため。退所は除外。スケジュールa1674be\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">スケジュール</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">スケジュールの利用者選択に休止中の方も含める</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">予定作成の対象利用者が「利用中」のみで、休止中でも担当者会議等がある方を選べなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用中と休止中の両方を選択可にした(退所は除外)。</b>休止中は名前に「（休止中）」を付けて区別。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1674be</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"連絡帳の個別連絡事項を消しても復活して削除できない問題を修正+削除ボタン追加。個別連絡事項が項目単位保護の対象外で、同期のキー単位バックフィルにより空にしてもクラウドの旧本文で復活していた。連絡帳86389a8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">連絡帳の個別連絡事項が削除できない問題を修正(削除ボタンも追加)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個別連絡事項(contactBookRenraku)が項目単位保護の対象外で、同期マージのキー単位バックフィルにより、本文を空にしてもクラウドの旧本文で補完(復活)され削除できなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個別連絡事項を項目単位保護(_fieldTs)に追加し、明示的な削除(空)が確実に残るようにした。</b>あわせて連絡事項の各セクション(個別・全体)に「削除」ボタンを追加し、本文と表示期間を空にできるようにした。全体は元々削除可能だが操作を統一。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">86389a8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームのお知らせ類を上位N件+もっと見るに整理して高さを揃えた。運営からのお知らせは上位3件、家族ケアマネからの更新とお知らせは上位5件、残りはもっと見るで開閉。ホーム17ce8e3\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">ホームのお知らせ類を上位N件+もっと見るに整理(高さを揃える)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">ホームのお知らせ/更新カードが件数によって高さがバラバラだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>つむぎ運営からのお知らせは上位3件、家族・ケアマネからの更新とお知らせは上位5件を表示し、残りは「もっと見る」で開閉。</b>既定を上位のみにすることで本日のスケジュール等と並ぶカードの高さが揃う。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">17ce8e3</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"基本利用曜日を変更すると月間スケジュールがその曜日空欄になる問題を修正。適用開始日を未来にすると当月が空欄になり、変更履歴も累積して曜日を空欄へ巻き戻していた。今日からボタン追加+同曜日のapplyFrom以降の古い履歴を除去。利用者マスタ2efbed7\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">基本利用曜日の変更で月間スケジュールが空欄になる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">適用開始日(applyFrom)を未来日にすると、その日より前(当月)は「まだ利用曜日でない」扱いで空欄になり、さらに変更のたびに変更履歴が累積して古い履歴がその曜日を空欄へ巻き戻していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>適用開始日に『今日から(すぐ反映)』ボタンを追加し、再設定時は同じ曜日のapplyFrom以降の古い履歴を除去。</b>既に空欄になった利用者は、基本利用曜日を無→対象に設定し直せば直る(記録は削除されておらず表示で隠れていただけ)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2efbed7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"日付入力にクリア(✕)ボタンを追加=利用終了日を確実に空にできる。一部だけ消して外すと元に戻り終了日が消せず、退所扱いのまま提供記録入力に出ない/月間スケジュールが空欄になっていた問題の逃げ道。記録は削除されておらず表示フィルタで隠れていただけ。利用者マスタ74dd12a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">日付入力にクリア(✕)を追加=利用終了日が確実に消せる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">独自日付入力で一部だけ消してフォーカスを外すと元の値に戻る挙動があり、年を残したまま消そうとすると利用終了日がクリアできず、退所扱いのまま提供記録入力に出ない/月間スケジュールが空欄になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>値があるとき✕(クリア)ボタンを表示し、押すと年月日を確実に空にする。</b>利用終了日をクリアすれば退所扱いが解け再表示される。記録データは削除されておらず表示で隠れていただけなので再入力は不要。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74dd12a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"利用終了日をクリアしても提供記録入力に利用者が戻ってこない問題を修正2a89490\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">終了日クリア後も提供記録入力に利用者が出ない問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">提供記録入力の一覧シードのdepsが利用者数(length)で、終了日など内容の変更では再シードされず、終了日をクリアしても一覧に戻らなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始/終了日・状態・基本利用曜日のシグネチャをdepsに追加し、終了日クリアで即一覧へ戻るようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2a89490</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"月間スケジュールで利用終了日より後を空欄(非利用日)にして終了箇所を明確化2a89490\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">月間スケジュールで利用終了日以降を空欄にして一目で分かるように</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">利用終了しても月間スケジュールに出席等が表示され、どこで終了したか分かりにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用終了日より後(・開始日より前)の日を空欄(非利用日)にし操作不可に。利用中に戻せば出席等が再表示される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2a89490</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"年月日の日付入力を独自入力に置換(年4桁・日フル入力・年→月→日自動送り)00a310d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">日付入力を独自入力にして年4桁制限・日のフル入力・自動送りに対応</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">OS標準の日付入力は年が6桁入る/日を1桁で確定して2桁目が打てない等、ブラウザ依存で入力しづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>独自のSmartDateInputを新設し、利用開始日/終了日・休止の開始/終了日を置換。年は4桁まで、月/日の途中1桁は確定せず2桁目やフォーカス移動を待ち、年→月→日へ自動送り。カレンダーピッカーも利用可。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00a310d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"利用終了日をクリアしても勝手に元に戻る(退所済みに戻る)問題を修正fed6fa9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">利用終了日のクリアが元に戻る(退所に戻る)問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用開始日/終了日がフィールド単位保護の対象外で、クリアしても『空欄のみ補完』により古い端末の値が復活し、退所済みにも戻っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日/終了日を項目単位時刻(_fieldTs)保護の対象に追加。明示的なクリアが刻印され新しい方(空)が優先されるため、クリアが確実に残る。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fed6fa9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"休止の理由/期間が出席後も特記に残る・取り消し後も特記が残る問題を修正fed6fa9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">休止/取り消しの特記が残り続ける問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">休止の理由/期間を特記に焼き込んでいたため休止終了後も残り、また振替/欠席の取り消し後も特記が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>休止の理由/期間は表示のみ(保存しない・pauseHistoryが保持)にし、休止終了で特記から消える。過去に焼き付いたラベルも表示時に除去。取り消し時は特記(○へ振替/欠席理由)を完全クリア。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fed6fa9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"提供記録入力の保存で次回予定(次回利用日/お迎え時間)が消える問題を修正f1b51ac\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">提供記録入力を保存すると次回予定(日付・時間)が消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">提供記録入力の保存時レコード再構築に次回予定(nextDateOverride/nextTimeOverride)が含まれず、他項目を保存するたびに次回予定が欠落していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録入力では次回予定を編集しないため既存値を必ず引き継ぐようにし、他項目を保存しても次に変更するまで残るようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f1b51ac</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替の人が連絡帳/提供記録入力で二重表示・終了血圧が片方に寄る問題を修正8bee647\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">振替の二重表示・終了血圧/脈が片方で消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替/欠席の記録IDがランダムだったため、同一利用者・同一日に複数行ができ、findが拾った片方に無い終了血圧/脈が消えて見え、連絡帳では二人表示になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>振替/欠席の記録IDを決定的ID(tr_患者_年_月_日)に統一して重複を防止。提供記録入力は同一日の複数記録を非空で統合表示、連絡帳は1件に絞って二重表示を解消。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8bee647</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替/欠席の取り消し・出席戻しでバイタル等が消える問題を修正2093934\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">振替/欠席の取り消し・出席戻しで記録が消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">取り消し系(振替取り消し/状態クリア/出席戻し)が記録を無条件に削除(墓石登録)していたため、入力済みのバイタル・気分・運動・整体ごと消えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>データのある記録は削除せず出席として保持(振替の目印tokkiは消す)、データの無い空枠だけ削除するように統一。誤って振替/欠席にしても取り消せば元どおり、特記の「○へ振替」も消える。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2093934</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"欠席/休業/振替で既存の記録を消さないよう修正+過去日を欠席等にする時の警告(運動/整体/特記や過去日の血圧/脈が消える)提供記録入力の状態変更で欠席・休業・振替元の記録を既存を無視して全項目空で作り直していた。既存があればバイタル・気分・運動・整体・特記を保持し状態だけ変更するよう統一。さらに提供記録入力と月間スケジュールの両方で過去日を欠席/休業/振替/休止に変更する時に確認警告を表示。提供記録27b765b\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">欠席/休業/振替で記録が消える問題を追加修正+過去日の状態変更に警告</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回の振替修正後も、提供記録入力の状態変更で欠席・休業・振替元の記録を既存を無視して全項目空で作り直していたため、運動・整体・特記や、過去日を欠席にした日の血圧・脈などが消えていた(休止だけは既存を保持して正しく動作)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>欠席・休業・振替元も、既存の記録があればバイタル・気分・運動・整体・特記・項目別時刻を保持し状態だけ変更するよう統一。</b>間違えて欠席にしても消えず、出席に戻せば元どおりになる。さらに提供記録入力・月間スケジュールの両方で、過去日を欠席/休業/振替/休止に変更する時に確認警告を表示。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">27b765b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"振替設定で振替先の入力済みバイタル等が消える問題を修正(状態が振替の人の血圧・気分・脈・運動が消える)振替の設定処理で、振替先の日に既に記録があっても全項目を空で作り直し新しい保存時刻を付けて上書きしていたため、その日に来所して入力済みだったバイタル・気分・運動・整体が振替設定のたびに消えていた。振替先に既存記録がある場合は既存の入力を保持し状態のみ振替に変更するよう修正。提供記録25a2956\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">振替の方の血圧・気分・脈・運動などが消える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替の設定処理で、振替先の日に既に記録があっても全項目を空で作り直し、新しい保存時刻を付けて上書きしていた。その日に来所して入力済みだったバイタル・気分・運動・整体が、振替設定のたびに消えていた(同期でも新しい方が勝つため他端末にも波及)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>振替先に既存の記録がある場合は、体温・血圧・脈・気分・運動・整体・特記・項目別時刻(_fieldTs)を保持したまま、状態だけを振替に変更するよう修正。</b>新規の振替先のみ従来どおり空で作成。データを消さない方向のみの変更で同期の安全性は不変。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">25a2956</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"お知らせ\" data-text=\"更新内容を確認できる仕組みを追加(更新バナー+ホームにライブ反映)「新しいバージョンがあります」と出ても何が変わったか分からず、更新してよいか迷うという声があった。静的ファイル(update-notes.json)を旧バージョンでもライブ取得し、更新バナーに「更新内容を確認」ボタン(モーダル表示)を設置。ホームのつむぎ運営からのお知らせにも再読み込みなしで反映。同期やデータ書き込みは行わない読み取り専用。お知らせ7b57cde\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">お知らせ</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">更新内容を確認できる仕組みを追加(更新バナー+ホームにライブ反映)</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">「新しいバージョンがあります」と表示されても何が変わったか分からず、更新してよいか迷うという声があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>更新バナーに「更新内容を確認」ボタンを設置し、押すと今回の更新内容をモーダルで表示。</b>静的ファイル(update-notes.json)を旧バージョンでもライブ取得(60秒ごと)するため、ホームの「つむぎ運営からのお知らせ」にも再読み込みなしで反映される。同期・データ書き込みは行わない読み取り専用。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7b57cde</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"デザイン\" data-text=\"アプリロゴを新デザイン(握手マーク)に刷新従来の四つ葉クローバーから、支え合い・つながり・未来を紡ぐ想いを込めた握手マークの正式ロゴへ刷新。ログイン画面・サイドバー上部・favicon・3種マニュアル(事業所/関係者/家族)の表紙ロゴを新デザインに統一し、サイドバーのマークを拡大。ロゴの意味の解説はマニュアルからは外し今後のLPへ掲載予定。ロゴは正式PNGをそのまま画像として使用(描き直しなし)。デザイン994be51\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">デザイン</span><span class=\"date tnum\">2026-08-06</span></div>\n      <p class=\"title\">アプリロゴを新デザイン(握手マーク)に刷新</p>\n      <div class=\"cf\"><span class=\"lb\">背景</span><span class=\"tx\">従来の四つ葉クローバーから、支え合い・つながり・未来を紡ぐ想いを込めた握手マークの正式ロゴへ刷新することにした。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ログイン画面・サイドバー上部・favicon・3種マニュアルの表紙ロゴを新デザインに統一。</b>ロゴの意味の解説はマニュアルには載せず今後のLPへ掲載予定。サイドバーのマークを拡大し、ロゴは正式PNGをそのまま画像として使用(SVG等で描き直さない)。</span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">487041d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"連絡帳\" data-text=\"入力済みの次回お迎え時間が時間経過で全て消える次回時間の欄に触れて閉じただけでも毎回保存が走り、空値や自動計算値が新しい時刻付きで記録され、同期(新しい方が勝つ)が他端末で入力済みの時間を次々と上書きしていた。「実際に値が変わった時だけ」書き込むガードを追加。現在値と同じ・実質未設定欄への空や自動計算値と同内容の書き込みは行わない。値のある欄の意図的クリアは従来どおり反映。連絡帳8b52d13\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">入力済みの次回お迎え時間が時間経過で全て消える</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">次回時間の欄に触れて閉じただけでも毎回保存が走り、空値や自動計算値が新しい時刻付きで記録され、同期(新しい方が勝つ)が他端末で入力済みの時間を次々と上書きしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「実際に値が変わった時だけ」書き込むガードを追加。現在値と同じ・実質未設定欄への空や自動計算値と同内容の書き込みは行わない。値のある欄の意図的クリアは従来どおり反映。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b52d13</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"バイタル範囲外入力の警告バナー(体温7・血圧1257等の桁違い検知)体温「7」血圧「1257」のような桁違い入力がそのまま記録され、後から気付けなかった。体温30〜43/血圧上50〜250/血圧下30〜150/脈拍30〜200の範囲外を入力すると画面上部に赤い警告を8秒表示。入力自体は止めず記録の自由は保つ。tab移動時とテンキーを閉じる時に判定。提供記録58babdf\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">バイタル範囲外入力の警告バナー(体温7・血圧1257等の桁違い検知)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">体温「7」血圧「1257」のような桁違い入力がそのまま記録され、後から気付けなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>体温30〜43/血圧上50〜250/血圧下30〜150/脈拍30〜200の範囲外を入力すると画面上部に赤い警告を8秒表示。入力自体は止めず記録の自由は保つ。Tab移動時とテンキーを閉じる時に判定。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">58babdf</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"提供記録だけを編集中に「同期停止」の誤警告が出る問題を解消テーブル方式では提供記録の保存が巨大jsonのpush-okを発生させず、同期停止検知(stall)が誤作動していた。テーブル書き込み(rows-upsert)成功を同期成功として記録するように変更。同期58babdf\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">提供記録だけを編集中に「同期停止」の誤警告が出る問題を解消</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テーブル方式では提供記録の保存が巨大JSONのpush-okを発生させず、同期停止検知(stall)が誤作動していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>テーブル書き込み(rows-upsert)成功を同期成功として記録するように変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">58babdf</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡\" data-text=\"各種連絡: 保存ボタン・本文の書式(文字サイズ/下線)・入力内容からの定型文作成保存ボタンが無く休み連絡と操作感が不統一。fax向けに文字を大きく/下線を引きたい。作成済みの本文を定型文として使い回したい(店舗要望)。右上に保存ボタン(押すと✓保存しました表示)。本文と定型文に文字サイズ(標準/大/特大)と下線の書式を追加(faxのため色は無し)。「今の入力内容から定型文を作成」で件名→タイトル・本文→内容の編集画面を開けるように。連絡11fdfb4\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">各種連絡: 保存ボタン・本文の書式(文字サイズ/下線)・入力内容からの定型文作成</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存ボタンが無く休み連絡と操作感が不統一。FAX向けに文字を大きく/下線を引きたい。作成済みの本文を定型文として使い回したい(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>右上に保存ボタン(押すと✓保存しました表示)。本文と定型文に文字サイズ(標準/大/特大)と下線の書式を追加(FAXのため色は無し)。「今の入力内容から定型文を作成」で件名→タイトル・本文→内容の編集画面を開けるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">11fdfb4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"端末名設定: 保存済みの名前を常時表示・ブラウザ自動入力の混入を抑止保存した端末名がどこにも確定表示されず、ブラウザが保存済みログインid等を端末名欄へ自動入力してしまう事象があった(店舗報告)。「現在の端末名: ◯◯(保存済み/未設定)」を常時表示。入力欄に自動入力抑止属性を付与。各種設定8b54f1c\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">端末名設定: 保存済みの名前を常時表示・ブラウザ自動入力の混入を抑止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存した端末名がどこにも確定表示されず、ブラウザが保存済みログインID等を端末名欄へ自動入力してしまう事象があった(店舗報告)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「現在の端末名: ◯◯(保存済み/未設定)」を常時表示。入力欄に自動入力抑止属性を付与。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8b54f1c</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"休業日は選択・閲覧可能に/定休日に開いたら次の営業日を初期表示休業日は日付選択で強制的に別日へずらされ、記録確認や事後入力ができなかった。定休日(土日)に開くと定休日自身が表示されていた(店舗要望)。日付選択は定休日だけ営業日へずらし、休業日は選択・閲覧可能に。起動時に今日が定休日なら前方の次の営業日を初期表示(休業日もスキップ)。提供記録698e48e\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">休業日は選択・閲覧可能に/定休日に開いたら次の営業日を初期表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">休業日は日付選択で強制的に別日へずらされ、記録確認や事後入力ができなかった。定休日(土日)に開くと定休日自身が表示されていた(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>日付選択は定休日だけ営業日へずらし、休業日は選択・閲覧可能に。起動時に今日が定休日なら前方の次の営業日を初期表示(休業日もスキップ)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">698e48e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"休止の入力ロックが休止期間外の日まで効いていたマスタの現在ステータス(休止)だけで判定しており、休止期間前の日や終了日以降まで提供記録の入力欄がロックされていた(店舗報告)。期間判定(getpausereasonondate)に差し替え、休止期間内の日だけ入力不可に。期間情報の無い休止のみ従来どおり常時ロック。提供記録b2762fe\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">休止の入力ロックが休止期間外の日まで効いていた</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">マスタの現在ステータス(休止)だけで判定しており、休止期間前の日や終了日以降まで提供記録の入力欄がロックされていた(店舗報告)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間判定(getPauseReasonOnDate)に差し替え、休止期間内の日だけ入力不可に。期間情報の無い休止のみ従来どおり常時ロック。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2762fe</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"更新バナーを「必ず再読み込みしてください」と強い表示に更新バナーが弱く再読み込みされないまま古いビルドで使い続けられ、同期不具合の原因になっていた(店舗要望)。「⚠ 新しいバージョンがあります。必ず再読み込みしてください」に文言・配色を強化。各種設定ec26967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">更新バナーを「必ず再読み込みしてください」と強い表示に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">更新バナーが弱く再読み込みされないまま古いビルドで使い続けられ、同期不具合の原因になっていた(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「⚠ 新しいバージョンがあります。必ず再読み込みしてください」に文言・配色を強化。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec26967</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"右上「詳細設定」を「印刷設定」に名称変更内容が印刷(面数/用紙/補助線)の設定であり名称が実態と合っていなかった(店舗要望)。ボタンとパネルの名称を「印刷設定」に統一。連絡帳ec26967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">右上「詳細設定」を「印刷設定」に名称変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">内容が印刷(面数/用紙/補助線)の設定であり名称が実態と合っていなかった(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ボタンとパネルの名称を「印刷設定」に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec26967</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回予定の「変更済」判定をマスタ自動計算値との差分に変更値の有無だけで判定していたため、欄に触れただけの人まで「変更済」表示になっていた。サービス提供内容(マスタ)由来の自動計算値から実際に変わっている時だけ表示。意図的な「未定」は変更として扱う。連絡帳ec26967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">次回予定の「変更済」判定をマスタ自動計算値との差分に変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">値の有無だけで判定していたため、欄に触れただけの人まで「変更済」表示になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供内容(マスタ)由来の自動計算値から実際に変わっている時だけ表示。意図的な「未定」は変更として扱う。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec26967</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"次回お迎え時間が「分から入力すると消える」・空白の見えない値で変更済み扱いになる空入力時に「　時　分」(空白文字入り)を記録へ書き込み、①触っただけで変更済 ②モーダルで数字が取り出せず空白表示 ③同期で実際の入力時間を打ち負かす毒データになっていた。時刻分解も時が無いと分を読めなかった。空は空のまま返す(毒データを書かない)。数字の無い残骸は自動計算値で表示し編集可能に。分単独の入力も保持する時刻分解に修正。連絡帳9aab5c6\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">次回お迎え時間が「分から入力すると消える」・空白の見えない値で変更済み扱いになる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">空入力時に「　時　分」(空白文字入り)を記録へ書き込み、①触っただけで変更済 ②モーダルで数字が取り出せず空白表示 ③同期で実際の入力時間を打ち負かす毒データになっていた。時刻分解も時が無いと分を読めなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>空は空のまま返す(毒データを書かない)。数字の無い残骸は自動計算値で表示し編集可能に。分単独の入力も保持する時刻分解に修正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9aab5c6</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"「元に戻す」が完全に無反応(復元機能が全く効かない)recordviewにdevicenameが渡されないまま復元処理が参照しており、「戻す」を押すと未定義エラーで処理が即死していた。さらに確認ダイアログが2連続でブラウザに抑止される問題も重なっていた。devicenameをpropsに追加。確認はブラウザ依存のconfirmをやめアプリ内ダイアログ(1回だけ)に変更。復元履歴に「戻した後の内容」サマリ(体温/血圧/気分/運動/整体の件数)も追加。提供記録5f89404\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-03</span></div>\n      <p class=\"title\">「元に戻す」が完全に無反応(復元機能が全く効かない)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">RecordViewにdeviceNameが渡されないまま復元処理が参照しており、「戻す」を押すと未定義エラーで処理が即死していた。さらに確認ダイアログが2連続でブラウザに抑止される問題も重なっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>deviceNameをpropsに追加。確認はブラウザ依存のconfirmをやめアプリ内ダイアログ(1回だけ)に変更。復元履歴に「戻した後の内容」サマリ(体温/血圧/気分/運動/整体の件数)も追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f89404</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録を「1記録=1行」のテーブル方式へ移行(カットオーバー)巨大json方式は全記録を1行に保存するため、多端末の同時入力で衝突・上書き消失が構造的に発生していた(7/30の保存全滅事故もこの構造が原因)。ticket_recordsテーブルへ移行。プレビュー3日間の検証で、受信マージの項目時刻対応(明示クリアが伝わる/事故は守る)・運動○のキー単位同期(1タップで他端末の○が全滅するバグ修正)・空欄増幅ガード・起動時取込の一本化・書込失敗の自動再送キュー・容量超過時の軽量保存・復元のフル書込など9件を修正した上で、営業前に全店再シードして切替。稼働初日を無事完走。同期62f5fe0\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-08-04</span></div>\n      <p class=\"title\">提供記録を「1記録=1行」のテーブル方式へ移行(カットオーバー)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">巨大JSON方式は全記録を1行に保存するため、多端末の同時入力で衝突・上書き消失が構造的に発生していた(7/30の保存全滅事故もこの構造が原因)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ticket_recordsテーブルへ移行。プレビュー3日間の検証で、受信マージの項目時刻対応(明示クリアが伝わる/事故は守る)・運動○のキー単位同期(1タップで他端末の○が全滅するバグ修正)・空欄増幅ガード・起動時取込の一本化・書込失敗の自動再送キュー・容量超過時の軽量保存・復元のフル書込など9件を修正した上で、営業前に全店再シードして切替。稼働初日を無事完走。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">62f5fe0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"日誌\" data-text=\"日誌の過去日の編集ロックを廃止過去分の記入漏れを追記しにくかった(店舗要望)。過去日付も常時編集可能に変更。日誌00e83ac\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-08-01</span></div>\n      <p class=\"title\">日誌の過去日の編集ロックを廃止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">過去分の記入漏れを追記しにくかった(店舗要望)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>過去日付も常時編集可能に変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e83ac</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"復元履歴に「(状態)他17名」など触っていない人まで表示される直前スナップショットに存在しない人は既定の「状態=出席」だけでも変更扱いになり、初回保存で全員が差分表示されていた。初出の人は実際に触った項目や既定以外の状態だけを表示。最古の履歴は差分を出さず「この日の最初の保存」とだけ表示。提供記録00e83ac\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-08-01</span></div>\n      <p class=\"title\">復元履歴に「(状態)他17名」など触っていない人まで表示される</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直前スナップショットに存在しない人は既定の「状態=出席」だけでも変更扱いになり、初回保存で全員が差分表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>初出の人は実際に触った項目や既定以外の状態だけを表示。最古の履歴は差分を出さず「この日の最初の保存」とだけ表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">00e83ac</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"2台同時編集で保存が全滅する(変更が保存されず変更ログが凍結)1台の端末が全記録の保存(cas書き込み)を同時に複数本並行実行し、自分同士で衝突→リトライ上限超過(conflict-retries-exhausted)で保存が失敗し続けていた。店舗単位でcas書き込みを直列化(同時に1本だけ)。各書き込みは実行時に最新versionを取り直すため内容は正しいまま。同期5787ed3\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-30</span></div>\n      <p class=\"title\">2台同時編集で保存が全滅する(変更が保存されず変更ログが凍結)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">1台の端末が全記録の保存(CAS書き込み)を同時に複数本並行実行し、自分同士で衝突→リトライ上限超過(conflict-retries-exhausted)で保存が失敗し続けていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>店舗単位でCAS書き込みを直列化(同時に1本だけ)。各書き込みは実行時に最新versionを取り直すため内容は正しいまま。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5787ed3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"新規登録の基本利用日を半日型に合わせam/pmのみに新規登録に付けた基本利用日の切替に「1日(全日)」が含まれていたが、この事業所は基本的に半日型デイのためam/pmだけでよいとの指摘。新規登録モーダルの基本利用日切替を 空→am→pm の2区分に変更(1日を廃止)。既存データの「1日」は各判定ロジックで従来どおり認識するので影響なし。利用者マスタec76d6d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">新規登録の基本利用日を半日型に合わせAM/PMのみに</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">新規登録に付けた基本利用日の切替に「1日(全日)」が含まれていたが、この事業所は基本的に半日型デイのためAM/PMだけでよいとの指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>新規登録モーダルの基本利用日切替を 空→AM→PM の2区分に変更(1日を廃止)。既存データの「1日」は各判定ロジックで従来どおり認識するので影響なし。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec76d6d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"新規登録に利用開始日・基本利用日＋登録後の遷移先選択を追加新規登録で氏名だけ入れて詳細画面へ行く流れだったが、名前・振り仮名・利用開始日・基本利用日を最初の画面で入れてサービス提供内容に反映したい/開始日が不明なこともある、との要望。必須を氏名(姓名)のみにし、フリガナ・利用開始日・基本利用日は任意に。基本利用日は曜日ごとにタップ入力→サービス提供内容へ反映。登録後の遷移先を『フェイスシート(手書き)』『サービス提供内容(マスタ編集)』『追加のみ』から選べるようにした。利用者マスタ021e67e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">新規登録に利用開始日・基本利用日＋登録後の遷移先選択を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">新規登録で氏名だけ入れて詳細画面へ行く流れだったが、名前・振り仮名・利用開始日・基本利用日を最初の画面で入れてサービス提供内容に反映したい/開始日が不明なこともある、との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>必須を氏名(姓名)のみにし、フリガナ・利用開始日・基本利用日は任意に。基本利用日は曜日ごとにタップ入力→サービス提供内容へ反映。登録後の遷移先を『フェイスシート(手書き)』『サービス提供内容(マスタ編集)』『追加のみ』から選べるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">021e67e</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"新規登録に『完了して詳細情報入力』『追加のみ』の2ボタンを追加登録後に詳細入力へ進むかどうかを選べると便利、との以前の要望。『完了して詳細情報入力』(追加してそのまま編集画面へ)と『追加のみ(あとで入力)』の2択に。※後続コミット021e67eでさらに拡張。利用者マスタ706ad5e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">新規登録に『完了して詳細情報入力』『追加のみ』の2ボタンを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">登録後に詳細入力へ進むかどうかを選べると便利、との以前の要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>『完了して詳細情報入力』(追加してそのまま編集画面へ)と『追加のみ(あとで入力)』の2択に。※後続コミット021e67eでさらに拡張。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">706ad5e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"日誌\" data-text=\"送迎者チェックの氏名(5文字以上)が見切れる問題を修正日誌の送迎者チェックが4列固定グリッド＋氏名がnowrap+ellipsisのため、5文字以上の氏名が末尾で切れていた。氏名の文字数に応じてフォントを自動縮小(5=9.5/6=8.5/7以上=7.5px)し、4列固定はそのままで見切れを解消。日誌f37677e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">日誌</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">送迎者チェックの氏名(5文字以上)が見切れる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日誌の送迎者チェックが4列固定グリッド＋氏名がnowrap+ellipsisのため、5文字以上の氏名が末尾で切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>氏名の文字数に応じてフォントを自動縮小(5=9.5/6=8.5/7以上=7.5px)し、4列固定はそのままで見切れを解消。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f37677e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"変更ログ\" data-text=\"変更ログの絵文字を削除し文字のみに業務画面では装飾的な絵文字は不要との方針。変更ログのボタン・見出しから絵文字(📋)を除去。今後も必要な箇所以外は絵文字を使わない方針に。変更ログ2fcdb08\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">変更ログ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">変更ログの絵文字を削除し文字のみに</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">業務画面では装飾的な絵文字は不要との方針。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>変更ログのボタン・見出しから絵文字(📋)を除去。今後も必要な箇所以外は絵文字を使わない方針に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2fcdb08</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"変更ログ\" data-text=\"カテゴリ別の変更ログ(端末名・内容・時刻)を記録＋閲覧ビューアを追加「いつ・どの端末で・何を変更したか」を後から追える仕組みが欲しい(同期トラブルの切り分けにも有用)との要望。保存時に変わったカテゴリ(提供記録/連絡/体力測定/利用者マスタ/各種設定 等)を端末名・軽い要約・時刻で最新300件記録(auditlog)。ヘッダーの『変更ログ』ボタンからカテゴリ絞り込み付きで閲覧。読み取り専用でマージには非干渉、店舗ごとに保存(他店は見えない)。空白上書きの検知(マージ計器)は高リスクのため見送り。変更ログd9cbb3d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">変更ログ</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">カテゴリ別の変更ログ(端末名・内容・時刻)を記録＋閲覧ビューアを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「いつ・どの端末で・何を変更したか」を後から追える仕組みが欲しい(同期トラブルの切り分けにも有用)との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存時に変わったカテゴリ(提供記録/連絡/体力測定/利用者マスタ/各種設定 等)を端末名・軽い要約・時刻で最新300件記録(auditLog)。ヘッダーの『変更ログ』ボタンからカテゴリ絞り込み付きで閲覧。読み取り専用でマージには非干渉、店舗ごとに保存(他店は見えない)。空白上書きの検知(マージ計器)は高リスクのため見送り。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d9cbb3d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替/臨時の次回お迎え時間は常に自動計算(過去の手入力を無視)先週8時と手入力した後に同じ記録をpmへ振替し直しても8時のまま残る恐れがあった。getnextvisitinfoがisfurikaeを返すようにし、次回が振替/臨時なら手入力を使わず区分(am/pm)に合った自動値を表示。通常の次回は従来どおり手入力優先。連絡帳84c1ad5\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">振替/臨時の次回お迎え時間は常に自動計算(過去の手入力を無視)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">先週8時と手入力した後に同じ記録をPMへ振替し直しても8時のまま残る恐れがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>getNextVisitInfoがisFurikaeを返すようにし、次回が振替/臨時なら手入力を使わず区分(AM/PM)に合った自動値を表示。通常の次回は従来どおり手入力優先。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">84c1ad5</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替の次回お迎え時間を『時だけ』表示＋未入力既定を8時/13時に自動値は時だけでよい/施設提供時間が未入力なら既定値が欲しい、との指摘。施設提供時間からの自動値を時だけ(8:50→8時 / 13:15→13時)にし、提供時間も未入力ならam=8時/pm=13時を既定に。連絡帳9028a45\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">振替の次回お迎え時間を『時だけ』表示＋未入力既定を8時/13時に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">自動値は時だけでよい/施設提供時間が未入力なら既定値が欲しい、との指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>施設提供時間からの自動値を時だけ(8:50→8時 / 13:15→13時)にし、提供時間も未入力ならAM=8時/PM=13時を既定に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9028a45</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"振替/送迎時間未設定日の次回お迎え時間を施設のサービス提供時間から自動計算週1日だけ等の利用者は他曜日の送迎時間を設定しないため、振替で別曜日に移ると次回時間が空欄/不定になっていた。登録済みのpickuptimesを最優先、未設定の曜日はam=am開始の10分前/pm=pm開始の10分前で自動計算(am↔pmで自動切替)。表示計算のみでマスタは書き換えない。連絡帳bbef167\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-29</span></div>\n      <p class=\"title\">振替/送迎時間未設定日の次回お迎え時間を施設のサービス提供時間から自動計算</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">週1日だけ等の利用者は他曜日の送迎時間を設定しないため、振替で別曜日に移ると次回時間が空欄/不定になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>登録済みのpickupTimesを最優先、未設定の曜日はAM=AM開始の10分前/PM=PM開始の10分前で自動計算(AM↔PMで自動切替)。表示計算のみでマスタは書き換えない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bbef167</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基本利用日が保存直後に一瞬で戻る競合を修正＋モーダルを『指定せず保存』化基本利用日(曜日)を保存した直後に、push反映前の古いクラウド値でlocalpatientが再シードされ、入力が一瞬消える(再入力で反映)競合があった。保存直後6秒は再シードしないガードを追加。あわせて運動メニューの反映日モーダルの『キャンセル』を『指定せず保存』に(値は保存・反映日のみ未指定)。利用者マスタ3b872f2\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-28</span></div>\n      <p class=\"title\">基本利用日が保存直後に一瞬で戻る競合を修正＋モーダルを『指定せず保存』化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">基本利用日(曜日)を保存した直後に、push反映前の古いクラウド値でlocalPatientが再シードされ、入力が一瞬消える(再入力で反映)競合があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存直後6秒は再シードしないガードを追加。あわせて運動メニューの反映日モーダルの『キャンセル』を『指定せず保存』に(値は保存・反映日のみ未指定)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3b872f2</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"運動メニュー変更の反映日確認を『保存時に1回まとめて』＋『分けない』廃止運動メニューを項目ごとに変えるたび、自動保存で反映日モーダルが時差で出て煩わしかった。『分けない』は基本使わない。自動保存では値だけ静かに保存し、反映日モーダルは『保存』時に全変更まとめて1回だけ出す(編集開始前の基準値と比較)。モーダルの『分けない』を『指定せず保存』に置換。利用者マスタ0022120\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-28</span></div>\n      <p class=\"title\">運動メニュー変更の反映日確認を『保存時に1回まとめて』＋『分けない』廃止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">運動メニューを項目ごとに変えるたび、自動保存で反映日モーダルが時差で出て煩わしかった。『分けない』は基本使わない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>自動保存では値だけ静かに保存し、反映日モーダルは『保存』時に全変更まとめて1回だけ出す(編集開始前の基準値と比較)。モーダルの『分けない』を『指定せず保存』に置換。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0022120</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳の穴あけマークを◀に変更＋自動同期停止時の控えめ未同期バナー穴あけ目印の見た目調整と、スリープ/通信断で最新が反映されていないのに気づけない懸念への対応。2面の穴あけ目印を●→◀に。app_stateの自動pullが30秒以上走っていない時だけヘッダーに『未同期・タップで再読み込み』を控えめ表示(読み取り専用でマージ非干渉)。連絡帳534c53d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳の穴あけマークを◀に変更＋自動同期停止時の控えめ未同期バナー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">穴あけ目印の見た目調整と、スリープ/通信断で最新が反映されていないのに気づけない懸念への対応。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>2面の穴あけ目印を●→◀に。app_stateの自動pullが30秒以上走っていない時だけヘッダーに『未同期・タップで再読み込み』を控えめ表示(読み取り専用でマージ非干渉)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">534c53d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"1\" data-area=\"同期\" data-text=\"バイタルの明示クリアを許可しつつ事故的な空欄上書きは防止バイタルを空で消せない多重防御を入れた結果、意図的なクリアもできなくなっていた。一方で事故的な空欄上書きは防ぎたい。バイタルの空↔非空マージを『空側の_fieldtsが非空側より厳密に新しい=はっきり消した時だけ』クリア反映に。空欄への_fieldtsは値→空の明示クリア時のみ付くため、意図的削除と事故的空を安全に区別できる。同期688b5ae\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">バイタルの明示クリアを許可しつつ事故的な空欄上書きは防止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">バイタルを空で消せない多重防御を入れた結果、意図的なクリアもできなくなっていた。一方で事故的な空欄上書きは防ぎたい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>バイタルの空↔非空マージを『空側の_fieldTsが非空側より厳密に新しい=はっきり消した時だけ』クリア反映に。空欄への_fieldTsは値→空の明示クリア時のみ付くため、意図的削除と事故的空を安全に区別できる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">688b5ae</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"1\" data-area=\"同期\" data-text=\"バイタルは空が新しくても非空を絶対優先(多重防御)空バイタル誤削除の再発を構造的に防ぎたい。万一どこかで空欄に新しい削除フラグが付いても入力済みを消させない。mergerecordfieldsの_fieldts短絡でも、体温/血圧/脈(*_am/*_pm)は片方だけ空なら非空を採用する多重防御を追加(後に688b5aeで明示クリアのみ許可に調整)。同期cdc4f28\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">バイタルは空が新しくても非空を絶対優先(多重防御)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">空バイタル誤削除の再発を構造的に防ぎたい。万一どこかで空欄に新しい削除フラグが付いても入力済みを消させない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>mergeRecordFieldsの_fieldTs短絡でも、体温/血圧/脈(*_AM/*_PM)は片方だけ空なら非空を採用する多重防御を追加(後に688b5aeで明示クリアのみ許可に調整)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cdc4f28</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"『元に戻す』が_fieldtsを更新せず削除フラグに負けて戻らない不具合を修正提供記録の元に戻す(スナップショット復元)が_savedatだけ更新し_fieldtsを据え置きだったため、クラウド側の空欄削除フラグ(新しい_fieldts)がフィールド単位マージで勝ち、復元しても血圧/体温が空のままだった。復元時に対象記録の全項目へ_fieldts=nowを刻むよう修正。消える前のスナップショットを選べば値が戻るようにした。同期9a0b345\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">『元に戻す』が_fieldTsを更新せず削除フラグに負けて戻らない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">提供記録の元に戻す(スナップショット復元)が_savedAtだけ更新し_fieldTsを据え置きだったため、クラウド側の空欄削除フラグ(新しい_fieldTs)がフィールド単位マージで勝ち、復元しても血圧/体温が空のままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>復元時に対象記録の全項目へ_fieldTs=nowを刻むよう修正。消える前のスナップショットを選べば値が戻るようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9a0b345</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録の空バイタルに削除フラグが付き他端末の血圧/体温を消す不具合を修正保存時のフィールド差分判定で、フォームがバイタルを空文字で正規化(undefined→&#x27;&#x27;)しただけの項目にも_fieldtsを刻んでいた。マージ側がこれを『意図的な削除』と誤判定し、他端末で入力済みの血圧/体温(am/pm)を空で上書き消去していた(運動はキー単位マージで生存)。特定店舗で血圧・体温だけが午前午後とも消える症状。差分判定で空↔未入力(undefined↔&#x27;&#x27;)を『変更なし』とみなすよう修正(値→&#x27;&#x27;の明示削除は従来どおり反映)。あわせて多重防御(cdc4f28/688b5ae)・元に戻す修正(9a0b345)も実施。同期0c02dee\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">提供記録の空バイタルに削除フラグが付き他端末の血圧/体温を消す不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">保存時のフィールド差分判定で、フォームがバイタルを空文字で正規化(undefined→&#x27;&#x27;)しただけの項目にも_fieldTsを刻んでいた。マージ側がこれを『意図的な削除』と誤判定し、他端末で入力済みの血圧/体温(AM/PM)を空で上書き消去していた(運動はキー単位マージで生存)。特定店舗で血圧・体温だけが午前午後とも消える症状。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分判定で空↔未入力(undefined↔&#x27;&#x27;)を『変更なし』とみなすよう修正(値→&#x27;&#x27;の明示削除は従来どおり反映)。あわせて多重防御(cdc4f28/688b5ae)・元に戻す修正(9a0b345)も実施。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0c02dee</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡\" data-text=\"休み連絡/各種連絡の送付履歴を個人ファイル一覧から直接削除できるボタンを追加重複や誤登録の送付履歴を、個人ファイルの連絡タブから直接消したいとの要望。個人ファイル(連絡タブ)の休み連絡・各種連絡・モニタリング履歴の各行に確認ダイアログ付き削除(✕)を追加。連絡696ddef\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">休み連絡/各種連絡の送付履歴を個人ファイル一覧から直接削除できるボタンを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">重複や誤登録の送付履歴を、個人ファイルの連絡タブから直接消したいとの要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個人ファイル(連絡タブ)の休み連絡・各種連絡・モニタリング履歴の各行に確認ダイアログ付き削除(✕)を追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">696ddef</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面のドットを左端へ＋休み連絡・各種連絡の重複自動追加を防止プレビューを開くたびに休み連絡/各種連絡の送付履歴が自動追加され重複していた。穴あけドットも内側寄りだった。休み連絡は同一利用者×同一欠席日は1件のみ、各種連絡は同一宛先×件名×本文が同じなら追加しないよう重複防止。2面の穴あけドットを左端(5mm)へ。連絡帳414ad24\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面のドットを左端へ＋休み連絡・各種連絡の重複自動追加を防止</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">プレビューを開くたびに休み連絡/各種連絡の送付履歴が自動追加され重複していた。穴あけドットも内側寄りだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>休み連絡は同一利用者×同一欠席日は1件のみ、各種連絡は同一宛先×件名×本文が同じなら追加しないよう重複防止。2面の穴あけドットを左端(5mm)へ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">414ad24</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面が真っ白になる不具合を修正(縮小実寸ラッパー枠方式)2面を絶対配置+transformにしたところ、印刷プレビューのクリップ処理で中身ごと消えて真っ白になった(ドットと点線だけ残る)。カード(182×257固定)を縮小後の実寸(約116.5×164.5mm)のラッパー枠に入れて確実に描画する方式へ変更。両面共通配置(重ねてピッタリ)・ドット一致は維持。連絡帳c9e583c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面が真っ白になる不具合を修正(縮小実寸ラッパー枠方式)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面を絶対配置+transformにしたところ、印刷プレビューのクリップ処理で中身ごと消えて真っ白になった(ドットと点線だけ残る)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>カード(182×257固定)を縮小後の実寸(約116.5×164.5mm)のラッパー枠に入れて確実に描画する方式へ変更。両面共通配置(重ねてピッタリ)・ドット一致は維持。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c9e583c</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面を両面同一の絶対配置に(重ねてピッタリ)＋左綴じ代ドット＋右詰め2面の左右余白が対称にならず、重ねたときに揃わない/右面の外側余白が広すぎるとの指摘。カード内蔵の左19mm綴じ代を活かし、両面共通のmarginで絶対配置に統一(中央でカット→2枚のb6を重ねると中身も穴も一致)。穴あけドットを左綴じ代の縦中央に、右端余白を詰めた。連絡帳c999f08\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面を両面同一の絶対配置に(重ねてピッタリ)＋左綴じ代ドット＋右詰め</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面の左右余白が対称にならず、重ねたときに揃わない/右面の外側余白が広すぎるとの指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>カード内蔵の左19mm綴じ代を活かし、両面共通のmarginで絶対配置に統一(中央でカット→2枚のB6を重ねると中身も穴も一致)。穴あけドットを左綴じ代の縦中央に、右端余白を詰めた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c999f08</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面をミラー配置に(中央のりしろを広く/外側を狭く)＋倍率0.64中身が中央線寄りで、切り取り線まわりののりしろが狭かった。左面は中身を左寄せ・右面は右寄せにし、空いた余白を中央に集約(のりしろを広く・外側を狭く)。倍率0.64で余白確保(後にc999f08で両面同一配置へ再調整)。連絡帳5e4b8cf\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面をミラー配置に(中央のりしろを広く/外側を狭く)＋倍率0.64</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">中身が中央線寄りで、切り取り線まわりののりしろが狭かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>左面は中身を左寄せ・右面は右寄せにし、空いた余白を中央に集約(のりしろを広く・外側を狭く)。倍率0.64で余白確保(後にc999f08で両面同一配置へ再調整)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5e4b8cf</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面印刷のサイズ崩れを修正(flex+0.70に戻す)＋既定b5-2面＋印刷ヘッダー抑制2面を絶対配置に変えた際に中身が拡大してはみ出した。既定の面数・用紙も整えたい。サイズが正しく出るflex中央+0.70倍方式に戻し、面数の既定をb5横2面に。印刷プレビューに@page{margin:0}を効かせブラウザのヘッダー/フッターを抑制。連絡帳7a42921\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面印刷のサイズ崩れを修正(flex+0.70に戻す)＋既定B5-2面＋印刷ヘッダー抑制</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面を絶対配置に変えた際に中身が拡大してはみ出した。既定の面数・用紙も整えたい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サイズが正しく出るflex中央+0.70倍方式に戻し、面数の既定をB5横2面に。印刷プレビューに@page{margin:0}を効かせブラウザのヘッダー/フッターを抑制。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7a42921</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳2面の左右偏りを絶対配置で解消＋右上日付は空面のみ空欄に2面印刷で左右の面の余白が対称にならず(両方が中央のカット線寄り)残っていた。flexの「はみ出し中央寄せ」が効かないため。また右上日付を常に空欄にしていたが、利用者がいる面は実際の日付が欲しいとの指摘。2面の各面を絶対配置(left:0/半分)にし、中身をtranslate(-50%,-50%)+scaleでface中央に固定して両面まったく同じ配置に。右上日付は2面印刷で余った空面(手書き用・id=__blank__)だけ「令和8年　月　日（　）」の空欄にし、利用者がいる面は従来どおり実際の日付(令和8年m月d日（曜）)を表示。連絡帳5fef4d9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳2面の左右偏りを絶対配置で解消＋右上日付は空面のみ空欄に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面印刷で左右の面の余白が対称にならず(両方が中央のカット線寄り)残っていた。flexの「はみ出し中央寄せ」が効かないため。また右上日付を常に空欄にしていたが、利用者がいる面は実際の日付が欲しいとの指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>2面の各面を絶対配置(left:0/半分)にし、中身をtranslate(-50%,-50%)+scaleでface中央に固定して両面まったく同じ配置に。右上日付は2面印刷で余った空面(手書き用・id=__blank__)だけ「令和8年　月　日（　）」の空欄にし、利用者がいる面は従来どおり実際の日付(令和8年M月D日（曜）)を表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5fef4d9</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳b5横2面の左右余白を両面で完全一致に2面印刷で、左面は中身が右寄り(左余白広い)・右面は左寄り(右余白広い)＝両方が中央のカット線寄りになり、左右の面で余白がバラついていた。原因は182mm幅の中身を128.5mmの枠にはみ出したまま中央寄せしていたため。各面の中身を「縮小後の実寸ピッタリの箱(transform-origin:top left)」にしてから中央寄せする方式に変更。これで左右の余白が両面で完全に一致する。連絡帳2c852dd\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳B5横2面の左右余白を両面で完全一致に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">2面印刷で、左面は中身が右寄り(左余白広い)・右面は左寄り(右余白広い)＝両方が中央のカット線寄りになり、左右の面で余白がバラついていた。原因は182mm幅の中身を128.5mmの枠にはみ出したまま中央寄せしていたため。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各面の中身を「縮小後の実寸ピッタリの箱(transform-origin:top left)」にしてから中央寄せする方式に変更。これで左右の余白が両面で完全に一致する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2c852dd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳右上の日付を「令和8年　月　日（　）」表記に修正(年は表示・月日曜は手書き用の空欄)前回、右上の日付から令和・年数字ごと削除してしまったが、正しくは「令和8年」は残し、月・日・曜日を空欄(手書き)にしたいという指摘。右上の日付を「令和(和暦年)年　月　日（　）」形式に変更。令和と年(例:令和8年)は表示し、月・日・曜日は全角スペースの空欄にして手書きで記入できるようにした。連絡帳4d2c587\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳右上の日付を「令和8年　月　日（　）」表記に修正(年は表示・月日曜は手書き用の空欄)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">前回、右上の日付から令和・年数字ごと削除してしまったが、正しくは「令和8年」は残し、月・日・曜日を空欄(手書き)にしたいという指摘。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>右上の日付を「令和(和暦年)年　月　日（　）」形式に変更。令和と年(例:令和8年)は表示し、月・日・曜日は全角スペースの空欄にして手書きで記入できるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4d2c587</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳b5横2面印刷の位置ズレ・見切れ・穴あけ点・日付表記を調整実機で2面印刷したところ、内容が左に寄る/連絡欄や次回欄が見切れる/1枚目と2枚目で位置が違う、穴あけ点が右面にしか出ず上下2点だった、次回未設定が「未定」、右上が「令和8年…」表記、等の指摘があった。各面を1面(b6)と同じ「flexで中央＋0.70倍」配置に統一し、左寄り・見切れ・1/2枚目の差を解消。b5を左右いっぱいに使い中央のカット点線が真ん中に来るように。穴あけ点は各面の左・縦ど真ん中に1つずつ(左右両面)に変更。次回お迎え日付が未設定なら「未定」でなく「　月　日（　）」の手書き用空欄に。連絡帳右上の日付は令和・年数字を外し「m月d日（曜）」表記に。連絡帳5381ad5\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳B5横2面印刷の位置ズレ・見切れ・穴あけ点・日付表記を調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">実機で2面印刷したところ、内容が左に寄る/連絡欄や次回欄が見切れる/1枚目と2枚目で位置が違う、穴あけ点が右面にしか出ず上下2点だった、次回未設定が「未定」、右上が「令和8年…」表記、等の指摘があった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各面を1面(B6)と同じ「flexで中央＋0.70倍」配置に統一し、左寄り・見切れ・1/2枚目の差を解消。B5を左右いっぱいに使い中央のカット点線が真ん中に来るように。穴あけ点は各面の左・縦ど真ん中に1つずつ(左右両面)に変更。次回お迎え日付が未設定なら「未定」でなく「　月　日（　）」の手書き用空欄に。連絡帳右上の日付は令和・年数字を外し「M月D日（曜）」表記に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5381ad5</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳をb5横に2面印刷(後で中央カット)できるように＋補助線＋右上を「詳細設定」化b6非対応/b6トレイのセットでエラーになる複合機があり、b5に1枚(b6位置)印刷が使えない事業所があった。普通にb5印刷して後でカットしたい要望。連絡帳画面右上の「用紙」を「詳細設定」に変更し、面数(1面/2面)・用紙(横b5/縦b6)・補助線をパネルで選択可能に。2面モードはb5横(257×182)に連絡帳を左右2面配置し、中央でカットするとb6×2枚になる。人数が奇数のときは最後の1面を空欄(氏名・次回日付/時間・運動の連動・自由入力が空＝手書き用)にして偶数化。補助線=中央の縦点線(カット線)＋各面の左側に上下2つの点(穴あけ目印)で、それぞれ印刷時にon/off選択可。印刷対象は従来の利用者選択で決めるため午前/午後/1日まとめもそのまま対応。1面モードは従来通り。連絡帳231e78b\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">連絡帳をB5横に2面印刷(後で中央カット)できるように＋補助線＋右上を「詳細設定」化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">B6非対応/B6トレイのセットでエラーになる複合機があり、B5に1枚(B6位置)印刷が使えない事業所があった。普通にB5印刷して後でカットしたい要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>連絡帳画面右上の「用紙」を「詳細設定」に変更し、面数(1面/2面)・用紙(横B5/縦B6)・補助線をパネルで選択可能に。2面モードはB5横(257×182)に連絡帳を左右2面配置し、中央でカットするとB6×2枚になる。人数が奇数のときは最後の1面を空欄(氏名・次回日付/時間・運動の連動・自由入力が空＝手書き用)にして偶数化。補助線=中央の縦点線(カット線)＋各面の左側に上下2つの点(穴あけ目印)で、それぞれ印刷時にON/OFF選択可。印刷対象は従来の利用者選択で決めるため午前/午後/1日まとめもそのまま対応。1面モードは従来通り。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">231e78b</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"運動メニュー/個別運動メニューの削除が、保存しても消えない不具合を修正各種設定の運動メニューはマウント時のスナップショットで保持し、保存時の安全ガード(ローカルが空ならクラウド側に戻す)により、削除して短く/空になった配列が古いクラウド値へ戻ることがあった(特に個別運動を全部消した時等)。加えて削除時の履歴の重複判定が effectivefrom(常にundefined)で、毎回不要なスナップショットを追加していた。マウント時の内容と比較して「ユーザーが実際に編集した配列」は、削除を含めローカルを必ず保存する(空でもクラウドへ戻さない)。未編集の配列は現行データを優先し、同期で増えた分の巻き戻りは防ぐ。運動メニュー・個別運動メニュー・その時系列履歴・クイックボタンに適用し、通常の保存ボタンと「未保存です」ポップアップ保存の両方で有効。削除時の履歴スナップショット重複判定を effectiveto 基準に統一。各種設定81ab60a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-27</span></div>\n      <p class=\"title\">運動メニュー/個別運動メニューの削除が、保存しても消えない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">各種設定の運動メニューはマウント時のスナップショットで保持し、保存時の安全ガード(ローカルが空ならクラウド側に戻す)により、削除して短く/空になった配列が古いクラウド値へ戻ることがあった(特に個別運動を全部消した時等)。加えて削除時の履歴の重複判定が effectiveFrom(常にundefined)で、毎回不要なスナップショットを追加していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マウント時の内容と比較して「ユーザーが実際に編集した配列」は、削除を含めローカルを必ず保存する(空でもクラウドへ戻さない)。未編集の配列は現行データを優先し、同期で増えた分の巻き戻りは防ぐ。運動メニュー・個別運動メニュー・その時系列履歴・クイックボタンに適用し、通常の保存ボタンと「未保存です」ポップアップ保存の両方で有効。削除時の履歴スナップショット重複判定を effectiveTo 基準に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">81ab60a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"保険証・負担割合証・フェイスシート等が他店の更新で反映されない/巻き戻る不具合を修正介護保険証/負担割合証のメタ・フェイスシート・担当者会議・アセスメント等が入るpersonalfile(入れ子)と、負担割合の有効期間(costburdenfrom/to)・被保険者番号が、同期の項目単位保護(_fieldts)の対象外だった。そのため別の項目を触った“少し古いデータの端末”が保存すると、他店で更新した保険証・フェイスシートが「新しいスナップショット」の名目でまるごと巻き戻っていた(保険証以外も同じ弱点)。同期の項目単位保護を拡張。①保護対象に costburdenfrom/costburdento/被保険者番号 を追加。②personalfile をサブキー単位の時刻(pf:キー)でマージ(各書類・フェイスシート・会議記録ごとに新しい方を採用。アセスメントは従来の和集合を維持)。③介護度・負担割合の変更履歴を和集合で保持し、両端末の追記=過去記録を失わないように。既存クラウドは項目時刻を持たないため当面は従来挙動にフォールバックし、以降の保存で段階的に保護が付く(後方互換)。同期7c18dfb\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">保険証・負担割合証・フェイスシート等が他店の更新で反映されない/巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護保険証/負担割合証のメタ・フェイスシート・担当者会議・アセスメント等が入るpersonalFile(入れ子)と、負担割合の有効期間(costBurdenFrom/To)・被保険者番号が、同期の項目単位保護(_fieldTs)の対象外だった。そのため別の項目を触った“少し古いデータの端末”が保存すると、他店で更新した保険証・フェイスシートが「新しいスナップショット」の名目でまるごと巻き戻っていた(保険証以外も同じ弱点)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期の項目単位保護を拡張。①保護対象に costBurdenFrom/costBurdenTo/被保険者番号 を追加。②personalFile をサブキー単位の時刻(pf:キー)でマージ(各書類・フェイスシート・会議記録ごとに新しい方を採用。アセスメントは従来の和集合を維持)。③介護度・負担割合の変更履歴を和集合で保持し、両端末の追記=過去記録を失わないように。既存クラウドは項目時刻を持たないため当面は従来挙動にフォールバックし、以降の保存で段階的に保護が付く(後方互換)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c18dfb</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"テンキー日本語ラベルを大きく表示＋言い回しを変更（bs→1字消す／tab→次へ）日本語化したテンキーのラベルが小さく見づらかった。bs・tabは別の言い回しの方が直感的との要望。bs=1字消す(2行)／tab=次へ に変更。日本語ラベルのフォントを拡大（全削除=0.66倍、1字消す/次へ/確定=0.82倍）。キー値は英語のままで動作は不変。提供記録f4da324\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">テンキー日本語ラベルを大きく表示＋言い回しを変更（BS→1字消す／TAB→次へ）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日本語化したテンキーのラベルが小さく見づらかった。BS・TABは別の言い回しの方が直感的との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>BS=1字消す(2行)／TAB=次へ に変更。日本語ラベルのフォントを拡大（全削除=0.66倍、1字消す/次へ/確定=0.82倍）。キー値は英語のままで動作は不変。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f4da324</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"テンキーの特殊キーを日本語表示に（del→全削除／bs→1文字削除／tab→右へ／enter→確定）テンキーのdel/bs/tab/enterが英語表記で、意味が分からない職員がいた。表示ラベルを日本語化（del=全削除／bs=1文字削除〔2行〕／tab=右へ／enter=確定）。キー値は英語のままロジックで使用するため動作は不変。日本語ラベルはボタン内に収まるようフォントサイズを調整。提供記録cf98527\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">テンキーの特殊キーを日本語表示に（DEL→全削除／BS→1文字削除／TAB→右へ／ENTER→確定）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テンキーのDEL/BS/TAB/ENTERが英語表記で、意味が分からない職員がいた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>表示ラベルを日本語化（DEL=全削除／BS=1文字削除〔2行〕／TAB=右へ／ENTER=確定）。キー値は英語のままロジックで使用するため動作は不変。日本語ラベルはボタン内に収まるようフォントサイズを調整。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cf98527</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析/提供記録\" data-text=\"気分列幅を状態列と同じに＋日々の詳細記録の気分理由ツールチップをipad対応にサービス提供記録の気分列が状態列より広かった。日々の詳細記録の気分絵文字はnative title頼りで、ipad等タッチ端末ではカーソルを合わせても理由が表示されなかった。サービス提供記録の気分列ヘッダ幅を60→34(状態列と同じ)にしセルのminwidthも撤去。日々の詳細記録の気分絵文字に、ホバー(onpointerenter)とタップ(onclick)の両方で理由を表示する浮動ツールチップを実装(タップ時は2.6秒で自動クローズ、理由なしは「（理由なし）」)。分析/提供記録c18172e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析/提供記録</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">気分列幅を状態列と同じに＋日々の詳細記録の気分理由ツールチップをiPad対応に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サービス提供記録の気分列が状態列より広かった。日々の詳細記録の気分絵文字はnative title頼りで、iPad等タッチ端末ではカーソルを合わせても理由が表示されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供記録の気分列ヘッダ幅を60→34(状態列と同じ)にしセルのminWidthも撤去。日々の詳細記録の気分絵文字に、ホバー(onPointerEnter)とタップ(onClick)の両方で理由を表示する浮動ツールチップを実装(タップ時は2.6秒で自動クローズ、理由なしは「（理由なし）」)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c18172e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析/提供記録\" data-text=\"気分表示を絵文字のみに整理＋日々の詳細記録の見やすさ改善サービス提供記録の気分に💬コメント絵文字が付いて列幅を取っていた。分析個人『日々の詳細記録』は気分の理由テキストが括弧書きで表示され横に広がっていた。特記列が狭く、行のストライプが薄くて見分けにくかった。サービス提供記録(検索一覧)の気分から💬を削除し気分列幅を縮小(minwidth 52→36)、理由はホバー(title)で従来通り。日々の詳細記録の気分(通)/(帰)は絵文字のみ表示にし理由テキストを廃止、絵文字ホバーで気分理由を表示。特記列の幅を拡大(minwidth 220→340)。奇数行のストライプ背景グレーを濃く(#fafbfc→#eef2f6)。分析/提供記録d7a9976\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析/提供記録</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">気分表示を絵文字のみに整理＋日々の詳細記録の見やすさ改善</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サービス提供記録の気分に💬コメント絵文字が付いて列幅を取っていた。分析個人『日々の詳細記録』は気分の理由テキストが括弧書きで表示され横に広がっていた。特記列が狭く、行のストライプが薄くて見分けにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供記録(検索一覧)の気分から💬を削除し気分列幅を縮小(minWidth 52→36)、理由はホバー(title)で従来通り。日々の詳細記録の気分(通)/(帰)は絵文字のみ表示にし理由テキストを廃止、絵文字ホバーで気分理由を表示。特記列の幅を拡大(minWidth 220→340)。奇数行のストライプ背景グレーを濃く(#fafbfc→#eef2f6)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d7a9976</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"連絡\" data-text=\"休み連絡・各種連絡の送付先fax番号を表示(マスタ補完)＋ワンクリックコピー送付状の送付先faxが利用者のcmfaxのみ参照で、利用者にfax未設定だと表示されなかった(各種設定のケアマネ事業所情報にはfaxがある)。各種設定のケアマネ事業所情報(cmoffices)から事業所名一致でfax番号を補完して表示。fax番号の右にコピーボタン(copyfaxbutton)を新設し、複合機にそのまま貼り付けられるようクリップボードへコピー(navigator.clipboard、非対応時はexeccommandでフォールバック)。コピーボタンはno-printクラスで印刷/pdf時は非表示。連絡684adcb\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">休み連絡・各種連絡の送付先FAX番号を表示(マスタ補完)＋ワンクリックコピー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">送付状の送付先FAXが利用者のcmFaxのみ参照で、利用者にFAX未設定だと表示されなかった(各種設定のケアマネ事業所情報にはFAXがある)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定のケアマネ事業所情報(cmOffices)から事業所名一致でFAX番号を補完して表示。FAX番号の右にコピーボタン(CopyFaxButton)を新設し、複合機にそのまま貼り付けられるようクリップボードへコピー(navigator.clipboard、非対応時はexecCommandでフォールバック)。コピーボタンはno-printクラスで印刷/PDF時は非表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">684adcb</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"科学的介護推進・adl維持等の帳票(印刷/pdf)を追加lifeの科学的介護推進(tifi2024)・adl維持等(aint2024)は評価内容を紙様式で出す帳票が無く、csvのみだった。lifehubviewに印刷機能(onshowprintpreview)を渡し、両様式カードに「帳票印刷」ボタンを追加。科学的介護推進に関する評価=事業所/利用者/評価日/介護度/自立度・barthel一覧・身長体重・口腔(義歯/むせ/歯の汚れ/歯肉)・認知症診断・生活認知機能尺度7設問(点数+選択肢)・vitalityをa4紙様式で出力。adl維持等=ヘッダ+対象月区分+barthel一覧。元データ=選択中利用者の最新adl評価+固有項目。生活機能チェック(3-2)/個別機能訓練(3-3)の帳票は各計画書画面の印刷/pdfから。life加算a7119db\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">科学的介護推進・ADL維持等の帳票(印刷/PDF)を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEの科学的介護推進(TIFI2024)・ADL維持等(AINT2024)は評価内容を紙様式で出す帳票が無く、CSVのみだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LifeHubViewに印刷機能(onShowPrintPreview)を渡し、両様式カードに「帳票印刷」ボタンを追加。科学的介護推進に関する評価=事業所/利用者/評価日/介護度/自立度・Barthel一覧・身長体重・口腔(義歯/むせ/歯の汚れ/歯肉)・認知症診断・生活認知機能尺度7設問(点数+選択肢)・VitalityをA4紙様式で出力。ADL維持等=ヘッダ+対象月区分+Barthel一覧。元データ=選択中利用者の最新ADL評価+固有項目。生活機能チェック(3-2)/個別機能訓練(3-3)の帳票は各計画書画面の印刷/PDFから。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a7119db</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"個別機能訓練 idua2024(103列)のlife提出csvを実装(v1)＋計画書にコード入力uilifeの4様式のうち個別機能訓練(idua2024・最大の103列)が未対応だった。目標や訓練内容はコード(icf/プログラム/職種/合併症/傷病名)での提出が必要。life_idua2024_columns(103)/buildidua2024row/validateidua2024を実装しlife_formsにsource=kinouで登録(addon=個別機能訓練加算ii)。元データ=個別機能訓練計画書(3-3)。マスタ同梱=icf目標55(§9.2)/訓練プログラム18(§9.3)/合併症23分類/職種名(准看護師=050のみ確定・他要確認)。本人家族希望・社会参加・居宅環境・治療経過・目標文→内容列、発症/入退院日→年月日分割、訓練内容→プログラムコード自動推定、達成度文→コード、自立度/介護度/管理番号/versionを自動生成。3-3計画書に「life提出用コード」入力(傷病名/合併症/目標icf/プログラム/職種/達成度=editing.life)を新設。提出ダッシュボード・単票出力もkinou元データに対応。傷病名27388件は任意入力扱い。life加算34f64f8 / a69388f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">個別機能訓練 IDUA2024(103列)のLIFE提出CSVを実装(v1)＋計画書にコード入力UI</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEの4様式のうち個別機能訓練(IDUA2024・最大の103列)が未対応だった。目標や訓練内容はコード(ICF/プログラム/職種/合併症/傷病名)での提出が必要。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE_IDUA2024_COLUMNS(103)/buildIdua2024Row/validateIdua2024を実装しLIFE_FORMSにsource=kinouで登録(addon=個別機能訓練加算II)。元データ=個別機能訓練計画書(3-3)。マスタ同梱=ICF目標55(§9.2)/訓練プログラム18(§9.3)/合併症23分類/職種名(准看護師=050のみ確定・他要確認)。本人家族希望・社会参加・居宅環境・治療経過・目標文→内容列、発症/入退院日→年月日分割、訓練内容→プログラムコード自動推定、達成度文→コード、自立度/介護度/管理番号/versionを自動生成。3-3計画書に「LIFE提出用コード」入力(傷病名/合併症/目標ICF/プログラム/職種/達成度=editing.life)を新設。提出ダッシュボード・単票出力もkinou元データに対応。傷病名27388件は任意入力扱い。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">34f64f8 / a69388f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"月別稼働率グラフで7月時点に8月の稼働率が出てしまう不具合を修正月別グラフは年度12ヶ月を常に表示。当月は今日までにcapする処理はあったが、未来月を除外する処理が無く、稼働率の照合が「記録に年がある時だけ年フィルタ」だったため、年情報のない同月番号の記録(前年8月分等)を未来月が拾い、売上¥0なのに稼働率91%等と表示されていた。_isfuturemonth(当月より後)を判定し、未来月は稼働率rate=null(グラフ・表で非表示)に。年なし記録の混入を防ぎ、稼働率の線は当月までで止まる。売上の年付き照合は元々正しいため¥0表示は不変。分析9011a1f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">月別稼働率グラフで7月時点に8月の稼働率が出てしまう不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月別グラフは年度12ヶ月を常に表示。当月は今日までにcapする処理はあったが、未来月を除外する処理が無く、稼働率の照合が「記録に年がある時だけ年フィルタ」だったため、年情報のない同月番号の記録(前年8月分等)を未来月が拾い、売上¥0なのに稼働率91%等と表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>_isFutureMonth(当月より後)を判定し、未来月は稼働率rate=null(グラフ・表で非表示)に。年なし記録の混入を防ぎ、稼働率の線は当月までで止まる。売上の年付き照合は元々正しいため¥0表示は不変。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9011a1f</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"生活機能チェック(func2024・52列)のlife提出csvを追加＋様式横断にsource導入lifeはtifi2024/aint2024のみで生活機能チェック(様式3-2)のfunc2024が未対応。ダッシュボード/出力もbarthel(adlrecords)固定で別データ元の様式を扱えなかった。life_func2024_columns(52列)/buildfunc2024row/validatefunc2024を新設しlife_formsにfunc2024を登録(addon=個別機能訓練加算ⅱ)。元データ=生活機能チェック(seikatsukinourecords)。adl10項目はseikatsuadltobarthel→lifebicode(§6.4 bi段階コード)、iadl3/起居動作5は自立=3/見守り=2/一部介助=1/全介助=0。課題の有無は自動判定(自立=無/他=有)。作成日の和暦→yyyymmdd変換(reiwatoymd)追加。life_formsにsource(adl/seikatsu)を追加し提出ダッシュボード・単票を元データで分岐(tifi/aintは従来通り)。func2024はマスタ不要。life加算692f5a2\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">生活機能チェック(FUNC2024・52列)のLIFE提出CSVを追加＋様式横断にsource導入</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEはTIFI2024/AINT2024のみで生活機能チェック(様式3-2)のFUNC2024が未対応。ダッシュボード/出力もBarthel(adlRecords)固定で別データ元の様式を扱えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE_FUNC2024_COLUMNS(52列)/buildFunc2024Row/validateFunc2024を新設しLIFE_FORMSにFUNC2024を登録(addon=個別機能訓練加算Ⅱ)。元データ=生活機能チェック(seikatsuKinouRecords)。ADL10項目はseikatsuAdlToBarthel→lifeBiCode(§6.4 BI段階コード)、IADL3/起居動作5は自立=3/見守り=2/一部介助=1/全介助=0。課題の有無は自動判定(自立=無/他=有)。作成日の和暦→YYYYMMDD変換(reiwaToYmd)追加。LIFE_FORMSにsource(adl/seikatsu)を追加し提出ダッシュボード・単票を元データで分岐(TIFI/AINTは従来通り)。FUNC2024はマスタ不要。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">692f5a2</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"adl維持等加算(aint2024)のcsv出力を追加・ダッシュボード/出力を様式横断化lifeは科学的介護推進(tifi2024)のみ対応で、adl維持等加算のcsvが無かった。aint2024全23列(既存barthel評価を流用・first_month/sixth_monthフラグ対応)を実装。adl評価編集に対象月区分(初月/6か月後/どちらでもない)を追加し利用開始日から目安月を表示。提出ダッシュボード・単票/まとめcsv出力を様式横断(life_forms)に一般化し、加算が複数onなら様式プルダウンでtifi2024/aint2024を切替。life加算4c8ef63\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">ADL維持等加算(AINT2024)のCSV出力を追加・ダッシュボード/出力を様式横断化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEは科学的介護推進(TIFI2024)のみ対応で、ADL維持等加算のCSVが無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>AINT2024全23列(既存Barthel評価を流用・first_month/sixth_monthフラグ対応)を実装。ADL評価編集に対象月区分(初月/6か月後/どちらでもない)を追加し利用開始日から目安月を表示。提出ダッシュボード・単票/まとめCSV出力を様式横断(LIFE_FORMS)に一般化し、加算が複数ONなら様式プルダウンでTIFI2024/AINT2024を切替。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c8ef63</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"科学的介護推進: 提出ダッシュボード＋複数利用者まとめcsv出力csv出力が利用者1名ずつだった。提出月に複数利用者をまとめて出力できず、誰が提出可/未評価/エラーかの一覧も無かった。life・加算画面に提出ダッシュボード(利用者×状態=提出可/エラー/未評価・確認事項)を追加。行クリックでその利用者に切替。『まとめてcsv出力』で提出可の全利用者を1つのtifi2024_yyyymm.csvに出力(未評価・エラーは自動除外し確認一覧に表示)。各行の管理番号は利用者ごとの評価年月で採番。提出年月セレクタでファイル名整理。life加算74b1da2\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">科学的介護推進: 提出ダッシュボード＋複数利用者まとめCSV出力</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">CSV出力が利用者1名ずつだった。提出月に複数利用者をまとめて出力できず、誰が提出可/未評価/エラーかの一覧も無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に提出ダッシュボード(利用者×状態=提出可/エラー/未評価・確認事項)を追加。行クリックでその利用者に切替。『まとめてCSV出力』で提出可の全利用者を1つのTIFI2024_YYYYMM.csvに出力(未評価・エラーは自動除外し確認一覧に表示)。各行の管理番号は利用者ごとの評価年月で採番。提出年月セレクタでファイル名整理。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74b1da2</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"分析個人/LIFE加算\" data-text=\"気分表示を絵文字＋ホバーにコンパクト化／life事業所情報は各種設定に一元化①分析個人『日々の詳細記録』で気分の理由テキストが長いと行が縦に伸びて見づらかった。②lifeの事業所番号・保険者番号がlife画面専用カードにあり、事業所情報と二重管理気味だった。①気分列を絵文字だけの一定行高さ表示に変更し、理由はホバー(title)で表示(理由ありは💬)。②事業所番号・保険者番号(既定)・サービス種類コード・csvバージョンを『各種設定→事業所情報』に入力項目として設置し、life・加算のcsvはそこから読込(専用カードは表示のみに)。分析個人/life加算55305ca\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析個人/LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">気分表示を絵文字＋ホバーにコンパクト化／LIFE事業所情報は各種設定に一元化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①分析個人『日々の詳細記録』で気分の理由テキストが長いと行が縦に伸びて見づらかった。②LIFEの事業所番号・保険者番号がLIFE画面専用カードにあり、事業所情報と二重管理気味だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①気分列を絵文字だけの一定行高さ表示に変更し、理由はホバー(title)で表示(理由ありは💬)。②事業所番号・保険者番号(既定)・サービス種類コード・CSVバージョンを『各種設定→事業所情報』に入力項目として設置し、LIFE・加算のCSVはそこから読込(専用カードは表示のみに)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">55305ca</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"life設定(事業所/保険者番号/サービスコード/version)＋利用者ごと保険者番号＋生活認知機能尺度の正式文言科学的介護推進csvで事業所番号・保険者番号が空欄(&#x27;要確認&#x27;警告)だった。また生活・認知機能尺度の7設問が仮ラベルのままだった。life・加算画面に『life設定』(事業所番号・保険者番号既定・サービス種類コード・施設通所区分・csvバージョン=systemsettings.life)を追加。利用者基本情報に被保険者番号表示＋利用者ごとの保険者番号入力を追加(csvは利用者→無ければ事業所既定)。生活・認知機能尺度7設問を別紙様式3の正式文言に差し替え、各点数の選択肢説明も表示。life加算424891d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">LIFE設定(事業所/保険者番号/サービスコード/version)＋利用者ごと保険者番号＋生活認知機能尺度の正式文言</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">科学的介護推進CSVで事業所番号・保険者番号が空欄(&#x27;要確認&#x27;警告)だった。また生活・認知機能尺度の7設問が仮ラベルのままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に『LIFE設定』(事業所番号・保険者番号既定・サービス種類コード・施設通所区分・CSVバージョン=systemSettings.life)を追加。利用者基本情報に被保険者番号表示＋利用者ごとの保険者番号入力を追加(CSVは利用者→無ければ事業所既定)。生活・認知機能尺度7設問を別紙様式3の正式文言に差し替え、各点数の選択肢説明も表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">424891d</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"スケジュール/提供記録\" data-text=\"担当者会議のスケジュール→記録入力ショートカット／提供記録の全画面に連絡帳ボタン①本日のスケジュールで担当者会議(利用者紐付き)を設定していても、記録入力までの導線が無かった。②サービス提供記録入力を全画面にすると連絡帳ボタンが消えていた。①本日のスケジュールの担当者会議イベントの詳細に『担当者会議記録を入力』ボタンを追加し、押すとその利用者の個人ファイル(ケアマネジメント)で会議記録の新規入力を即開くように。②全画面ヘッダにも『連絡帳』ボタンを追加。スケジュール/提供記録9c435e7\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">スケジュール/提供記録</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">担当者会議のスケジュール→記録入力ショートカット／提供記録の全画面に連絡帳ボタン</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①本日のスケジュールで担当者会議(利用者紐付き)を設定していても、記録入力までの導線が無かった。②サービス提供記録入力を全画面にすると連絡帳ボタンが消えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①本日のスケジュールの担当者会議イベントの詳細に『担当者会議記録を入力』ボタンを追加し、押すとその利用者の個人ファイル(ケアマネジメント)で会議記録の新規入力を即開くように。②全画面ヘッダにも『連絡帳』ボタンを追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9c435e7</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"科学的介護推進体制加算(tifi2024)のlife提出用csv出力を実装(第1弾)life(科学的介護情報システム)へ提出する加算データを一元入力→取込用csvを生成する仕組みが未実装だった(まるっとlifeはexcel運用)。まず科学的介護推進体制加算から着手。life・加算画面に、科学的介護推進の固有入力(身長体重/口腔/認知症診断/生活認知機能尺度7設問/vitality)を追加し、既存のadl評価(barthel)・フェイスシートの自立度を流用して全114列のcsv(tifi2024)を出力。§6.4コード変換(bi段階・自立度・要介護度)、管理番号採番、utf-8/cr-lf、提出前チェック(必須/未来日付/整合)を実装。提出頻度は令和6年度改定に合わせ3ヶ月に修正。次段: 事業所/保険者番号のlife設定・複数まとめ出力・帳票印刷・adl維持等/個別機能訓練の様式。life加算17f432e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">科学的介護推進体制加算(TIFI2024)のLIFE提出用CSV出力を実装(第1弾)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFE(科学的介護情報システム)へ提出する加算データを一元入力→取込用CSVを生成する仕組みが未実装だった(まるっとLIFEはExcel運用)。まず科学的介護推進体制加算から着手。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に、科学的介護推進の固有入力(身長体重/口腔/認知症診断/生活認知機能尺度7設問/Vitality)を追加し、既存のADL評価(Barthel)・フェイスシートの自立度を流用して全114列のCSV(TIFI2024)を出力。§6.4コード変換(BI段階・自立度・要介護度)、管理番号採番、UTF-8/CR-LF、提出前チェック(必須/未来日付/整合)を実装。提出頻度は令和6年度改定に合わせ3ヶ月に修正。次段: 事業所/保険者番号のLIFE設定・複数まとめ出力・帳票印刷・ADL維持等/個別機能訓練の様式。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">17f432e</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"利用者マスタ\" data-text=\"運動メニュー規定値をハイフン(ー)/クリアにすると過去の記録まで遡って変わる不具合を修正テンキーの ○/×/ー ボタンは押下で即確定(自動クローズ)するため、数値変更のように『別セルへ移動→保存で&quot;いつから反映&quot;を確認』の流れに乗らず、自動保存で当日付のまま(場合により履歴無しで)確定され、提供記録入力で過去日を遡ると規定値が全てハイフンになっていた。運動メニュー・個別運動の規定値変更は、数値・ハイフン・クリアを問わず必ず『いつから反映しますか』モーダルを表示。自動保存でも当日付で勝手に確定せず、適用開始日を選んで日付単位で履歴管理(過去は旧値のまま保持)。全期間へ適用したい場合はモーダルの『分けない』を選択。利用者マスタ8d48609\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">運動メニュー規定値をハイフン(ー)/クリアにすると過去の記録まで遡って変わる不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テンキーの ○/×/ー ボタンは押下で即確定(自動クローズ)するため、数値変更のように『別セルへ移動→保存で&quot;いつから反映&quot;を確認』の流れに乗らず、自動保存で当日付のまま(場合により履歴無しで)確定され、提供記録入力で過去日を遡ると規定値が全てハイフンになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>運動メニュー・個別運動の規定値変更は、数値・ハイフン・クリアを問わず必ず『いつから反映しますか』モーダルを表示。自動保存でも当日付で勝手に確定せず、適用開始日を選んで日付単位で履歴管理(過去は旧値のまま保持)。全期間へ適用したい場合はモーダルの『分けない』を選択。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8d48609</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"フェイスシート編集の更新通知にも項目名(本人情報・留意点・被保険者番号等)を表示フェイスシートに追加した項目(氏名・住所・電話・被保険者番号・留意点・その他関係者)が差分表(fs_field_labels)に無く、フェイスシートで編集しても『フェイスシートの編集』に項目名が出なかった。fs_field_labels にこれらを追加し、フェイスシート経由の編集でも『フェイスシートの編集（○○）』と項目名が出るように(既往歴は登録済み)。ケアマネ連携fe04080\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">フェイスシート編集の更新通知にも項目名(本人情報・留意点・被保険者番号等)を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシートに追加した項目(氏名・住所・電話・被保険者番号・留意点・その他関係者)が差分表(FS_FIELD_LABELS)に無く、フェイスシートで編集しても『フェイスシートの編集』に項目名が出なかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>FS_FIELD_LABELS にこれらを追加し、フェイスシート経由の編集でも『フェイスシートの編集（○○）』と項目名が出るように(既往歴は登録済み)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fe04080</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"家族・ケアマネの『利用者情報の編集』通知に変更項目名を全項目分表示変更項目名を出す差分表に生年月日・性別・介護度・被保険者番号が含まれておらず、これらだけを編集した場合は項目名が出ず『利用者情報の編集』とだけ表示されていた。差分表にこの4項目を追加し、どの項目を編集しても『利用者情報の編集（○○・○○）』のように具体名が出るように。※既存の古い通知は文言が固定のため変わりません(以後の編集から反映)。ホームb7ac04d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">家族・ケアマネの『利用者情報の編集』通知に変更項目名を全項目分表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">変更項目名を出す差分表に生年月日・性別・介護度・被保険者番号が含まれておらず、これらだけを編集した場合は項目名が出ず『利用者情報の編集』とだけ表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分表にこの4項目を追加し、どの項目を編集しても『利用者情報の編集（○○・○○）』のように具体名が出るように。※既存の古い通知は文言が固定のため変わりません(以後の編集から反映)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b7ac04d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"支援経過表に負担割合変更・各種更新通知・アカウント発行を自動記録支援経過表(利用者に関わる経過の記録)に、負担割合の変更やフェイスシート・利用者情報・保険証写真・アセスメントの更新、アカウント発行が載っていなかった。支援経過表は各データから毎回再生成する導出型のため、生成元(spautoevents)に『負担割合履歴・docupdates(各種更新通知)・家族/関係者アカウント』を追加。介護度/ケアマネ/サービス変更/休止/休み連絡/各種連絡/モニタリング/体力測定/担当者会議/初回報告/基本情報変更は従来どおり自動記録。利用者マスタ41deb07\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">支援経過表に負担割合変更・各種更新通知・アカウント発行を自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">支援経過表(利用者に関わる経過の記録)に、負担割合の変更やフェイスシート・利用者情報・保険証写真・アセスメントの更新、アカウント発行が載っていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>支援経過表は各データから毎回再生成する導出型のため、生成元(spAutoEvents)に『負担割合履歴・docUpdates(各種更新通知)・家族/関係者アカウント』を追加。介護度/ケアマネ/サービス変更/休止/休み連絡/各種連絡/モニタリング/体力測定/担当者会議/初回報告/基本情報変更は従来どおり自動記録。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41deb07</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"削除したログインidが再利用できない不具合を修正招待セルフ登録の最終id重複チェックが古いローカルデータを参照し、他端末で削除済みのidが残っていると『事前は使える→登録でng』の矛盾になっていた。supabase有効時はsupabaseの判定を正とし、ローカルのみの重複拒否はsupabase無効時に限定。削除したidを再利用できるように。家族アプリcd60129\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">削除したログインIDが再利用できない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">招待セルフ登録の最終ID重複チェックが古いローカルデータを参照し、他端末で削除済みのIDが残っていると『事前は使える→登録でNG』の矛盾になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>Supabase有効時はSupabaseの判定を正とし、ローカルのみの重複拒否はSupabase無効時に限定。削除したIDを再利用できるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cd60129</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"担当ケアマネ欄に登録ケアマネ(アカウント)一覧を表示(複数対応)ケアマネのアカウントを追加しても基本情報・フェイスシートに現れず、どこにも反映されないように見えた(先の緊急連絡先非表示化とも整合させる必要)。利用者に紐づくケアマネアカウント(kind=caremanager等)を担当ケアマネ欄に一覧表示。複数のケアマネも表示され、追加登録が反映される。担当(事業所/担当者)の変更は従来どおり『担当を変更』。利用者マスタc73942d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">担当ケアマネ欄に登録ケアマネ(アカウント)一覧を表示(複数対応)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ケアマネのアカウントを追加しても基本情報・フェイスシートに現れず、どこにも反映されないように見えた(先の緊急連絡先非表示化とも整合させる必要)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者に紐づくケアマネアカウント(kind=caremanager等)を担当ケアマネ欄に一覧表示。複数のケアマネも表示され、追加登録が反映される。担当(事業所/担当者)の変更は従来どおり『担当を変更』。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c73942d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ/家族画面の保険証等で『表示中に問題が発生しました』(familystoreid未定義)を修正子コンポーネント familypatientview が familystoreid(親familyviewで定義)を受け取っておらず、保険証(cmdocsmodal)の描画やケアマネのフェイスシート保存で familystoreid を参照した瞬間に referenceerror となり、家族/ケアマネ画面全体がエラー画面に落ちていた。pc/端末やキャッシュにより発生タイミングが違って見えた。familyview から familystoreid を prop として familypatientview へ渡すよう修正。保険証・アセスメント表示やcm保存が落ちなくなる。ケアマネ連携b2fa3d9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ケアマネ/家族画面の保険証等で『表示中に問題が発生しました』(familyStoreId未定義)を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">子コンポーネント FamilyPatientView が familyStoreId(親FamilyViewで定義)を受け取っておらず、保険証(CmDocsModal)の描画やケアマネのフェイスシート保存で familyStoreId を参照した瞬間に ReferenceError となり、家族/ケアマネ画面全体がエラー画面に落ちていた。PC/端末やキャッシュにより発生タイミングが違って見えた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>FamilyView から familyStoreId を prop として FamilyPatientView へ渡すよう修正。保険証・アセスメント表示やCM保存が落ちなくなる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2fa3d9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"家族・ケアマネのログインux改善(利用規約1回化・ホーム追加案内・q&amp;a・規約リンク)利用規約が毎回表示され煩わしかった。高齢者がホーム画面追加やログイン失敗時に迷いやすい。ログイン後に規約を見返す導線も無かった。利用規約の再同意を端末×ポリシー版で記録し同じ版なら二度と出さない(1回)。ログイン画面に『ホーム画面に追加する方法』(ios/android手順)と『ログインできない時(q&amp;a)』を追加。ログイン後フッターに『利用規約・プライバシーポリシー』閲覧リンクを追加。家族アプリ8cdbaab\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">家族・ケアマネのログインUX改善(利用規約1回化・ホーム追加案内・Q&amp;A・規約リンク)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用規約が毎回表示され煩わしかった。高齢者がホーム画面追加やログイン失敗時に迷いやすい。ログイン後に規約を見返す導線も無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用規約の再同意を端末×ポリシー版で記録し同じ版なら二度と出さない(1回)。ログイン画面に『ホーム画面に追加する方法』(iOS/Android手順)と『ログインできない時(Q&amp;A)』を追加。ログイン後フッターに『利用規約・プライバシーポリシー』閲覧リンクを追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8cdbaab</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"アカウント管理の操作ボタン潰れを修正＋エラー画面に原因表示アカウント一覧の操作ボタンが col-span-1(約8%幅)に押し込まれ、スマホで潰れて見切れていた。また画面エラー時に原因が極薄色で読めなかった。操作ボタンにラベル(id編集/印刷/削除)を付け、スマホでは縦積みに(grid 4+3+2+3)。エラー画面は原因(スタック)を読める色で表示。家族アプリa4f60c9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">アカウント管理の操作ボタン潰れを修正＋エラー画面に原因表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アカウント一覧の操作ボタンが col-span-1(約8%幅)に押し込まれ、スマホで潰れて見切れていた。また画面エラー時に原因が極薄色で読めなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>操作ボタンにラベル(ID編集/印刷/削除)を付け、スマホでは縦積みに(grid 4+3+2+3)。エラー画面は原因(スタック)を読める色で表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a4f60c9</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"緊急連絡先: ケアマネを非表示化＋フェイスシートでの削除が反映されない不具合を修正①主要連絡先がケアマネ(続柄=ケアマネ等)でも緊急連絡先に表示されていた。②フェイスシートで連絡先を削除して保存しても、既存へのupsert(追加更新)のみで削除されず、墓石も無いため同期で復活していた。①主要連絡先がケアマネ由来なら緊急連絡先に出さない。②家族連絡先はフェイスシートの編集結果で置き換え(削除を反映)、ケアマネ連絡先は保持。削除分は墓石(_deletedec)に記録し同期でも復活させない。利用者マスタ725a3fd\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">緊急連絡先: ケアマネを非表示化＋フェイスシートでの削除が反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①主要連絡先がケアマネ(続柄=ケアマネ等)でも緊急連絡先に表示されていた。②フェイスシートで連絡先を削除して保存しても、既存へのupsert(追加更新)のみで削除されず、墓石も無いため同期で復活していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①主要連絡先がケアマネ由来なら緊急連絡先に出さない。②家族連絡先はフェイスシートの編集結果で置き換え(削除を反映)、ケアマネ連絡先は保持。削除分は墓石(_deletedEC)に記録し同期でも復活させない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">725a3fd</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"pdf/画像プレビューの×ボタンを見やすく＋pdfのボタン重複を解消×閉じるボタンが半透明の白で、白いpdf面の上だと見えなかった。またpdf時に『ダウンロード』と『別タブで開く』が重複していた。×ボタンを赤・白枠・影で明確化(最前面)。pdfは『別タブで開く』のみ、画像は『ダウンロード』のみ表示に整理。ケアマネ連携fb510e8\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">PDF/画像プレビューの×ボタンを見やすく＋PDFのボタン重複を解消</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">×閉じるボタンが半透明の白で、白いPDF面の上だと見えなかった。またPDF時に『ダウンロード』と『別タブで開く』が重複していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>×ボタンを赤・白枠・影で明確化(最前面)。PDFは『別タブで開く』のみ、画像は『ダウンロード』のみ表示に整理。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fb510e8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"その他関係者(訪問看護等)もフェイスシートへ一本化その他関係者だけ利用者マスタで編集する形が残り、他項目(氏名・連絡先・介護保険)をフェイスシートへ一本化した方針と不揃いだった。フェイスシートに『その他関係者』の編集枠(追加/削除・氏名/種別/事業所/電話/fax)を新設し、保存で利用者本体へ反映(事業所・ケアマネ両経路)。利用者マスタ基本情報のその他関係者は表形式(表示のみ)＋『フェイスシートで編集』に。利用者マスタ8f0483a\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">その他関係者(訪問看護等)もフェイスシートへ一本化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">その他関係者だけ利用者マスタで編集する形が残り、他項目(氏名・連絡先・介護保険)をフェイスシートへ一本化した方針と不揃いだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>フェイスシートに『その他関係者』の編集枠(追加/削除・氏名/種別/事業所/電話/FAX)を新設し、保存で利用者本体へ反映(事業所・ケアマネ両経路)。利用者マスタ基本情報のその他関係者は表形式(表示のみ)＋『フェイスシートで編集』に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8f0483a</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ側で事業所が添付したpdf(保険証・負担割合証)が見れない不具合を修正事業所がアップロードしたpdfは type=&#x27;application/pdf&#x27; で保存されるが、ケアマネ画面のファイル表示は type===&#x27;pdf&#x27;(完全一致)で判定していたため、事業所pdfが画像扱いになり壊れて表示されていた(ケアマネ自身がアップした分は type=&#x27;pdf&#x27; のため見れていた)。加えて data uri のpdfはブラウザがiframe/別タブでブロックする。ファイル表示・プレビューのpdf判定を『type部分一致 または .pdf名』に堅牢化。data uri のpdfは blob url に変換して表示し、『別タブで開く』ボタンも追加。事業所・ケアマネのどちらが添付したpdfも双方で閲覧可能に。ケアマネ連携52590d4\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ケアマネ側で事業所が添付したPDF(保険証・負担割合証)が見れない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">事業所がアップロードしたPDFは type=&#x27;application/pdf&#x27; で保存されるが、ケアマネ画面のファイル表示は type===&#x27;pdf&#x27;(完全一致)で判定していたため、事業所PDFが画像扱いになり壊れて表示されていた(ケアマネ自身がアップした分は type=&#x27;pdf&#x27; のため見れていた)。加えて data URI のPDFはブラウザがiframe/別タブでブロックする。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ファイル表示・プレビューのPDF判定を『type部分一致 または .pdf名』に堅牢化。data URI のPDFは Blob URL に変換して表示し、『別タブで開く』ボタンも追加。事業所・ケアマネのどちらが添付したPDFも双方で閲覧可能に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">52590d4</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"基本情報の並び調整＋担当ケアマネ・緊急連絡先も表形式に統一介護保険の期間が値と離れて分かりにくく、担当ケアマネ・緊急連絡先だけ従来の入力欄形式で見た目が不揃いだった。介護度の直下に認定有効期間、負担割合の直下に負担割合の有効期間を配置。担当ケアマネは表形式(表示のみ)＋『担当を変更』ボタン(履歴付きモーダル)、緊急連絡先は表形式(主要＋追加をまとめて表示)＋『フェイスシートで編集』に統一。利用者マスタ5177da2\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">基本情報の並び調整＋担当ケアマネ・緊急連絡先も表形式に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護保険の期間が値と離れて分かりにくく、担当ケアマネ・緊急連絡先だけ従来の入力欄形式で見た目が不揃いだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度の直下に認定有効期間、負担割合の直下に負担割合の有効期間を配置。担当ケアマネは表形式(表示のみ)＋『担当を変更』ボタン(履歴付きモーダル)、緊急連絡先は表形式(主要＋追加をまとめて表示)＋『フェイスシートで編集』に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5177da2</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ基本情報(表示のみ)を表形式に変更し見やすく表示のみ化した基本情報が「ラベル 値／ラベル 値」の2列詰めで、項目が追いづらく見づらかった。ラベル＝左(薄い背景)／値＝右の行(表)形式に統一(氏名・介護保険・住所連絡先の各カード)。罫線区切りで一覧性を向上。利用者マスタa191a33\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者マスタ基本情報(表示のみ)を表形式に変更し見やすく</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">表示のみ化した基本情報が「ラベル 値／ラベル 値」の2列詰めで、項目が追いづらく見づらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ラベル＝左(薄い背景)／値＝右の行(表)形式に統一(氏名・介護保険・住所連絡先の各カード)。罫線区切りで一覧性を向上。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a191a33</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ基本情報を表示のみ化し、編集をフェイスシート／個人ファイルへ一本化(仕上げ)氏名・住所・連絡先・被保険者番号・介護保険が複数画面で編集でき『どこで入力するか』が分かりにくかった。編集場所が一本化されれば、慣れない人でも迷わず、二重編集の巻き戻りも防げる。利用者マスタ基本情報の 氏名/フリガナ/性別/生年月日・住所/電話/メール・被保険者番号 を表示のみに。各ブロックの『フェイスシートで編集』で個人ファイルのフェイスシートを自動オープン、介護度・負担割合・認定期間は『個人ファイルで編集』で保険証/負担割合証へジャンプ。運用項目(利用状態・利用開始/終了日・担当ケアマネ)はマスタで編集可のまま。利用者マスタd8e377f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者マスタ基本情報を表示のみ化し、編集をフェイスシート／個人ファイルへ一本化(仕上げ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名・住所・連絡先・被保険者番号・介護保険が複数画面で編集でき『どこで入力するか』が分かりにくかった。編集場所が一本化されれば、慣れない人でも迷わず、二重編集の巻き戻りも防げる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者マスタ基本情報の 氏名/フリガナ/性別/生年月日・住所/電話/メール・被保険者番号 を表示のみに。各ブロックの『フェイスシートで編集』で個人ファイルのフェイスシートを自動オープン、介護度・負担割合・認定期間は『個人ファイルで編集』で保険証/負担割合証へジャンプ。運用項目(利用状態・利用開始/終了日・担当ケアマネ)はマスタで編集可のまま。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8e377f</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"フェイスシートを利用者情報の編集ハブ化(本人情報・被保険者番号・留意点を編集可＋誰が編集しても1箇所に反映)氏名・住所・電話・被保険者番号等が利用者マスタでしか編集できず、フェイスシート・個人ファイルとの役割が曖昧だった。事業所・ケアマネ・家族が別々の画面で編集し、どこが正か分かりにくい。フェイスシートで氏名/フリガナ/生年月日/性別/住所/電話/メール/被保険者番号/留意点を編集可能にし、保存時に利用者本体へ書き戻す(事業所・ケアマネ両経路)。誰が編集しても最終反映先は利用者本体の1箇所に統一。あわせて保険証・負担割合証の期間入力を和暦のみ(西暦カレンダー廃止)に。※マスタ側の該当項目を表示のみにする対応は次段階。利用者マスタ02ecdb6\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">フェイスシートを利用者情報の編集ハブ化(本人情報・被保険者番号・留意点を編集可＋誰が編集しても1箇所に反映)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名・住所・電話・被保険者番号等が利用者マスタでしか編集できず、フェイスシート・個人ファイルとの役割が曖昧だった。事業所・ケアマネ・家族が別々の画面で編集し、どこが正か分かりにくい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>フェイスシートで氏名/フリガナ/生年月日/性別/住所/電話/メール/被保険者番号/留意点を編集可能にし、保存時に利用者本体へ書き戻す(事業所・ケアマネ両経路)。誰が編集しても最終反映先は利用者本体の1箇所に統一。あわせて保険証・負担割合証の期間入力を和暦のみ(西暦カレンダー廃止)に。※マスタ側の該当項目を表示のみにする対応は次段階。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02ecdb6</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護保険・負担割合の適用期間の表示を和暦に統一適用期間・変更履歴が西暦(2026/4/1等)表示で、介護保険証・負担割合証の実物(和暦)と突き合わせづらかった。マスタ基本情報の認定有効期間・負担割合の有効期間の表示、および変更履歴(valuehistorylist)の期間表示を和暦(令和8年4月1日等)に変更。利用者マスタc146458\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護保険・負担割合の適用期間の表示を和暦に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">適用期間・変更履歴が西暦(2026/4/1等)表示で、介護保険証・負担割合証の実物(和暦)と突き合わせづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マスタ基本情報の認定有効期間・負担割合の有効期間の表示、および変更履歴(ValueHistoryList)の期間表示を和暦(令和8年4月1日等)に変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c146458</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護保険(介護度・負担割合・認定期間)の編集を個人ファイルへ一本化(マスタ基本情報は表示のみ＋ジャンプ)同じ介護度・負担割合・認定期間が『利用者マスタの基本情報』と『個人ファイル』の両方で編集でき、どちらで入力するか分かりにくく、二重編集による巻き戻りの温床でもあった。証の写真は個人ファイルにしか貼れない。マスタ基本情報では介護度・負担割合・認定有効期間を表示のみにし、『個人ファイルで編集』ボタンで個人ファイル(保険証・負担割合証)へジャンプ＋該当セクションへ自動スクロール。編集場所を個人ファイルに一本化(写真と同じ場所で管理)。被保険者番号は個人ファイルに編集欄が無いためマスタ編集のまま残置。氏名・住所・電話等の個人ファイルへの移設は編集ui新設が必要なため次段階。利用者マスタ2f6fcac\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護保険(介護度・負担割合・認定期間)の編集を個人ファイルへ一本化(マスタ基本情報は表示のみ＋ジャンプ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同じ介護度・負担割合・認定期間が『利用者マスタの基本情報』と『個人ファイル』の両方で編集でき、どちらで入力するか分かりにくく、二重編集による巻き戻りの温床でもあった。証の写真は個人ファイルにしか貼れない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マスタ基本情報では介護度・負担割合・認定有効期間を表示のみにし、『個人ファイルで編集』ボタンで個人ファイル(保険証・負担割合証)へジャンプ＋該当セクションへ自動スクロール。編集場所を個人ファイルに一本化(写真と同じ場所で管理)。被保険者番号は個人ファイルに編集欄が無いためマスタ編集のまま残置。氏名・住所・電話等の個人ファイルへの移設は編集UI新設が必要なため次段階。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2f6fcac</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"個人ファイルの介護保険証・負担割合証を「選択即保存」から「保存ボタンで確定」に個人ファイル(利用者を開いた詳細画面)の保険証(介護度・認定有効期間)/負担割合証(負担割合・有効期間)は、プルダウンや日付を選んだ瞬間に利用者マスタへ自動保存・履歴記録されていた。期間を決める前の暫定選択がそのまま確定してしまう。選択・期間変更は下書きに溜め、『保存』ボタンを押したときだけ確定(取消可)する方式に変更。従来のインライン自動保存を廃止。※前回の対応は利用者マスタ管理の別レイアウト側で、実際に使う個人ファイル側に未反映だったのを修正。利用者マスタa1dd0d3\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">個人ファイルの介護保険証・負担割合証を「選択即保存」から「保存ボタンで確定」に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個人ファイル(利用者を開いた詳細画面)の保険証(介護度・認定有効期間)/負担割合証(負担割合・有効期間)は、プルダウンや日付を選んだ瞬間に利用者マスタへ自動保存・履歴記録されていた。期間を決める前の暫定選択がそのまま確定してしまう。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>選択・期間変更は下書きに溜め、『保存』ボタンを押したときだけ確定(取消可)する方式に変更。従来のインライン自動保存を廃止。※前回の対応は利用者マスタ管理の別レイアウト側で、実際に使う個人ファイル側に未反映だったのを修正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1dd0d3</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"一括削除の「重複候補」に統合機能を追加（記録を残す1人へ引き継ぐ）利用者マスタの「重複」ボタン(統合)を各種設定へ集約するにあたり、各種設定側は削除しかできなかった。両方に記録がある重複を安全に1人へまとめる手段が必要だった。重複候補を同名でグループ化し、グループごとに『残す1人』をラジオで選んで統合できるように。統合すると他の重複の記録(提供記録・シフト・写真等)を残す人へ付け替え、空欄も補完してから重複を削除する(記録は失われない)。記録件数を各行に表示し、既定は記録が最も多い人を残す。各種設定188b16e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">一括削除の「重複候補」に統合機能を追加（記録を残す1人へ引き継ぐ）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者マスタの「重複」ボタン(統合)を各種設定へ集約するにあたり、各種設定側は削除しかできなかった。両方に記録がある重複を安全に1人へまとめる手段が必要だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>重複候補を同名でグループ化し、グループごとに『残す1人』をラジオで選んで統合できるように。統合すると他の重複の記録(提供記録・シフト・写真等)を残す人へ付け替え、空欄も補完してから重複を削除する(記録は失われない)。記録件数を各行に表示し、既定は記録が最も多い人を残す。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">188b16e</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護度の適用期間を「変更ボタン→ポップアップ→保存」方式に変更（重複ボタンは各種設定へ集約し削除）直前の対応(下書き＋小さな保存ボタン)は、編集→保存の手数が多く分かりやすくなかった。また利用者マスタの「重複」統合は各種設定の一括削除(重複候補)へ機能を集約した。介護度の適用期間は、現在の期間を表示し「適用期間を変更」ボタンでポップアップを開き、介護度・開始日/終了日を選んで保存する方式に統一(負担割合・介護度変更と同じ操作感。期間の訂正では履歴を増やさない)。利用者マスタの「重複」ボタンは削除。利用者マスタ3002443\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護度の適用期間を「変更ボタン→ポップアップ→保存」方式に変更（重複ボタンは各種設定へ集約し削除）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直前の対応(下書き＋小さな保存ボタン)は、編集→保存の手数が多く分かりやすくなかった。また利用者マスタの「重複」統合は各種設定の一括削除(重複候補)へ機能を集約した。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度の適用期間は、現在の期間を表示し「適用期間を変更」ボタンでポップアップを開き、介護度・開始日/終了日を選んで保存する方式に統一(負担割合・介護度変更と同じ操作感。期間の訂正では履歴を増やさない)。利用者マスタの「重複」ボタンは削除。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3002443</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"各種設定\" data-text=\"利用者・ケアマネ事業所の一括削除が管理者以外でも操作できた問題を修正「管理者用」と表示しつつ、実際の表示条件が isadmin(=管理者に加えmanager職も含む)だったため、管理者以外のログインでも一括削除が使えてしまっていた。介護記録に紐づく重要データを消せる画面のため危険だった。ログイン情報カード等と同じ canadmin(管理者パスワード認証済み / super_admin / 管理者未設定時のみ)に統一。管理者以外には操作させず、未認証時は『管理者のみ』ゲート＋認証ボタンを表示する。各種設定0cb6b26\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者・ケアマネ事業所の一括削除が管理者以外でも操作できた問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「管理者用」と表示しつつ、実際の表示条件が isAdmin(=管理者に加えmanager職も含む)だったため、管理者以外のログインでも一括削除が使えてしまっていた。介護記録に紐づく重要データを消せる画面のため危険だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ログイン情報カード等と同じ canAdmin(管理者パスワード認証済み / super_admin / 管理者未設定時のみ)に統一。管理者以外には操作させず、未認証時は『管理者のみ』ゲート＋認証ボタンを表示する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0cb6b26</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"一括削除に「重複候補」フィルタを追加(重複利用者の削除)氏名が同じ重複利用者(csv取込の二重登録等)を、利用者マスタの統合とは別に、まとめて確認・削除する手段が各種設定側に無かった。一括削除の利用者一覧に『重複候補』フィルタ(同名2件以上)を追加。各行に記録件数と重複バッジを表示し、記録0件の重複を選んで削除できるようにした。両方に記録がある場合は記録が消えるため、利用者マスタの『重複』統合(記録引き継ぎ)を案内。各種設定0cb6b26\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">一括削除に「重複候補」フィルタを追加(重複利用者の削除)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名が同じ重複利用者(CSV取込の二重登録等)を、利用者マスタの統合とは別に、まとめて確認・削除する手段が各種設定側に無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>一括削除の利用者一覧に『重複候補』フィルタ(同名2件以上)を追加。各行に記録件数と重複バッジを表示し、記録0件の重複を選んで削除できるようにした。両方に記録がある場合は記録が消えるため、利用者マスタの『重複』統合(記録引き継ぎ)を案内。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0cb6b26</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護度の適用期間も選択即保存をやめ、確定ボタン方式に介護度の適用期間(カレンダー)を編集すると、確定前でも1.5秒後に自動保存され、暫定の期間がそのまま全端末へ反映されていた。期間は下書きに溜め、『この期間で保存』を押したときだけ保存する方式に変更(負担割合と同じ考え方)。取消もできる。利用者マスタ88ee804\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護度の適用期間も選択即保存をやめ、確定ボタン方式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護度の適用期間(カレンダー)を編集すると、確定前でも1.5秒後に自動保存され、暫定の期間がそのまま全端末へ反映されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間は下書きに溜め、『この期間で保存』を押したときだけ保存する方式に変更(負担割合と同じ考え方)。取消もできる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">88ee804</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"「元に戻す」でokしても記録が画面に反映されない不具合を修正復元は onsave で提供記録を更新するが、提供記録入力(recordview)の画面用データを作り直すエフェクトに「同じ日付で編集中(dirty)なら作り直さない」ガードがあり、復元が編集中フラグを落とさないため、データは復元されているのに画面が復元前のまま(=戻したのに変わらない)になっていた。復元の適用後に編集中フラグ(dirtyref)を落とし、必ず画面を作り直すようにした。これで選んだ時点の内容が即座に画面へ反映される。提供記録2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">「元に戻す」でOKしても記録が画面に反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">復元は onSave で提供記録を更新するが、提供記録入力(RecordView)の画面用データを作り直すエフェクトに「同じ日付で編集中(dirty)なら作り直さない」ガードがあり、復元が編集中フラグを落とさないため、データは復元されているのに画面が復元前のまま(=戻したのに変わらない)になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>復元の適用後に編集中フラグ(dirtyRef)を落とし、必ず画面を作り直すようにした。これで選んだ時点の内容が即座に画面へ反映される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"ipad等で利用者マスタの右端が見切れる問題を修正画面は横1100px設計を前提にzoom縮小して各端末に合わせているが、利用者マスタは最大1800px・340px固定リスト＋多列で、ipad(縦810/横1080px)では実画面幅で多列レイアウトが発火して1100pxの枠をはみ出し、下までスクロールすると右端が切れていた。利用者マスタをzoom縮小の対象から外し、実際の画面幅で素直に折り返す方式に変更(pcは従来どおり)。端末ごとに画面領域へ収まるようにした。利用者マスタ2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">iPad等で利用者マスタの右端が見切れる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">画面は横1100px設計を前提にzoom縮小して各端末に合わせているが、利用者マスタは最大1800px・340px固定リスト＋多列で、iPad(縦810/横1080px)では実画面幅で多列レイアウトが発火して1100pxの枠をはみ出し、下までスクロールすると右端が切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者マスタをzoom縮小の対象から外し、実際の画面幅で素直に折り返す方式に変更(PCは従来どおり)。端末ごとに画面領域へ収まるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"負担割合をプルダウン選択した瞬間に保存されるのをやめ、確定ボタン方式に負担割合を選ぶと(適用期間を決める前でも)1.5秒後に自動でクラウド保存され、暫定選択がそのまま確定・全端末へ反映されてしまっていた。介護度と同じく、選択したら確認モーダルを開き、適用開始日/終了日を指定して「確定」を押したときだけ保存する方式に統一。誤選択がそのまま保存されないようにした。利用者マスタ2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">負担割合をプルダウン選択した瞬間に保存されるのをやめ、確定ボタン方式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">負担割合を選ぶと(適用期間を決める前でも)1.5秒後に自動でクラウド保存され、暫定選択がそのまま確定・全端末へ反映されてしまっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度と同じく、選択したら確認モーダルを開き、適用開始日/終了日を指定して「確定」を押したときだけ保存する方式に統一。誤選択がそのまま保存されないようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ホーム\" data-text=\"ホームの「家族・ケアマネからの更新」に、変更した項目名を表示家族・ケアマネが利用者情報を編集した通知が『利用者情報の編集』としか出ず、どこを直したのか分からなかった。編集前後を項目単位で比較し『利用者情報の編集（電話番号・住所 ほか）』のように変更項目名を表示(最大8件＋ほかn項目)。ホーム2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ホームの「家族・ケアマネからの更新」に、変更した項目名を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族・ケアマネが利用者情報を編集した通知が『利用者情報の編集』としか出ず、どこを直したのか分からなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>編集前後を項目単位で比較し『利用者情報の編集（電話番号・住所 ほか）』のように変更項目名を表示(最大8件＋ほかN項目)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"「元に戻す」の確認に、現在クラウド上の最新の端末・時刻を表示復元(元に戻す)は全端末へ「最新」として反映され、他端末の新しい入力を上書きしうる。従来の確認文は一般的な注意のみで、いま実際に誰が最新なのかが分からず、上書きの判断がしづらかった。確認ダイアログに _lastsync から「現在の最新: 『端末名』が 〇時 に更新」を常時表示。さらに、この復元スナップショットより後に別の端末が更新している場合のみ『⚠ この履歴より新しい更新が別端末にあります。復元すると上書きされます』を追加表示(自分が最新なら余計な警告は出さない)。提供記録a4f3d28\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">「元に戻す」の確認に、現在クラウド上の最新の端末・時刻を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">復元(元に戻す)は全端末へ「最新」として反映され、他端末の新しい入力を上書きしうる。従来の確認文は一般的な注意のみで、いま実際に誰が最新なのかが分からず、上書きの判断がしづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>確認ダイアログに _lastSync から「現在の最新: 『端末名』が 〇時 に更新」を常時表示。さらに、この復元スナップショットより後に別の端末が更新している場合のみ『⚠ この履歴より新しい更新が別端末にあります。復元すると上書きされます』を追加表示(自分が最新なら余計な警告は出さない)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a4f3d28</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"端末名の設定と「最終更新した端末」の表示を追加複数の端末(pc・ipad等)で使うと、今どの端末の入力が最新か分からず、古い端末で上書きしていないか不安があった。以前検討した「入力ロック」は現場運用の妨げになるため見送り、代わりに『誰が最後に更新したか』を可視化する方針にした。各種設定＞システムに「この端末の名前」欄を追加(端末ごとにlocalstorageへ保存。他端末には送信しない)。記録の保存時に「最終更新した端末名・時刻」を全端末共有の _lastsync に記録し、画面上部ヘッダーと設定画面に常時表示。最終更新が自端末なら緑「この端末の内容が最新です」、別端末なら青「最新の更新は〇〇で行われました(この端末にも反映済み)」を表示。ヘッダーの表示をタップすると設定の端末名欄へジャンプ。各種設定c44b757\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">端末名の設定と「最終更新した端末」の表示を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">複数の端末(PC・iPad等)で使うと、今どの端末の入力が最新か分からず、古い端末で上書きしていないか不安があった。以前検討した「入力ロック」は現場運用の妨げになるため見送り、代わりに『誰が最後に更新したか』を可視化する方針にした。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定＞システムに「この端末の名前」欄を追加(端末ごとにlocalStorageへ保存。他端末には送信しない)。記録の保存時に「最終更新した端末名・時刻」を全端末共有の _lastSync に記録し、画面上部ヘッダーと設定画面に常時表示。最終更新が自端末なら緑「この端末の内容が最新です」、別端末なら青「最新の更新は〇〇で行われました(この端末にも反映済み)」を表示。ヘッダーの表示をタップすると設定の端末名欄へジャンプ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c44b757</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"操作ログ同期の切替で提供記録の保存先が一時的に失われた不具合を修正し、段階導入へ変更差分を作る処理が参照していた変数 prev がスコープ外にあり referenceerror となって、操作が1件も作られていなかった(診断ログ ops-diff-error &quot;prev is not defined&quot; で判明)。にもかかわらず巨大json側の ticketrecords を先に凍結していたため、「新方式は動かない×旧方式も止めてある」という状態になり、その間の提供記録の保存がクラウドのどこにも書かれなかった。切替を一度に行ったこと自体が設計判断の誤り。差分の直前状態を appdata から取得するよう修正。oplog_frozen_keys を空に戻して巨大json方式を再有効化し、新方式が動かなくても必ず保存される二重の保険とした。さらに oplog_apply フラグを追加し、第1段は「操作ログへの送信のみ」を本番で走らせる方式に変更。受信適用と旧方式の凍結は、送信の安定をログで確認してから第2段でまとめて有効化する。同期703dd4c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">操作ログ同期の切替で提供記録の保存先が一時的に失われた不具合を修正し、段階導入へ変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">差分を作る処理が参照していた変数 prev がスコープ外にあり ReferenceError となって、操作が1件も作られていなかった(診断ログ ops-diff-error &quot;prev is not defined&quot; で判明)。にもかかわらず巨大JSON側の ticketRecords を先に凍結していたため、「新方式は動かない×旧方式も止めてある」という状態になり、その間の提供記録の保存がクラウドのどこにも書かれなかった。切替を一度に行ったこと自体が設計判断の誤り。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分の直前状態を appData から取得するよう修正。OPLOG_FROZEN_KEYS を空に戻して巨大JSON方式を再有効化し、新方式が動かなくても必ず保存される二重の保険とした。さらに OPLOG_APPLY フラグを追加し、第1段は「操作ログへの送信のみ」を本番で走らせる方式に変更。受信適用と旧方式の凍結は、送信の安定をログで確認してから第2段でまとめて有効化する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">703dd4c</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"同期\" data-text=\"提供記録を操作ログ同期へ接続（送信・受信・リベース・凍結の実装）巨大jsonの往復方式では、2端末での編集時にマージの勝ち負けで入力が消える問題が構造的に解消できないため。保存時に変わった項目だけを差分化してindexeddbへ永続化し sync_ops へ送信、ackが返った分だけキューから削除。受信はrealtime＋5秒ポーリングで差分取得。適用は必ず「受信分＋自分の未送信分」の順で畳み込み(リベース)、他端末の更新を受けた瞬間に入力途中が消えないようにした。初回取得はページングで全件取得。差分化と適用の純関数を28ケースで検証。同期ec97394\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">提供記録を操作ログ同期へ接続（送信・受信・リベース・凍結の実装）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">巨大JSONの往復方式では、2端末での編集時にマージの勝ち負けで入力が消える問題が構造的に解消できないため。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存時に変わった項目だけを差分化してIndexedDBへ永続化し sync_ops へ送信、ACKが返った分だけキューから削除。受信はRealtime＋5秒ポーリングで差分取得。適用は必ず「受信分＋自分の未送信分」の順で畳み込み(リベース)、他端末の更新を受けた瞬間に入力途中が消えないようにした。初回取得はページングで全件取得。差分化と適用の純関数を28ケースで検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec97394</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"同期\" data-text=\"同期方式の刷新に着手（操作ログ方式）：基盤モジュールとdbマイグレーションを用意時計補正・押し戻し遮断の修正後も同期停止が再発。根本原因は「アプリ全体の巨大jsonを1.2秒ごとに丸ごと送り合い、端末の時計でマージの勝敗を決めている」という構造そのものにある。加えて送信キューもackも無いため、iosの通信サスペンドで失われた送信は永久に失われる。「変更した項目だけを送る」操作ログ方式へ移行する。src/lib/syncops.js を新設（送信未確定キューをindexeddbに永続化／push_sync_ops rpcへの送信とackによるキュー削除／revision差分取得とrealtime購読／操作を状態へ畳み込む純関数applyops）。順序はpostgresのbigserial採番が決めるため端末の時計に一切依存しない。純関数部分を18ケース（項目更新・入れ子・新規作成・深い階層・二次元マップ・空文字・レコード削除・set→deleteの順序・リベース・後勝ち・参照維持）で検証済み。dbマイグレーションsql（sync_opsテーブル／push_sync_ops rpc／rls／realtime有効化。追加のみ・非破壊）を sql/2026-07-20_sync_ops_phase1.sql に用意。現時点ではアプリ本体から未接続のため動作に影響なし。外部レビュー（gemini提案書）のうち「クライアント代表がスナップショットを上書きする」案は今回の事故と同じ構造のため不採用とし、db側で畳み込む方式に変更した。同期a041567 / f08a148\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">同期方式の刷新に着手（操作ログ方式）：基盤モジュールとDBマイグレーションを用意</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">時計補正・押し戻し遮断の修正後も同期停止が再発。根本原因は「アプリ全体の巨大JSONを1.2秒ごとに丸ごと送り合い、端末の時計でマージの勝敗を決めている」という構造そのものにある。加えて送信キューもACKも無いため、iOSの通信サスペンドで失われた送信は永久に失われる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「変更した項目だけを送る」操作ログ方式へ移行する。src/lib/syncOps.js を新設（送信未確定キューをIndexedDBに永続化／push_sync_ops RPCへの送信とACKによるキュー削除／revision差分取得とRealtime購読／操作を状態へ畳み込む純関数applyOps）。順序はPostgresのbigserial採番が決めるため端末の時計に一切依存しない。純関数部分を18ケース（項目更新・入れ子・新規作成・深い階層・二次元マップ・空文字・レコード削除・SET→DELETEの順序・リベース・後勝ち・参照維持）で検証済み。DBマイグレーションSQL（sync_opsテーブル／push_sync_ops RPC／RLS／Realtime有効化。追加のみ・非破壊）を sql/2026-07-20_sync_ops_phase1.sql に用意。現時点ではアプリ本体から未接続のため動作に影響なし。外部レビュー（Gemini提案書）のうち「クライアント代表がスナップショットを上書きする」案は今回の事故と同じ構造のため不採用とし、DB側で畳み込む方式に変更した。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a041567 / f08a148</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"同期\" data-text=\"未同期バナーを撤去し、原因特定用の同期診断ログを追加未同期警告バナーが誤検知で常時表示され作業の邪魔になっていた。また、時計補正と押し戻しループの修正後も同期が止まる事象が再発したが、ipadではブラウザのコンソールが見られず原因を特定する手段が無かった。バナーの画面表示を廃止(検知自体は継続しログにのみ記録)。localstorageに直近120件の同期イベント(save/pull/pull-preserve/push-ok/push-fail/cas-conflict/clock-adjust/stall)を記録し、urlに ?syncdebug=1 を付けて開くと右下に同期ログパネルを表示できるようにした。再現時のログから、保存が発火しているか・クラウドへ届いているか・競合で失敗しているかを切り分ける。同期edbe195\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">未同期バナーを撤去し、原因特定用の同期診断ログを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">未同期警告バナーが誤検知で常時表示され作業の邪魔になっていた。また、時計補正と押し戻しループの修正後も同期が止まる事象が再発したが、iPadではブラウザのコンソールが見られず原因を特定する手段が無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>バナーの画面表示を廃止(検知自体は継続しログにのみ記録)。localStorageに直近120件の同期イベント(save/pull/pull-preserve/push-ok/push-fail/cas-conflict/clock-adjust/stall)を記録し、URLに ?syncdebug=1 を付けて開くと右下に同期ログパネルを表示できるようにした。再現時のログから、保存が発火しているか・クラウドへ届いているか・競合で失敗しているかを切り分ける。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">edbe195</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"他端末の入力をクラウドから消し戻し続けるループを遮断pull(4秒ごと)の「端末内の記録を保持する」処理が、『端末内の_savedatがクラウドより新しい』というだけで記録を丸ごとクラウドへ押し戻していた。時計が進んだ端末ではこの条件が常に成立するため、他端末が入力するたびに4秒後に古い内容で上書きし直すループになり、同期が止まったように見えていた。さらに双方が押し合うことで楽観ロック(cas)の競合が増え、既定5回の再試行を使い切って保存自体が失敗することもあった。再送(push)するのは「クラウドに存在しない記録があるとき」＝pushが本当に届いていない場合だけに限定。クラウドにも存在する記録の新旧判定は、項目単位でマージする通常の保存経路に任せる。あわせて通常保存のcas再試行を5→8回に増強。保持・墓石・クラウド優先の各挙動は6ケースで回帰検証済み。同期1118876\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">他端末の入力をクラウドから消し戻し続けるループを遮断</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pull(4秒ごと)の「端末内の記録を保持する」処理が、『端末内の_savedAtがクラウドより新しい』というだけで記録を丸ごとクラウドへ押し戻していた。時計が進んだ端末ではこの条件が常に成立するため、他端末が入力するたびに4秒後に古い内容で上書きし直すループになり、同期が止まったように見えていた。さらに双方が押し合うことで楽観ロック(CAS)の競合が増え、既定5回の再試行を使い切って保存自体が失敗することもあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>再送(push)するのは「クラウドに存在しない記録があるとき」＝pushが本当に届いていない場合だけに限定。クラウドにも存在する記録の新旧判定は、項目単位でマージする通常の保存経路に任せる。あわせて通常保存のCAS再試行を5→8回に増強。保持・墓石・クラウド優先の各挙動は6ケースで回帰検証済み。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1118876</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"端末間の時計ズレで同期が止まり、入力が消える不具合を恒久修正同期のマージは記録の _savedat / _fieldts（保存時刻）が新しい方を採用する方式だが、この時刻は各端末の date.now()＝端末の時計そのものだった。pcの時計がipadより進んでいると、ipadで入力した内容は常に「古い」と判定されてマージで捨てられる。画面上はエラーも出ないため同期が止まったように見え、再読み込みするとクラウドの古い内容に戻って入力が消える。長文入力ほど同一項目を上書きし続けるため発症しやすかった。同期専用の単調時計(lamport clock)を導入。app_state に __clock（そのデータの最大同期時刻）を持たせ、クラウドを読むたびに自端末のオフセットを引き上げて「クラウドで見た最新より必ず新しい時刻」を刻むようにした。これで端末の時計がずれていても後から行った入力が必ず勝つ。__clock を持たない既存データは記録の _savedat 最大値から初期化。400日以上先の異常な時刻は取り込まない安全弁つき。あわせて _savedat/_fieldts/_updatedat の刻印を全26箇所で新方式に統一。さらに、ローカル編集から20秒以上クラウド保存が成功していない場合は画面上部に「⚠ クラウドに保存できていません（n秒未同期）」＋「今すぐ再送」を常時表示し、同期停止が無表示のまま続かないようにした。同期18fda72\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">端末間の時計ズレで同期が止まり、入力が消える不具合を恒久修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同期のマージは記録の _savedAt / _fieldTs（保存時刻）が新しい方を採用する方式だが、この時刻は各端末の Date.now()＝端末の時計そのものだった。PCの時計がiPadより進んでいると、iPadで入力した内容は常に「古い」と判定されてマージで捨てられる。画面上はエラーも出ないため同期が止まったように見え、再読み込みするとクラウドの古い内容に戻って入力が消える。長文入力ほど同一項目を上書きし続けるため発症しやすかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期専用の単調時計(Lamport clock)を導入。app_state に __clock（そのデータの最大同期時刻）を持たせ、クラウドを読むたびに自端末のオフセットを引き上げて「クラウドで見た最新より必ず新しい時刻」を刻むようにした。これで端末の時計がずれていても後から行った入力が必ず勝つ。__clock を持たない既存データは記録の _savedAt 最大値から初期化。400日以上先の異常な時刻は取り込まない安全弁つき。あわせて _savedAt/_fieldTs/_updatedAt の刻印を全26箇所で新方式に統一。さらに、ローカル編集から20秒以上クラウド保存が成功していない場合は画面上部に「⚠ クラウドに保存できていません（N秒未同期）」＋「今すぐ再送」を常時表示し、同期停止が無表示のまま続かないようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">18fda72</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"ケアマネ連携\" data-text=\"事業所の更新をケアマネへ通知：変更項目名の明示と保険証内容変更の追加フェイスシート更新の通知が「フェイスシート」としか出ず、どこを変えたか分からなかった。また介護保険証・負担割合証は「添付ファイルの更新」しか通知されず、要介護度や負担割合の内容変更はケアマネに届かなかった。新旧フェイスシートを項目単位で差分比較する difffacesheetfields を追加し「フェイスシート（服薬状況・通所の経緯）」のように変更項目名を表示（最大8件＋ほかn項目）。利用者マスタで要介護度／認定有効期間／負担割合を変更した際も、ケアマネにのみ未読通知（by=office / readcm=false）を発行。逆方向（ケアマネの編集→事業所ホーム「家族・ケアマネからの更新」）も項目名を表示。ケアマネ連携cdecfc6\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">事業所の更新をケアマネへ通知：変更項目名の明示と保険証内容変更の追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシート更新の通知が「フェイスシート」としか出ず、どこを変えたか分からなかった。また介護保険証・負担割合証は「添付ファイルの更新」しか通知されず、要介護度や負担割合の内容変更はケアマネに届かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>新旧フェイスシートを項目単位で差分比較する diffFaceSheetFields を追加し「フェイスシート（服薬状況・通所の経緯）」のように変更項目名を表示（最大8件＋ほかN項目）。利用者マスタで要介護度／認定有効期間／負担割合を変更した際も、ケアマネにのみ未読通知（by=office / readCm=false）を発行。逆方向（ケアマネの編集→事業所ホーム「家族・ケアマネからの更新」）も項目名を表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cdecfc6</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書4様式に一時保存を統一・残りの日付欄もカレンダー化一時保存が通所計画書のみで、個別機能訓練・生活機能チェック・興味関心は途中保存できず、一部の日付が手入力のままだった。4様式すべてに「一時保存／保存して閉じる」を追加。発症日・入院日・退院日・作成日等もカレンダー選択に統一。計画書98add01\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">計画書4様式に一時保存を統一・残りの日付欄もカレンダー化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">一時保存が通所計画書のみで、個別機能訓練・生活機能チェック・興味関心は途中保存できず、一部の日付が手入力のままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>4様式すべてに「一時保存／保存して閉じる」を追加。発症日・入院日・退院日・作成日等もカレンダー選択に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">98add01</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"負担割合証：開始日を選び直したら常に1年後を終了日に設定「終了日が空のときだけ」1年後を計算していたため、開始日を選び直しても既存の終了日が更新されず、今日基準の古い値が残っていた。開始日を変えたら常に 終了日＝開始日＋1年−1日 を再設定。うるう年含め検証。利用者マスタe8cb276\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">負担割合証：開始日を選び直したら常に1年後を終了日に設定</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「終了日が空のときだけ」1年後を計算していたため、開始日を選び直しても既存の終了日が更新されず、今日基準の古い値が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日を変えたら常に 終了日＝開始日＋1年−1日 を再設定。うるう年含め検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e8cb276</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書：日付のカレンダー選択・一時保存・目標期間の逆コピー日付が手入力のみ、途中保存ができず、期間コピーの向きが実務と逆だった。作成日・目標・提供内容①〜⑤等をカレンダー選択に。一時保存を追加。長期目標の期間を①〜⑤へ下ろすコピーに変更。計画書86d5926\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">通所介護計画書：日付のカレンダー選択・一時保存・目標期間の逆コピー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日付が手入力のみ、途中保存ができず、期間コピーの向きが実務と逆だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>作成日・目標・提供内容①〜⑤等をカレンダー選択に。一時保存を追加。長期目標の期間を①〜⑤へ下ろすコピーに変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">86d5926</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"LIFE加算\" data-text=\"生活機能チェックのadlからbarthel点数を提案同じ10項目を生活機能チェックとbarthelで二度入力していた。生活機能チェックのadl→barthel点数の対応表を作り、取り込みボタンで自動提案（最終確認は職員）。life加算c1c5f93\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">生活機能チェックのADLからBarthel点数を提案</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同じ10項目を生活機能チェックとBarthelで二度入力していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>生活機能チェックのADL→Barthel点数の対応表を作り、取り込みボタンで自動提案（最終確認は職員）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c1c5f93</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"生活機能チェック：項目名とプルダウンの間隔・幅を調整ラベルが固定幅でプルダウンが伸び、隣の項目とくっついて読みにくかった。項目名にプルダウンを寄せ、幅を縮小し、列間を広げた。計画書193774f\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">生活機能チェック：項目名とプルダウンの間隔・幅を調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ラベルが固定幅でプルダウンが伸び、隣の項目とくっついて読みにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>項目名にプルダウンを寄せ、幅を縮小し、列間を広げた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">193774f</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"計画書\" data-text=\"計画書：フェイスシート連携の参照先を修正・自動作成を廃止・1日の流れ/提供区分を自動化フェイスシートの保存先を取り違え、連携が丸ごと不動だった（自立度が入らない等）。利用者追加時に空の計画書が自動作成されていた。正しい保存先を参照。自動作成を廃止。1日の流れ（am/pm両方）と提供時間区分を自動算出。計画書700fe4a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">計画書：フェイスシート連携の参照先を修正・自動作成を廃止・1日の流れ/提供区分を自動化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシートの保存先を取り違え、連携が丸ごと不動だった（自立度が入らない等）。利用者追加時に空の計画書が自動作成されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>正しい保存先を参照。自動作成を廃止。1日の流れ（AM/PM両方）と提供時間区分を自動算出。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">700fe4a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳：反映元の「未選択」を廃止し、無効なら先頭項目に連動連動を選んでも未選択では自由記述と変わらず無意味だった。未選択という状態をなくし、無効なら先頭の運動項目に自動連動。表示と実挙動を一致させた。連絡帳7344829\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">連絡帳：反映元の「未選択」を廃止し、無効なら先頭項目に連動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">連動を選んでも未選択では自由記述と変わらず無意味だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>未選択という状態をなくし、無効なら先頭の運動項目に自動連動。表示と実挙動を一致させた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7344829</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳：反映元が未設定でも設定済みに見える問題を修正選択肢に空欄が無く、連動先が無効でもブラウザが先頭項目を表示。設定済みに見えて実際は連動しなかった。無効な連動先を検知し、名前一致でも値を拾えるよう解決規則を統一。連絡帳45c32c8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">連絡帳：反映元が未設定でも設定済みに見える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">選択肢に空欄が無く、連動先が無効でもブラウザが先頭項目を表示。設定済みに見えて実際は連動しなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>無効な連動先を検知し、名前一致でも値を拾えるよう解決規則を統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">45c32c8</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○の規定値を「月初」でなく記録の実日付で引く規定値を月の1日時点で引いていたため、月途中に設定した規定値が反映されず、店舗差になっていた。記録の実日付で規定値を引くよう修正。設定タイミングに関わらず反映。分析c5df252\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○の規定値を「月初」でなく記録の実日付で引く</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">規定値を月の1日時点で引いていたため、月途中に設定した規定値が反映されず、店舗差になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>記録の実日付で規定値を引くよう修正。設定タイミングに関わらず反映。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5df252</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○で規定値をグラフに反映・個別運動は選択した種目名で表示規定値の取得がid直接一致のみで、項目を作り直した店舗で取れなかった。個別運動が「個別運動①」表示だった。id一致→同名で解決。個別運動は選択した種目名（屋外歩行訓練等）で表示。分析c300df8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○で規定値をグラフに反映・個別運動は選択した種目名で表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">規定値の取得がid直接一致のみで、項目を作り直した店舗で取れなかった。個別運動が「個別運動①」表示だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>id一致→同名で解決。個別運動は選択した種目名（屋外歩行訓練等）で表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c300df8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録入力：規定値がセルに収まるようフォントを縮小文字サイズを入力値の長さだけで決め、規定値だけ表示の空セルで長い値がはみ出していた。規定値の長さも考慮してフォントサイズを決定。提供記録ac31e0d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">提供記録入力：規定値がセルに収まるようフォントを縮小</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">文字サイズを入力値の長さだけで決め、規定値だけ表示の空セルで長い値がはみ出していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>規定値の長さも考慮してフォントサイズを決定。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ac31e0d</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○は規定値を反映・個別運動の規定値ルックアップを修正○に単位が付き「○分」と表示。個別運動の規定値を持たない側を先に見て常に空だった。記号に単位を付けない。個別運動は利用者側の規定値を優先（3箇所修正）。分析9526174\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○は規定値を反映・個別運動の規定値ルックアップを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">○に単位が付き「○分」と表示。個別運動の規定値を持たない側を先に見て常に空だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>記号に単位を付けない。個別運動は利用者側の規定値を優先（3箇所修正）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9526174</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"店舗によって運動の○が分析個人に反映されない不具合を修正分析個人がid直接一致でしか値を引かず、項目を作り直した店舗だけ「記録なし」になっていた。idが変わっても同名で拾う解決関数に統一。分析add9d88\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">店舗によって運動の○が分析個人に反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">分析個人がid直接一致でしか値を引かず、項目を作り直した店舗だけ「記録なし」になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>idが変わっても同名で拾う解決関数に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">add9d88</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"分析個人：○(実施)の記録が規定値未設定の月に消える不具合を修正○を規定値に置換する際、規定値が未設定の月は空を返し、実施記録が「記録なし」扱いになっていた。規定値が無くても○のまま残す。分析ffcf5d6\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○(実施)の記録が規定値未設定の月に消える不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">○を規定値に置換する際、規定値が未設定の月は空を返し、実施記録が「記録なし」扱いになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>規定値が無くても○のまま残す。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ffcf5d6</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"体力測定グラフ：最低のフォントを揃え、開始位置の右寄りを直す最低のラベルだけ極端に小さく、1件時にグラフ開始点が大きく右へずれていた。体温グラフと同じ体裁に統一し、固定ステップ＋左パディング方式に。分析9b76c39\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">体力測定グラフ：最低のフォントを揃え、開始位置の右寄りを直す</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">最低のラベルだけ極端に小さく、1件時にグラフ開始点が大きく右へずれていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>体温グラフと同じ体裁に統一し、固定ステップ＋左パディング方式に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9b76c39</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"体力測定\" data-text=\"体力測定：タップでテンキー表示・全角入力を半角へ自動変換身長体重等の数値入力でテンキーが出ず、全角入力すると値が消えることがあった。提供記録と同じテンキーを表示。全角数字・句読点を半角へ自動変換。体力測定41549bc\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">体力測定</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">体力測定：タップでテンキー表示・全角入力を半角へ自動変換</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">身長体重等の数値入力でテンキーが出ず、全角入力すると値が消えることがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録と同じテンキーを表示。全角数字・句読点を半角へ自動変換。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41549bc</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"利用者マスタの電話番号（固定/携帯）に自動でハイフンを付与既存フォーマッタから漏れ、全角入力で番号が消える不具合もあった。共通フォーマッタに統一し、全角対応も追加。12ケースで検証。利用者マスタ50aa40b\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">利用者マスタの電話番号（固定/携帯）に自動でハイフンを付与</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">既存フォーマッタから漏れ、全角入力で番号が消える不具合もあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>共通フォーマッタに統一し、全角対応も追加。12ケースで検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50aa40b</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"作成予定をホームからサイドバー「計画書 &gt; 作成予定」へ移動導入直後は全員が未作成で件数が膨らみ、ホームで実用にならなかった。専用画面に移動。未作成は既定で隠し、必要時に表示できるように。計画書b6ec8b9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">作成予定をホームからサイドバー「計画書 &gt; 作成予定」へ移動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">導入直後は全員が未作成で件数が膨らみ、ホームで実用にならなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>専用画面に移動。未作成は既定で隠し、必要時に表示できるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b6ec8b9</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"計画書・加算の作成時期を通知作成期限の把握手段がなく、作成漏れが起きやすかった。期限の1ヶ月前から、誰の・何を・いつまでにを月ごとに表示。計画書f86b363\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">計画書・加算の作成時期を通知</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">作成期限の把握手段がなく、作成漏れが起きやすかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期限の1ヶ月前から、誰の・何を・いつまでにを月ごとに表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f86b363</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"共通項目の連携：自立度をフェイスシート起点に統一自立度が3画面で別名保存され、半角/全角の違いで○が付かなかった。表記ゆれを吸収し、フェイスシートを正として各計画書へ取り込み。計画書67e213a\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">共通項目の連携：自立度をフェイスシート起点に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">自立度が3画面で別名保存され、半角/全角の違いで○が付かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>表記ゆれを吸収し、フェイスシートを正として各計画書へ取り込み。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">67e213a</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"計画書\" data-text=\"個別機能訓練計画書（様式3-3）をa4 1枚で使い切る高さ指定がなく下部に余白が残っていた。a4実寸の縦フレックスにし、各記入欄を比率配分。計画書eb4f153\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">個別機能訓練計画書（様式3-3）をA4 1枚で使い切る</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">高さ指定がなく下部に余白が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>A4実寸の縦フレックスにし、各記入欄を比率配分。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb4f153</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"提供記録\" data-text=\"月モードの保存で他の月の記録が全て消えるバグを修正選択月のみ保持する配列で全記録を置換しており、保存で他月が失われる構造だった（未使用画面／予防）。id単位のマージに変更し、選択月以外を必ず温存。提供記録dc4a6c0\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">月モードの保存で他の月の記録が全て消えるバグを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">選択月のみ保持する配列で全記録を置換しており、保存で他月が失われる構造だった（未使用画面／予防）。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>id単位のマージに変更し、選択月以外を必ず温存。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">dc4a6c0</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"検索一覧の表示を提供記録入力に完全に合わせる色・脈表記・介護整体列が入力画面と揃っていなかった。状態色・脈（）表記・介護整体列を入力画面と統一。提供記録61bb967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">検索一覧の表示を提供記録入力に完全に合わせる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">色・脈表記・介護整体列が入力画面と揃っていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>状態色・脈（）表記・介護整体列を入力画面と統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">61bb967</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"氏名検索の月一覧を提供記録入力と同じ表形式に検索結果がテキスト一覧で入力画面と見え方が違った。同じ列構成の表にし、行タップで当日入力へジャンプ。提供記録02e699d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">氏名検索の月一覧を提供記録入力と同じ表形式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">検索結果がテキスト一覧で入力画面と見え方が違った。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同じ列構成の表にし、行タップで当日入力へジャンプ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02e699d</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"家族アプリ\" data-text=\"分析個人の公開範囲：モニタリングはケアマネのみ・特記は本人に非表示ナイーブな臨床所見が本人・家族に見えていた。モニタリングはケアマネ限定、今回の様子・特記は本人に非表示（家族は可）。家族アプリ9b642fa\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">分析個人の公開範囲：モニタリングはケアマネのみ・特記は本人に非表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ナイーブな臨床所見が本人・家族に見えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>モニタリングはケアマネ限定、今回の様子・特記は本人に非表示（家族は可）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9b642fa</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"氏名検索一覧に運動の数値も表示状態・バイタルのみで運動が確認できなかった。各運動項目の記録値を一覧に追加。提供記録35874fe\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">氏名検索一覧に運動の数値も表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">状態・バイタルのみで運動が確認できなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各運動項目の記録値を一覧に追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">35874fe</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"提供記録\" data-text=\"提供記録入力：氏名検索でその月の利用日を全て表示検索しても当日のロスターしか出ず、来所しない人は表示されなかった。その月の利用日を一覧化し、行タップで当日入力へ。提供記録34725e7\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">提供記録入力：氏名検索でその月の利用日を全て表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">検索しても当日のロスターしか出ず、来所しない人は表示されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>その月の利用日を一覧化し、行タップで当日入力へ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">34725e7</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由ランキング：振替側に後から書いた理由も拾う欠席側にしか理由を見に行かず、振替側に追記した理由が集計に反映されなかった。対の振替側レコードの理由も拾って集計。分析10e2b70\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">欠席理由ランキング：振替側に後から書いた理由も拾う</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">欠席側にしか理由を見に行かず、振替側に追記した理由が集計に反映されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>対の振替側レコードの理由も拾って集計。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">10e2b70</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"分析\" data-text=\"欠席理由ランキング：振替の日付表記でなく実際の理由で集計振替の欠席理由が「○月○日へ振替」の文字列丸ごとで集計され、日付が理由として並んでいた。括弧内の実際の理由で集計し、語尾ゆらぎもまとめた。分析bb991c2\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">欠席理由ランキング：振替の日付表記でなく実際の理由で集計</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替の欠席理由が「○月○日へ振替」の文字列丸ごとで集計され、日付が理由として並んでいた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>括弧内の実際の理由で集計し、語尾ゆらぎもまとめた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bb991c2</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"管理局\" data-text=\"管理局から設定したアドオンが巻き戻る不具合を修正読んでから書く構造で連続操作が消え、項目単位の時刻更新も無く店舗端末の保存で巻き戻っていた。cas（楽観ロック）内で完結させ、時刻も更新。管理局a1792d3\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">管理局から設定したアドオンが巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">読んでから書く構造で連続操作が消え、項目単位の時刻更新も無く店舗端末の保存で巻き戻っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>CAS（楽観ロック）内で完結させ、時刻も更新。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1792d3</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"各種設定\" data-text=\"単位欄の既定値を廃止し、例示が見切れないよう幅を拡大個別運動の追加行に既定値『回』が入り、単位の違う種目でも残っていた。例示も見切れていた。既定値を廃止して例示表示に。入力欄の幅を拡大。各種設定99bc709\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">単位欄の既定値を廃止し、例示が見切れないよう幅を拡大</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個別運動の追加行に既定値『回』が入り、単位の違う種目でも残っていた。例示も見切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>既定値を廃止して例示表示に。入力欄の幅を拡大。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">99bc709</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"提供記録は空欄なのに連絡帳に古いバイタルが出る不具合を修正派生値（プレーンのバイタル）を独立にマージし、非空優先のため一度入った値が消せなかった。マージ後にam/pmから射影し直し、空欄なら空欄に。同期5f906e8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">提供記録は空欄なのに連絡帳に古いバイタルが出る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">派生値（プレーンのバイタル）を独立にマージし、非空優先のため一度入った値が消せなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マージ後にAM/PMから射影し直し、空欄なら空欄に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f906e8</span></span></div>\n    </article>\n    <article class=\"row k-imp\" data-kind=\"imp\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"認定有効期間だけの更新も変更履歴に残す値が同じで期間だけ更新した場合が履歴に残らなかった。開始日が変われば「認定更新」として履歴に記録（3経路統一）。利用者マスタeea97e5\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">認定有効期間だけの更新も変更履歴に残す</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">値が同じで期間だけ更新した場合が履歴に残らなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日が変われば「認定更新」として履歴に記録（3経路統一）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eea97e5</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"同期\" data-text=\"書類削除を1回で確定・次回予定は編集した項目だけ保存書類削除がpullで復活。次回予定は全員分の計算値が書き込まれ全員が変更済みになっていた。個人ファイル表示中はpull停止＋墓石尊重。次回予定は変更項目のみ保存。同期b4a3a62\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">書類削除を1回で確定・次回予定は編集した項目だけ保存</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">書類削除がpullで復活。次回予定は全員分の計算値が書き込まれ全員が変更済みになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個人ファイル表示中はpull停止＋墓石尊重。次回予定は変更項目のみ保存。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4a3a62</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"連絡帳\" data-text=\"連絡帳の次回予定：欠席の日を飛ばし振替を優先月間シフトのみ見て提供記録の欠席を見ておらず、欠席日のまま表示されていた。提供記録を優先し、欠席は飛ばし振替を優先。連絡帳bffc945\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">連絡帳の次回予定：欠席の日を飛ばし振替を優先</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間シフトのみ見て提供記録の欠席を見ておらず、欠席日のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録を優先し、欠席は飛ばし振替を優先。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bffc945</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"各種設定の変更が4秒後に巻き戻る不具合を修正クラウド取得（pull）が丸ごと置換で、保存完了前の4秒ポーリングが古い値で上書きしていた。設定を項目単位の時刻で保持し、他端末の変更は潰さない。同期b907b77\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">各種設定の変更が4秒後に巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド取得（pull）が丸ごと置換で、保存完了前の4秒ポーリングが古い値で上書きしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>設定を項目単位の時刻で保持し、他端末の変更は潰さない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b907b77</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"変更履歴タブが開けないエラーを修正（info is not defined）アイコンを未importで使用し、タブを開くと画面全体がエラーになった。import済みアイコンに差し替え。全jsxの未importを機械検査。利用者マスタ5f48438\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">変更履歴タブが開けないエラーを修正（Info is not defined）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アイコンを未importで使用し、タブを開くと画面全体がエラーになった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>import済みアイコンに差し替え。全JSXの未importを機械検査。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f48438</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"利用者マスタ\" data-text=\"介護度/負担割合/ケアマネの変更履歴を入力1か所から自動記録直接編集しても変更履歴・支援経過表に反映されず、二重入力が同期漏れの温床だった。入力起点を基本情報に統一し、履歴と支援経過表へ自動記録。利用者マスタe8fe1de\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">介護度/負担割合/ケアマネの変更履歴を入力1か所から自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直接編集しても変更履歴・支援経過表に反映されず、二重入力が同期漏れの温床だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>入力起点を基本情報に統一し、履歴と支援経過表へ自動記録。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e8fe1de</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"1\" data-area=\"同期\" data-text=\"書類（保険証/負担割合証）の削除が復活する不具合を修正id単位の和集合マージで削除が表現できず、クラウドの残存で必ず復活していた。墓石（削除記録）を導入し、両端末で合算して復活を防止。同期3843f08\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">書類（保険証/負担割合証）の削除が復活する不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">id単位の和集合マージで削除が表現できず、クラウドの残存で必ず復活していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>墓石（削除記録）を導入し、両端末で合算して復活を防止。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3843f08</span></span></div>\n    </article>\n    <article class=\"row k-bug\" data-kind=\"bug\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書：印刷の行高さ・列幅を修正、入力を自動化セル書式のpre-wrapで改行が余白として描画され行が異常に高く、列幅指定も効いていなかった。書式を分離し、colgroupで列幅を効かせ、入力の自動化を追加。計画書75dbd58\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">通所介護計画書：印刷の行高さ・列幅を修正、入力を自動化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">セル書式のpre-wrapで改行が余白として描画され行が異常に高く、列幅指定も効いていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>書式を分離し、colgroupで列幅を効かせ、入力の自動化を追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">75dbd58</span></span></div>\n    </article>\n    <article class=\"row k-feat\" data-kind=\"feat\" data-crit=\"0\" data-area=\"計画書\" data-text=\"通所介護計画書を厚労省 別紙様式3-4 準拠に刷新独自レイアウトで公的様式と構造が違い、a4に収まっていなかった。別紙様式3-4準拠に作り直し、a4 1枚で使い切る構成に。計画書e60fc54\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">通所介護計画書を厚労省 別紙様式3-4 準拠に刷新</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">独自レイアウトで公的様式と構造が違い、A4に収まっていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>別紙様式3-4準拠に作り直し、A4 1枚で使い切る構成に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e60fc54</span></span></div>\n    </article>\n  </div>\n  <section class=\"block\"><h2>未対応・今後の予定</h2><p class=\"lead\">まだ着手していない、または継続中の項目です。優先度は事業インパクト順。</p><div class=\"todo\" id=\"todo\">\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>操作ログ同期の第2段（受信適用と旧方式の凍結）</b><span>現在は第1段＝「送信のみ」。診断ログで ops-queued→ops-acked が安定して出ることを確認できたら、OPLOG_APPLY と OPLOG_FROZEN_KEYS を有効にして切替を完了する。その後フェーズ5（DB側での操作ログ畳み込みと刈り取り）を追加する。</span></div><span class=\"prio\">優先度：最優先</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>認証基盤の是正（Supabase Auth 未使用）</b><span>職員ログインが staff テーブルへのSELECT照合のみでJWTを発行しておらず、全アクセスがanonロール。anon keyはJSバンドルから誰でも取得できるため、RLSを書いても店舗ごとの分離をDB側で強制できない。介護記録は要配慮個人情報にあたるため、同期刷新の完了後に着手する（放置ではなく延期）。</span></div><span class=\"prio\">優先度：高（同期刷新の次）</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>実績記録票のCSV出力 → 格安/無料の請求ソフトへ連携</b><span>収益に最短で効く本命。連携先ソフトのCSV形式が分かれば着手可能。</span></div><span class=\"prio\">優先度：最優先</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>国保連請求データのCSV生成</b><span>介護給付費請求書等インターフェース仕様書（最新版）に準拠して生成。テスト伝送での検証が必須。</span></div><span class=\"prio\">優先度：高</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>LIFE加算のCSV出力・提出</b><span>LIFEの公式CSV連携仕様に沿って出力。実データでのアップロード検証が必要。</span></div><span class=\"prio\">優先度：高</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>モニタリング自動FAX（丸投げ君 代替）の仕上げ</b><span>FAX API・モニタリング表は実装済み。運用の詰めを残す。</span></div><span class=\"prio\">優先度：中</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>ケアプラン写真/PDFの取り込み → 計画書へ転記</b><span>OCR/貼り付けで目標以外の転記を省力化する構想。</span></div><span class=\"prio\">優先度：中</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>勤務表を日誌データから自動作成</b><span>手入力に加え、日誌の出勤・送迎・記録者から実績を自動生成。</span></div><span class=\"prio\">優先度：低</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>計画書の残作業（個別3-3のカレンダー化 等）</b><span>通所で入れた一時保存・カレンダーを個別機能訓練計画書にも展開。</span></div><span class=\"prio\">優先度：中</span></div>\n    </div></section>\n  <section class=\"block\"><h2>請求・LIFE実装に必要な資料</h2><p class=\"lead\">実績→請求／LIFE加算の実装を正確に進めるために、そろえていただきたい資料です。</p><div class=\"docs\" id=\"docs\">\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">1</span>介護給付費請求 CSVインターフェース仕様書</p><ul><li>国保中央会が定める請求データの公式仕様（最新版）</li><li>明細書・給付管理票のレコード様式</li><li>エラーコード一覧</li></ul><p class=\"note\">これがあれば「つむぎのどのデータをどう並べるか」を具体設計できます。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">2</span>LIFE CSV連携仕様書</p><ul><li>厚労省/LIFEが公開するCSVレイアウト</li><li>科学的介護推進・個別機能訓練加算 の項目定義</li><li>コード表（評価区分・選択肢の数値）</li></ul><p class=\"note\">LIFEは細部が厳格。実データでのアップロード検証を前提に。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">3</span>現行ソフトの出力サンプル</p><ul><li>カイポケ：実績記録票・請求明細書・給付管理票のPDF</li><li>マルットライフ：LIFE提出用CSV/PDF</li><li>丸投げ君：モニタリングFAXの送信様式</li></ul><p class=\"note\">項目を合わせる基準になります。個人情報は伏せた見本で十分です。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">4</span>連携先の請求ソフト情報</p><ul><li>採用予定の格安/無料 請求ソフト名</li><li>そのソフトが取り込めるCSVの形式・項目</li><li>（あれば）取り込みマニュアル</li></ul><p class=\"note\">連携先が決まればCSVをその形式に合わせて出力します。</p></div>\n    </div></section>\n  <footer>この台帳は開発時のコミット記録（Git）から生成しています。各行末尾の英数字はコミットIDで、変更内容の実体と1対1で対応します。「重大」はデータの消失・巻き戻りに関わる不具合です。</footer>\n</div>\n<script>\n(function(){try{\n  var rows=[].slice.call(document.querySelectorAll('#ledger .row')),cl=document.getElementById('count-line');\n  var st={mode:'all',area:'all',q:''};\n  function match(r){var m=st.mode;var okM=(m==='all')?true:(m==='crit'?r.getAttribute('data-crit')==='1':r.getAttribute('data-kind')===m);return okM&&(st.area==='all'||r.getAttribute('data-area')===st.area)&&(st.q===''||(r.getAttribute('data-text')||'').indexOf(st.q)>=0);}\n  function apply(){var n=0;rows.forEach(function(r){var ok=match(r);r.style.display=ok?'':'none';if(ok)n++;});if(cl)cl.textContent='表示 '+n+' 件 ／ 全 '+rows.length+' 件';[].forEach.call(document.querySelectorAll('[data-mode]'),function(el){el.setAttribute('aria-pressed',el.getAttribute('data-mode')===st.mode?'true':'false');});}\n  function setMode(m){st.mode=(st.mode===m&&m!=='all')?'all':m;apply();}\n  [].forEach.call(document.querySelectorAll('[data-mode]'),function(el){el.addEventListener('click',function(){setMode(el.getAttribute('data-mode'));});});\n  var ac=document.getElementById('area-chips');ac&&ac.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-area]');if(!b)return;st.area=b.getAttribute('data-area');[].forEach.call(ac.children,function(c){c.setAttribute('aria-pressed',c===b?'true':'false');});apply();});\n  var q=document.getElementById('q');q&&q.addEventListener('input',function(e){st.q=(e.target.value||'').toLowerCase();apply();});\n  apply();\n}catch(err){}})();\n</script>\n\n</body>\n</html>\n";
export default function handler(req, res) {
  const USER = process.env.CHANGELOG_USER || 'tsumugi';
  const PASS = process.env.CHANGELOG_PASS || 'hennkoukiroku';
  const h = req.headers.authorization || '';
  let ok = false;
  if (h.startsWith('Basic ')) { try { const dec = Buffer.from(h.slice(6),'base64').toString('utf8'); const i = dec.indexOf(':'); if (i!==-1 && dec.slice(0,i)===USER && dec.slice(i+1)===PASS) ok=true; } catch(e){} }
  if (!ok) { res.setHeader('WWW-Authenticate','Basic realm="tsumugi", charset="UTF-8"'); res.setHeader('content-type','text/plain; charset=utf-8'); res.status(401).send('認証が必要です / Authentication required'); return; }
  res.setHeader('content-type','text/html; charset=utf-8'); res.setHeader('cache-control','no-store'); res.setHeader('x-robots-tag','noindex, nofollow, noarchive'); res.status(200).send(HTML);
}
